  `kajiulang` enum('15 menit setelah intervensi obat injeksi','1 jam setelah intervensi obat oral','1x/shif bila skor nyeri 1-3','Setiap 3 jam bila skor 4-6','Setiap 1 jam bila skor nyeri 7-10','Di hentikan bila skor 0') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `nip` varchar(20) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
