-- ----------------------------
-- Table structure for billing
-- ----------------------------
DROP TABLE IF EXISTS `billing`;
CREATE TABLE `billing`  (
  `noindex` int NOT NULL,
  `no_rawat` varchar(17) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `tgl_byr` date NULL DEFAULT NULL,
  `no` varchar(50) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `nm_perawatan` varchar(200) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `pemisah` char(1) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `biaya` double NOT NULL,
  `jumlah` double NOT NULL,
  `tambahan` double NOT NULL,
  `totalbiaya` double NOT NULL,
  `status` enum('Laborat','Radiologi','Operasi','Obat','Ranap Dokter','Ranap Dokter Paramedis','Ranap Paramedis','Ralan Dokter','Ralan Dokter Paramedis','Ralan Paramedis','Tambahan','Potongan','Administrasi','Kamar','-','Registrasi','Harian','Service','TtlObat','TtlRanap Dokter','TtlRanap Paramedis','TtlRalan Dokter','TtlRalan Paramedis','TtlKamar','Dokter','Perawat','TtlTambahan','Retur Obat','TtlRetur Obat','Resep Pulang','TtlResep Pulang','TtlPotongan','TtlLaborat','TtlOperasi','TtlRadiologi','Tagihan') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  INDEX `no_rawat`(`no_rawat` ASC) USING BTREE,
  INDEX `status`(`status` ASC) USING BTREE,
  INDEX `totalbiaya`(`totalbiaya` ASC) USING BTREE,
  INDEX `nm_perawatan`(`nm_perawatan` ASC) USING BTREE,
  INDEX `tgl_byr`(`tgl_byr` ASC) USING BTREE,
  INDEX `no`(`no` ASC) USING BTREE,
  INDEX `pemisah`(`pemisah` ASC) USING BTREE,
  INDEX `biaya`(`biaya` ASC) USING BTREE,
  INDEX `jumlah`(`jumlah` ASC) USING BTREE,
  INDEX `tambahan`(`tambahan` ASC) USING BTREE,
  CONSTRAINT `billing_ibfk_1` FOREIGN KEY (`no_rawat`) REFERENCES `reg_periksa` (`no_rawat`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE = InnoDB CHARACTER SET = latin1 COLLATE = latin1_swedish_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for billing_header
-- ----------------------------
DROP TABLE IF EXISTS `billing_header`;
CREATE TABLE `billing_header`  (
  `id_billing` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `no_rawat` varchar(17) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `tgl_byr` date NULL DEFAULT NULL,
  `total_item` int UNSIGNED NOT NULL DEFAULT 0,
  `total_tagihan` double NOT NULL DEFAULT 0,
  `status` enum('Draft','Tagihan','Pulang','Cancelled','Merge','Split','Update') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'Tagihan',
  `created_at` datetime(6) NOT NULL DEFAULT current_timestamp(6),
  `created_by` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'system',
  `updated_at` datetime(6) NOT NULL DEFAULT current_timestamp(6) ON UPDATE CURRENT_TIMESTAMP(6),
  `updated_by` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'system',
  PRIMARY KEY (`id_billing`) USING BTREE,
  INDEX `idx_billing_header_lookup`(`no_rawat` ASC, `tgl_byr` ASC) USING BTREE,
  INDEX `idx_billing_header_updated`(`updated_at` ASC) USING BTREE,
  INDEX `idx_billing_header_status`(`status` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = Dynamic;

