  INDEX `id_jenis`(`id_jenis` ASC) USING BTREE,
  INDEX `nama_barang`(`nama_barang` ASC) USING BTREE,
  INDEX `jml_barang`(`jml_barang` ASC) USING BTREE,
  INDEX `thn_produksi`(`thn_produksi` ASC) USING BTREE,
