  `diagnosa_postop` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `status_asa` enum('1','2','3','4','5','E') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `karena` varchar(40) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `premedikasi` varchar(500) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `ttv_premedikasi_td` varchar(8) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `ttv_premedikasi_rr` varchar(5) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `ttv_premedikasi_hr` varchar(5) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `ttv_premedikasi_spo2` varchar(5) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `ttv_premedikasi_ekg` varchar(5) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `ttv_premedikasi_suhu` varchar(5) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `ttv_premedikasi_lain` varchar(30) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `lama_operasi` varchar(10) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `lama_anastesi` varchar(10) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `keadaan_umum_bb` varchar(5) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `keadaan_umum_tb` varchar(5) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `keadaan_umum_alergi` varchar(50) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `keadaan_umum_malampathy` varchar(50) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `keadaan_umum_e` varchar(1) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `keadaan_umum_v` varchar(1) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `keadaan_umum_m` varchar(1) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `jenis_anestesi_lokasi` varchar(30) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `jenis_anestesi_sedasi` enum('Ringan','Sedang','Berat') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `jenis_anestesi_regional` enum('Spinal','Epidural','Combined') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `jenis_anestesi_ga_ett` enum('Ya','Tidak') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `jenis_anestesi_ga_ntt` enum('Ya','Tidak') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `jenis_anestesi_ga_ema` enum('Ya','Tidak') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `jenis_anestesi_ga_bm` enum('Ya','Tidak') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `posisi` varchar(40) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `perdarahan` varchar(40) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `urine` varchar(40) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `komplikasi` varchar(40) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `ekstubasi` varchar(40) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `jumlah_pack` varchar(10) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `dipindahkan_ke` varchar(40) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `serah_terima_pasien` enum('RR','ICU/ICCU','NICU/PICU','ODC') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `catatan` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `nip_recovery_room` varchar(20) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  PRIMARY KEY (`no_rawat`, `mulai`) USING BTREE,
  INDEX `operator1`(`operator1` ASC) USING BTREE,
  INDEX `operator2`(`operator2` ASC) USING BTREE,
  INDEX `dokter_anestesi`(`dokter_anestesi` ASC) USING BTREE,
  INDEX `asisten_operator`(`asisten_operator` ASC) USING BTREE,
  INDEX `penata_anestesi`(`penata_anestesi` ASC) USING BTREE,
  INDEX `onloop`(`onloop` ASC) USING BTREE,
  INDEX `nip_recovery_room`(`nip_recovery_room` ASC) USING BTREE,
  CONSTRAINT `laporan_anestesi_ibfk_1` FOREIGN KEY (`operator1`) REFERENCES `dokter` (`kd_dokter`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `laporan_anestesi_ibfk_2` FOREIGN KEY (`operator2`) REFERENCES `dokter` (`kd_dokter`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `laporan_anestesi_ibfk_3` FOREIGN KEY (`dokter_anestesi`) REFERENCES `dokter` (`kd_dokter`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `laporan_anestesi_ibfk_4` FOREIGN KEY (`asisten_operator`) REFERENCES `petugas` (`nip`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `laporan_anestesi_ibfk_5` FOREIGN KEY (`penata_anestesi`) REFERENCES `petugas` (`nip`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `laporan_anestesi_ibfk_6` FOREIGN KEY (`onloop`) REFERENCES `petugas` (`nip`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `laporan_anestesi_ibfk_7` FOREIGN KEY (`nip_recovery_room`) REFERENCES `petugas` (`nip`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE = InnoDB CHARACTER SET = latin1 COLLATE = latin1_swedish_ci ROW_FORMAT = DYNAMIC;

