-- Table structure for penilaian_psikologi
-- ----------------------------
DROP TABLE IF EXISTS `penilaian_psikologi`;
CREATE TABLE `penilaian_psikologi`  (
  `no_rawat` varchar(17) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `tanggal` datetime NOT NULL,
  `nip` varchar(20) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `anamnesis` enum('Autoanamnesis','Alloanamnesis') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `dikirim_dari` enum('Ruang Rawat','Poliklinik','Rehabilitasi','After Care','Dokter') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `tujuan_pemeriksaan` enum('Klinik','Bimbingan','Forensik') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `ket_anamnesis` text CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `rupa` enum('Tampan','Buruk','Menarik','Memuakkan','Biasa') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `bentuk_tubuh` enum('Sangat Tinggi','Sangat Pendek','Sangat Kurus','Sangat Gemuk','Tinggi','Sedang','Atletik','Pendek','Langsing','Gemuk') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `tindakan` enum('Sopan','Tidak Sopan','Kurang Tahu Aturan','Canggung','Bebas','Tegas','Garang','Percaya Diri','Tertekan','Ragu-Ragu','Pasti','Kaku','Ceroboh','Dingin','Malu-Malu') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `pakaian` enum('Rapi','Serampangan','Terpelihara','Tidak Terpelihara','Teratur','Tidak Rapi','Sederhana','Biasa','Bersih','Kotor') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `ekspresi` enum('Sangat Mudah','Hati-Hati Dan Membatasi Diri','Sukar Mencari Kata-Kata','Mudah','Terbuka') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `berbicara` enum('Tenang','Acuh Tak Acuh','Gugup','Lancar','Ribut Dengan Banyak Gerak dan Isyarat') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `penggunaan_kata` enum('Ramah','Dibuat-Buat','Dengan Tekanan Suara','Terpengaruh Bahasa Daerah','Disertai Dengan Istilah Bahasa Asing') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `ciri_menyolok` varchar(500) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `hasil_psikotes` text CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `kepribadian` text CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `psikodinamika` text CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `kesimpulan_psikolog` text CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  PRIMARY KEY (`no_rawat`) USING BTREE,
  INDEX `nip`(`nip` ASC) USING BTREE,
  CONSTRAINT `penilaian_psikologi_ibfk_1` FOREIGN KEY (`no_rawat`) REFERENCES `reg_periksa` (`no_rawat`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `penilaian_psikologi_ibfk_2` FOREIGN KEY (`nip`) REFERENCES `petugas` (`nip`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE = InnoDB CHARACTER SET = latin1 COLLATE = latin1_swedish_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for penilaian_risiko_dekubitus
-- ----------------------------
DROP TABLE IF EXISTS `penilaian_risiko_dekubitus`;
CREATE TABLE `penilaian_risiko_dekubitus`  (
  `no_rawat` varchar(17) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `tanggal` datetime NOT NULL,
  `kondisi_fisik` enum('Baik','Sedang','Buruk','Sangat Buruk') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `kondisi_fisik_nilai` tinyint NULL DEFAULT NULL,
  `status_mental` enum('Sadar','Apatis','Bingung','Stupor') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `status_mental_nilai` tinyint NULL DEFAULT NULL,
  `aktifitas` enum('Jalan Sendiri','Jalan Dengan Bantuan','Kursi Roda','Di Tempat Tidur') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `aktifitas_nilai` tinyint NULL DEFAULT NULL,
  `mobilitas` enum('Bebas Bergerak','Agar Terbatas','Sangat Terbatas','Tidak Mampu Bergerak') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `mobilitas_nilai` tinyint NULL DEFAULT NULL,
  `inkontinensia` enum('Kontinen','Kadang-kadang Inkontinensia Urine','Selalu Inkontenesia Urine','Inkontinensia Alvi Dan Urine') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `inkontinensia_nilai` tinyint NULL DEFAULT NULL,
  `totalnilai` tinyint NULL DEFAULT NULL,
  `kategorinilai` enum('Risiko Rendah','Risiko Sedang','Risiko Tinggi') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `nip` varchar(20) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  PRIMARY KEY (`no_rawat`, `tanggal`) USING BTREE,
  INDEX `nip`(`nip` ASC) USING BTREE,
  CONSTRAINT `penilaian_risiko_dekubitus_ibfk_1` FOREIGN KEY (`no_rawat`) REFERENCES `reg_periksa` (`no_rawat`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `penilaian_risiko_dekubitus_ibfk_2` FOREIGN KEY (`nip`) REFERENCES `petugas` (`nip`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE = InnoDB CHARACTER SET = latin1 COLLATE = latin1_swedish_ci ROW_FORMAT = DYNAMIC;

