-- Table structure for penilaian_tambahan_geriatri
-- ----------------------------
DROP TABLE IF EXISTS `penilaian_tambahan_geriatri`;
CREATE TABLE `penilaian_tambahan_geriatri`  (
  `no_rawat` varchar(17) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `tanggal` datetime NOT NULL,
  `nik` varchar(20) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `asal_masuk` enum('IGD','Kamar Bersalin','Klinik') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `kondisi_masuk` enum('Mandiri','Kursi Roda','Dipapah','Tempat Tidur') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `keterangan_kondisi_masuk` varchar(50) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `anamnesis` enum('Autoanamnesis','Alloanamnesis') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `diagnosa_medis` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `riwayat_immuno_telinga` enum('Ya','Tidak') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `riwayat_immuno_sinus` enum('Ya','Tidak') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `riwayat_immuno_antibiotik` enum('Ya','Tidak') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `riwayat_immuno_pneumonia` enum('Ya','Tidak') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `riwayat_immuno_abses` enum('Ya','Tidak') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `riwayat_immuno_sariawan` enum('Ya','Tidak') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `riwayat_immuno_memerlukan_antibiotik` enum('Ya','Tidak') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `riwayat_immuno_infeksi_dalam` enum('Ya','Tidak') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `riwayat_immuno_immunodefisiensi_primer` enum('Ya','Tidak') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `riwayat_immuno_jenis_kangker` enum('Ya','Tidak') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `riwayat_immuno_infeksi_oportunistik` enum('Ya','Tidak') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `pola_aktifitas_tidur` enum('TAK','Insomnia','Lainnya') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `keterangan_pola_aktifitas_tidur` varchar(50) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `pola_aktifitas_obat_tidur` enum('Tidak','Ya') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `keterangan_pola_aktifitas_obat_tidur` varchar(50) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `pola_aktifitas_olahraga` enum('Tidak','Ya') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `keterangan_pola_aktifitas_olahraga` varchar(50) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `kualitas_hidup_mobilitas` enum('Tidak Mempunyai Masalah Untuk Berjalan','Ada Masalah Untuk Berjalan','Hanya Mampu Berbaring') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `kualitas_hidup_perawatan_diri` enum('Tidak Mempunyai Kesulitan Dalam Perawatan Diri Sendiri','Mengalami Kesulitan Untuk Membasuh Badan, Mandi Atau Berpakaian','Tidak Mampu Membasuh Badan, Mandi/Berpakaian Sendiri') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `kualitas_hidup_aktifitas_seharihari` enum('Tak Mempunyai Kesulitan Dalam Melaksanakan Kegiatan Sehari-hari','Mempunyai Keterbatasan Dalam Melaksanakan Kegiatan Sehari-hari','Tak Mampu Melaksanakan Kegiatan Sehari-hari') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `kualitas_hidup_rasa_nyeri` enum('Tidak Mempunyai Keluhan Rasa Nyeri Atau Rasa Tak Nyaman','Suka Merasakan Agak Nyeri/Agak Kurang Nyaman','Menderita Karena Keluhan Rasa Nyeri/Tidak Nyaman') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `skala_nyeri` enum('0 - Tidak Nyeri','2 - Dapat Ditoleransi(Aktifitas Tidak Tergangu)','4 - Dapat Ditoleransi(Beberapa Aktifitas Sedikit Terganggu)','5 - Tidak Dapat Ditoleransi(Masih Bisa Menggunakan Telp, Menonton TV/Membaca)','6 - Tidak Dapat Ditoleransi(Tidak Bisa Menggunakan Telp, Menonton TV/Membaca)','8 - Tidak Dapat Ditoleransi(Masih Bisa Berbicara Kerenya Nyeri)','10 - Tidak Dapat Ditoleransi(Tidak Bisa Berbicara Kerenya Nyeri)') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  PRIMARY KEY (`no_rawat`) USING BTREE,
  INDEX `kd_dokter`(`nik` ASC) USING BTREE,
  CONSTRAINT `penilaian_tambahan_geriatri_ibfk_1` FOREIGN KEY (`no_rawat`) REFERENCES `reg_periksa` (`no_rawat`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `penilaian_tambahan_geriatri_ibfk_2` FOREIGN KEY (`nik`) REFERENCES `pegawai` (`nik`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE = InnoDB CHARACTER SET = latin1 COLLATE = latin1_swedish_ci ROW_FORMAT = DYNAMIC;

