  `dinamis_frustasi_agitasi` enum('Ya','Tidak','Tidak Tahu') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `dinamis_skorfrustasi_agitasi` tinyint NULL DEFAULT NULL,
  `dinamis_kesenangan_kekerasan` enum('Ya','Tidak','Tidak Tahu') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `dinamis_skorkesenangan_kekerasan` tinyint NULL DEFAULT NULL,
