DROP TABLE IF EXISTS `penilaian_ulang_nyeri`;
CREATE TABLE `penilaian_ulang_nyeri`  (
  `no_rawat` varchar(17) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
