-- ----------------------------
-- Table structure for rsub2_dokumen
-- ----------------------------
DROP TABLE IF EXISTS `rsub2_dokumen`;
CREATE TABLE `rsub2_dokumen`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `no_rawat` varchar(17) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `no_rkm_medis` varchar(15) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `nik` varchar(20) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `kd_jenis` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `jenis_persetujuan` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `versi_dokumen` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `nama_penandatangan` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `hubungan_penandatangan` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `data_isian` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL,
  `isi_dokumen` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `disetujui_at` timestamp NOT NULL DEFAULT current_timestamp ON UPDATE CURRENT_TIMESTAMP,
  `selesai_at` timestamp NULL DEFAULT NULL,
  `pdf_path` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `khanza_no_surat` varchar(20) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `didaftarkan_at` timestamp NULL DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `rsub2_dokumen_no_rawat_index`(`no_rawat` ASC) USING BTREE,
  INDEX `rsub2_dokumen_no_rkm_medis_index`(`no_rkm_medis` ASC) USING BTREE,
  INDEX `rsub2_dokumen_nik_index`(`nik` ASC) USING BTREE,
  INDEX `rsub2_dokumen_kd_jenis_index`(`kd_jenis` ASC) USING BTREE,
  INDEX `rsub2_dokumen_selesai_at_index`(`selesai_at` ASC) USING BTREE,
  INDEX `rsub2_dokumen_didaftarkan_at_index`(`didaftarkan_at` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 8 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for rsub2_jenis_dokumen
-- ----------------------------
DROP TABLE IF EXISTS `rsub2_jenis_dokumen`;
CREATE TABLE `rsub2_jenis_dokumen`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `kd_jenis` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `slug` varchar(60) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `nama_jenis` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `no_formulir` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `versi` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `keterangan` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `kode_berkas` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `kd_poli` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL,
  `status_lanjut` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `perlu_foto` tinyint(1) NOT NULL DEFAULT 1,
  `aktif` tinyint(1) NOT NULL DEFAULT 1,
  `urutan` smallint UNSIGNED NOT NULL DEFAULT 99,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `rsub2_jenis_dokumen_kd_jenis_unique`(`kd_jenis` ASC) USING BTREE,
  UNIQUE INDEX `rsub2_jenis_dokumen_slug_unique`(`slug` ASC) USING BTREE,
  INDEX `rsub2_jenis_dokumen_aktif_urutan_index`(`aktif` ASC, `urutan` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 13 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for rsub2_tanda_tangan
-- ----------------------------
DROP TABLE IF EXISTS `rsub2_tanda_tangan`;
CREATE TABLE `rsub2_tanda_tangan`  (
  `id` bigint UNSIGNED NOT NULL AUTO_INCREMENT,
  `dokumen_id` bigint UNSIGNED NOT NULL,
  `peran` varchar(40) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `nama` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `hubungan` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `nik` varchar(20) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `foto_path` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `signature_path` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `signed_at` timestamp NOT NULL DEFAULT current_timestamp ON UPDATE CURRENT_TIMESTAMP,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE INDEX `rsub2_tanda_tangan_dokumen_id_peran_unique`(`dokumen_id` ASC, `peran` ASC) USING BTREE,
  CONSTRAINT `rsub2_tanda_tangan_dokumen_id_foreign` FOREIGN KEY (`dokumen_id`) REFERENCES `rsub2_dokumen` (`id`) ON DELETE CASCADE ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 16 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for rtl_ralan
-- ----------------------------
DROP TABLE IF EXISTS `rtl_ralan`;
CREATE TABLE `rtl_ralan`  (
  `no_rawat` varchar(17) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `rtl` varchar(50) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `tgl_kontrol` date NOT NULL DEFAULT '0000-00-00',
  `kd_dokter` varchar(30) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `kd_poli` varchar(30) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `catatan` varchar(255) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `catatan2` varchar(255) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `status` enum('0','1') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT '1',
  PRIMARY KEY (`no_rawat`) USING BTREE,
  INDEX `no_rawat`(`no_rawat` ASC) USING BTREE,
  INDEX `kdpoli`(`kd_poli` ASC) USING BTREE,
  INDEX `kddokter`(`kd_dokter` ASC) USING BTREE,
  CONSTRAINT `rtl_ralan_ibfk_1` FOREIGN KEY (`kd_poli`) REFERENCES `poliklinik` (`kd_poli`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `rtl_ralan_ibfk_2` FOREIGN KEY (`no_rawat`) REFERENCES `reg_periksa` (`no_rawat`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `rtl_ralan_ibfk_3` FOREIGN KEY (`kd_dokter`) REFERENCES `dokter` (`kd_dokter`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE = InnoDB CHARACTER SET = latin1 COLLATE = latin1_swedish_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for ruang_audit_kepatuhan
-- ----------------------------
DROP TABLE IF EXISTS `ruang_audit_kepatuhan`;
CREATE TABLE `ruang_audit_kepatuhan`  (
  `id_ruang` varchar(5) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `nama_ruang` varchar(40) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  PRIMARY KEY (`id_ruang`) USING BTREE,
  INDEX `nama_ruang`(`nama_ruang` ASC) USING BTREE
) ENGINE = InnoDB CHARACTER SET = latin1 COLLATE = latin1_swedish_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for ruang_ok
-- ----------------------------
DROP TABLE IF EXISTS `ruang_ok`;
CREATE TABLE `ruang_ok`  (
  `kd_ruang_ok` varchar(3) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `nm_ruang_ok` varchar(50) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  PRIMARY KEY (`kd_ruang_ok`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = latin1 COLLATE = latin1_swedish_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for rujuk
-- ----------------------------
DROP TABLE IF EXISTS `rujuk`;
CREATE TABLE `rujuk`  (
  `no_rujuk` varchar(40) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `no_rawat` varchar(17) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `rujuk_ke` varchar(150) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `tgl_rujuk` date NULL DEFAULT NULL,
  `keterangan_diagnosa` text CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL,
  `kd_dokter` varchar(20) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `kat_rujuk` enum('-','Bedah','Non Bedah','Kebidanan','Anak') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT 'Bedah',
  `ambulance` enum('-','AGD','SENDIRI','SWASTA') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT 'AGD',
  `keterangan` text CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL,
  `jam` time NULL DEFAULT NULL,
  `level` enum('Level 0','Level 0,5','Level 1','Level 2','Level 3') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT 'Level 0',
  `pen_dokter` enum('-','ACLS','ATLS') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT 'ACLS',
  `pen_perawat` enum('PK 1','PK 2','PK 3') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT 'PK 1',
  `pen_sopir` enum('-','BHD') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT '-',
  `alasan` enum('Ketiadaan Fasilitas dan Sarana','Pemeriksaan Penunjang','Permintaan Pasien/ Keluarga','Membutuhkan Dokter Spesialis/ Sub Spesialis') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT 'Ketiadaan Fasilitas dan Sarana',
  `alat` varchar(200) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT '',
  `penunjang` varchar(200) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT '',
  `kesadaran` enum('Compos Mentis','Gelisah','Delirium','Koma','Somnolen','Sopor') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT 'Compos Mentis',
  `nadi` varchar(20) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `td` varchar(20) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `gcs` varchar(20) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `rr` varchar(20) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `suhu` varchar(20) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `spo` varchar(20) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `alergi` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `obat` varchar(500) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `nip` varchar(20) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `petugas_tujuan` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `telp_tujuan` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `riwayat` varchar(2000) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT '',
  `tb` varchar(50) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT '',
  `bb` varchar(50) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT '',
  INDEX `kd_dokter`(`kd_dokter` ASC) USING BTREE,
  INDEX `no_rawat`(`no_rawat` ASC) USING BTREE,
  INDEX `rujuk_ke`(`rujuk_ke` ASC) USING BTREE,
  CONSTRAINT `rujuk_ibfk_1` FOREIGN KEY (`kd_dokter`) REFERENCES `dokter` (`kd_dokter`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `rujuk_ibfk_2` FOREIGN KEY (`no_rawat`) REFERENCES `reg_periksa` (`no_rawat`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE = InnoDB CHARACTER SET = latin1 COLLATE = latin1_swedish_ci ROW_FORMAT = Dynamic;

-- ----------------------------
-- Table structure for rujuk_masuk
-- ----------------------------
DROP TABLE IF EXISTS `rujuk_masuk`;
CREATE TABLE `rujuk_masuk`  (
  `no_rawat` varchar(17) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '',
  `perujuk` varchar(60) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `alamat` varchar(70) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `no_rujuk` varchar(40) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `jm_perujuk` double NOT NULL,
  `dokter_perujuk` varchar(50) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `kd_penyakit` varchar(10) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `kategori_rujuk` enum('-','Bedah','Non-Bedah','Kebidanan','Anak') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `keterangan` varchar(200) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `no_balasan` varchar(20) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  PRIMARY KEY (`no_rawat`) USING BTREE,
