-- ----------------------------
-- Table structure for satu_sehat_log
-- ----------------------------
DROP TABLE IF EXISTS `satu_sehat_log`;
CREATE TABLE `satu_sehat_log`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `waktu` datetime NOT NULL,
  `modul` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `no_rawat` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '',
  `referensi` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '',
  `http_method` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT NULL,
  `http_status` int NULL DEFAULT 0,
  `status` enum('SUKSES','GAGAL') CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,
  `id_resource` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL DEFAULT '',
  `pesan_error` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `request_json` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  `response_json` mediumtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_waktu`(`waktu` ASC) USING BTREE,
  INDEX `idx_status`(`status` ASC) USING BTREE,
  INDEX `idx_norawat`(`no_rawat` ASC) USING BTREE,
  INDEX `idx_modul`(`modul` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 39865 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_unicode_ci ROW_FORMAT = Dynamic;

