  CONSTRAINT `skrining_nutrisi_dewasa_ibfk_1` FOREIGN KEY (`no_rawat`) REFERENCES `reg_periksa` (`no_rawat`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `skrining_nutrisi_dewasa_ibfk_2` FOREIGN KEY (`nip`) REFERENCES `petugas` (`nip`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE = InnoDB CHARACTER SET = latin1 COLLATE = latin1_swedish_ci ROW_FORMAT = DYNAMIC;

-- ----------------------------
-- Table structure for skrining_nutrisi_lansia
-- ----------------------------
DROP TABLE IF EXISTS `skrining_nutrisi_lansia`;
CREATE TABLE `skrining_nutrisi_lansia`  (
  `no_rawat` varchar(17) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `tanggal` datetime NOT NULL,
  `td` varchar(8) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '',
  `hr` varchar(5) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '',
  `rr` varchar(5) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `suhu` varchar(5) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '',
  `bb` varchar(5) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '',
  `tbpb` varchar(5) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '',
  `spo2` varchar(5) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '',
  `alergi` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '',
  `sg1` enum('Asupan Makan Sangat Berkurang','Asupan Makan Agak Berkurang','Asupan Makan Tidak Berkurang') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `nilai1` enum('0','1','2') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `sg2` enum('Penurunan Berat Badan Lebih Dari 3 Kg','Tidak Tahu','Penurunan Berat Badan Antara 1 Hingga 3 Kg','Tidak Ada Penurunan Berat Badan') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `nilai2` enum('0','1','2','3') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `sg3` enum('Terbatas Dari Tempat Tidur Atau Kursi','Mampu Bangun Dari Tempat Tidur/Kursi Tetapi Tidak Bepergian Keluar Rumah','Dapat Bepergian Keluar Rumah') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `nilai3` enum('0','1','2') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `sg4` enum('Ya','Tidak') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `nilai4` enum('0','1') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `sg5` enum('Depresi Berat Atau Kepikunan Berat','Kepikunan Ringan','Tidak Ada Gangguan Psikologis') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `nilai5` enum('0','1','2') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `sg6` enum('IMT < 19','19 Hingga < 21','21 Hingga < 23','IMT >= 23','Lingkar Betis < 31','Lingkar Betis >= 31') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `nilai6` enum('0','1','2','3') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `total_hasil` tinyint NOT NULL,
  `skor_nutrisi` enum('Status Gizi Normal','Beresiko Malnutrisi','Malnutrisi') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `nip` varchar(20) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  PRIMARY KEY (`no_rawat`) USING BTREE,
  INDEX `nip`(`nip` ASC) USING BTREE,
  CONSTRAINT `skrining_nutrisi_lansia_ibfk_1` FOREIGN KEY (`no_rawat`) REFERENCES `reg_periksa` (`no_rawat`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `skrining_nutrisi_lansia_ibfk_2` FOREIGN KEY (`nip`) REFERENCES `petugas` (`nip`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE = InnoDB CHARACTER SET = latin1 COLLATE = latin1_swedish_ci ROW_FORMAT = DYNAMIC;

