-- ----------------------------
-- Table structure for surat_keteranganhd
-- ----------------------------
DROP TABLE IF EXISTS `surat_keteranganhd`;
CREATE TABLE `surat_keteranganhd`  (
  `no_rawat` varchar(17) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `tanggal` datetime NOT NULL,
  `diagnosautama` enum('Chronic Kidney Disease Stage 5','Acute Kidney Injury','Acute Kidney Injuri Superimposed on Chromic Kidney Disease') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `diagnosasekunder1` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `diagnosasekunder2` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `diagnosasekunder3` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `diagnosasekunder4` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `diagnosasekunder5` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `indikasi` enum('Hemodinamik tidak stabil','Keperluan perioperatif','Ibu hamil Kondisi overhidrasi yang sulit dikendalikan','Pasien dengan berat badan kering > 75 kg','Pasien transplantasi ginjal dengan delayed graft function','Pasien transplantasi ginjal dengan rekasi rejeksi') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `berlaku` enum('1 Bulan','3 Bulan') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `kddokterpj` varchar(20) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `kddoktersup` varchar(20) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  PRIMARY KEY (`no_rawat`, `tanggal`) USING BTREE,
  INDEX `no_rawat`(`no_rawat` ASC) USING BTREE,
  INDEX `surat_keteranganhd_ibfk_2`(`kddokterpj` ASC) USING BTREE,
  INDEX `surat_keteranganhd_ibfk_3`(`kddoktersup` ASC) USING BTREE,
  CONSTRAINT `surat_keteranganhd_ibfk_1` FOREIGN KEY (`no_rawat`) REFERENCES `reg_periksa` (`no_rawat`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `surat_keteranganhd_ibfk_2` FOREIGN KEY (`kddokterpj`) REFERENCES `dokter` (`kd_dokter`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `surat_keteranganhd_ibfk_3` FOREIGN KEY (`kddoktersup`) REFERENCES `dokter` (`kd_dokter`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE = InnoDB CHARACTER SET = latin1 COLLATE = latin1_swedish_ci ROW_FORMAT = Dynamic;

