-- ----------------------------
-- Table structure for surat_kontrol_umum
-- ----------------------------
DROP TABLE IF EXISTS `surat_kontrol_umum`;
CREATE TABLE `surat_kontrol_umum`  (
  `no_surat` varchar(50) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `tahun` year NOT NULL,
  `no_rkm_medis` varchar(15) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `diagnosa` varchar(50) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `terapi` text CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `diet` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `luka` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `ngt` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `lain` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `tunda` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `tanggal_datang` date NULL DEFAULT NULL,
  `tanggal_rujukan` date NOT NULL,
  `no_antrian` varchar(20) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `kd_dokter` varchar(20) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `status` enum('Menunggu','Sudah Periksa','Batal Periksa') CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `kd_poli` varchar(5) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  PRIMARY KEY (`tahun`, `no_antrian`) USING BTREE,
  INDEX `no_rkm_medis`(`no_rkm_medis` ASC) USING BTREE,
  INDEX `kd_dokter`(`kd_dokter` ASC) USING BTREE,
  INDEX `no_surat`(`no_surat` ASC) USING BTREE,
  CONSTRAINT `surat_kontrol_umum_ibfk_1` FOREIGN KEY (`no_rkm_medis`) REFERENCES `pasien` (`no_rkm_medis`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `surat_kontrol_umum_ibfk_2` FOREIGN KEY (`kd_dokter`) REFERENCES `dokter` (`kd_dokter`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE = InnoDB CHARACTER SET = latin1 COLLATE = latin1_swedish_ci ROW_FORMAT = Dynamic;

