-- ----------------------------
-- Table structure for transfer_pasien_antar_ruang
-- ----------------------------
DROP TABLE IF EXISTS `transfer_pasien_antar_ruang`;
CREATE TABLE `transfer_pasien_antar_ruang`  (
  `no_rawat` varchar(17) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `tanggal_masuk` datetime NOT NULL,
  `tanggal_pindah` datetime NULL DEFAULT NULL,
  `asal_ruang` varchar(30) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `ruang_selanjutnya` varchar(30) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `diagnosa_utama` varchar(500) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `diagnosa_sekunder` varchar(100) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `indikasi_pindah_ruang` enum('Kondisi Pasien Stabil','Kondisi Pasien Tidak Ada Perubahan','Kondisi Pasien Memburuk','Fasilitas Kurang Memadai','Fasilitas Butuh Lebih Baik','Tenaga Membutuhkan Yang Lebih Ahli','Tenaga Kurang','Lain-lain') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `keterangan_indikasi_pindah_ruang` varchar(50) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `prosedur_yang_sudah_dilakukan` varchar(800) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `obat_yang_telah_diberikan` varchar(800) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `metode_pemindahan_pasien` enum('Kursi Roda','Tempat Tidur','Brankar') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `peralatan_yang_menyertai` enum('Oksigen Portable','Infus','NGT','Syringe Pump','Suction','Kateter Urin','-') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `keterangan_peralatan_yang_menyertai` varchar(250) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `pemeriksaan_penunjang_yang_dilakukan` varchar(500) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `pasien_keluarga_menyetujui` enum('Ya','Tidak') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `nama_menyetujui` varchar(50) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `hubungan_menyetujui` enum('Kakak','Adik','Saudara','Keluarga','Kakek','Nenek','Orang Tua','Suami','Istri','Penanggung Jawab','Menantu','Ipar','Mertua','-') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `keluhan_utama_sebelum_transfer` varchar(200) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `keadaan_umum_sebelum_transfer` enum('Compos Mentis','Gelisah','Delirium','Koma') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `td_sebelum_transfer` varchar(7) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `nadi_sebelum_transfer` varchar(5) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `rr_sebelum_transfer` varchar(5) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `suhu_sebelum_transfer` varchar(5) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `keluhan_utama_sesudah_transfer` varchar(200) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `keadaan_umum_sesudah_transfer` enum('Compos Mentis','Gelisah','Delirium','Koma') CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `td_sesudah_transfer` varchar(7) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `nadi_sesudah_transfer` varchar(5) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `rr_sesudah_transfer` varchar(5) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `suhu_sesudah_transfer` varchar(5) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  `nip_menyerahkan` varchar(20) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `nip_menerima` varchar(20) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `rencana_yang_akan_dilakukan` varchar(200) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT '',
  PRIMARY KEY (`no_rawat`, `tanggal_masuk`) USING BTREE,
  INDEX `nip_menyerahkan`(`nip_menyerahkan` ASC) USING BTREE,
  INDEX `nip_menerima`(`nip_menerima` ASC) USING BTREE,
  CONSTRAINT `transfer_pasien_antar_ruang_ibfk_1` FOREIGN KEY (`no_rawat`) REFERENCES `reg_periksa` (`no_rawat`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `transfer_pasien_antar_ruang_ibfk_2` FOREIGN KEY (`nip_menyerahkan`) REFERENCES `petugas` (`nip`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `transfer_pasien_antar_ruang_ibfk_3` FOREIGN KEY (`nip_menerima`) REFERENCES `petugas` (`nip`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE = InnoDB CHARACTER SET = latin1 COLLATE = latin1_swedish_ci ROW_FORMAT = DYNAMIC;

