-- ----------------------------
-- Table structure for zzStatuss
-- ----------------------------
DROP TABLE IF EXISTS `zzStatuss`;
CREATE TABLE `zzStatuss`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `waktu` timestamp NOT NULL DEFAULT current_timestamp,
  `waktuu` timestamp NOT NULL DEFAULT current_timestamp ON UPDATE CURRENT_TIMESTAMP,
  `partisi` varchar(250) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '',
  `data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL,
  `vIndekA` varchar(250) CHARACTER SET latin1 COLLATE latin1_swedish_ci GENERATED ALWAYS AS (ifnull(json_unquote(json_extract(`data`,'$.indek.a')),'')) VIRTUAL NULL,
  `vIndekB` varchar(250) CHARACTER SET latin1 COLLATE latin1_swedish_ci GENERATED ALWAYS AS (ifnull(json_unquote(json_extract(`data`,'$.indek.b')),'')) VIRTUAL NULL,
  `vIndekC` varchar(250) CHARACTER SET latin1 COLLATE latin1_swedish_ci GENERATED ALWAYS AS (ifnull(json_unquote(json_extract(`data`,'$.indek.c')),'')) VIRTUAL NULL,
  `vIndekD` varchar(250) CHARACTER SET latin1 COLLATE latin1_swedish_ci GENERATED ALWAYS AS (ifnull(json_unquote(json_extract(`data`,'$.indek.d')),'')) VIRTUAL NULL,
  `vIndekE` varchar(250) CHARACTER SET latin1 COLLATE latin1_swedish_ci GENERATED ALWAYS AS (ifnull(json_unquote(json_extract(`data`,'$.indek.e')),'')) VIRTUAL NULL,
  PRIMARY KEY (`id`, `partisi`) USING BTREE,
  INDEX `vIndekA`(`vIndekA` ASC) USING BTREE,
  INDEX `vIndekB`(`vIndekB` ASC) USING BTREE,
  INDEX `vIndekC`(`vIndekC` ASC) USING BTREE,
  INDEX `vIndekD`(`vIndekD` ASC) USING BTREE,
  INDEX `vIndekE`(`vIndekE` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = latin1 COLLATE = latin1_swedish_ci ROW_FORMAT = Dynamic PARTITION BY LIST COLUMNS (`partisi`)
PARTITIONS 2
(PARTITION `p` ENGINE = InnoDB MAX_ROWS = 0 MIN_ROWS = 0 ,
PARTITION `pKEUJKNKlaimBayar` ENGINE = InnoDB MAX_ROWS = 0 MIN_ROWS = 0 )
;

