-- ----------------------------
-- Table structure for zzzdata_keuangan_copy1
-- ----------------------------
DROP TABLE IF EXISTS `zzzdata_keuangan_copy1`;
CREATE TABLE `zzzdata_keuangan_copy1`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `waktu` timestamp NOT NULL DEFAULT current_timestamp,
  `waktuu` timestamp NOT NULL DEFAULT current_timestamp ON UPDATE CURRENT_TIMESTAMP,
  `status` int NULL DEFAULT 1 COMMENT '0=nonaktif. 1=awal. 2=sudah dilanjutkan',
  `partisi` varchar(250) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '' COMMENT 'biayalayan_hitung=hitung per norawat\r\nbiayalayan_dokterbayar=hitung hr dokter\r\nbiayalayan_grup=biaya per grup',
  `subpartisi` varchar(250) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '',
  `data` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL,
  `cari` varchar(500) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT '',
  `vchra` varchar(250) CHARACTER SET latin1 COLLATE latin1_swedish_ci GENERATED ALWAYS AS (ifnull(json_unquote(json_extract(`data`,'$.indek.chr.a')),'')) VIRTUAL NULL,
  `vchrb` varchar(250) CHARACTER SET latin1 COLLATE latin1_swedish_ci GENERATED ALWAYS AS (ifnull(json_unquote(json_extract(`data`,'$.indek.chr.b')),'')) VIRTUAL NULL,
  `vchrc` varchar(250) CHARACTER SET latin1 COLLATE latin1_swedish_ci GENERATED ALWAYS AS (ifnull(json_unquote(json_extract(`data`,'$.indek.chr.c')),'')) VIRTUAL NULL,
  `vchrd` varchar(250) CHARACTER SET latin1 COLLATE latin1_swedish_ci GENERATED ALWAYS AS (ifnull(json_unquote(json_extract(`data`,'$.indek.chr.d')),'')) VIRTUAL NULL,
  `vchre` varchar(250) CHARACTER SET latin1 COLLATE latin1_swedish_ci GENERATED ALWAYS AS (ifnull(json_unquote(json_extract(`data`,'$.indek.chr.e')),'')) VIRTUAL NULL,
  `vchrf` varchar(250) CHARACTER SET latin1 COLLATE latin1_swedish_ci GENERATED ALWAYS AS (lcase(ifnull(json_unquote(json_extract(`data`,'$.indek.chr.f')),''))) VIRTUAL NULL,
  `vchrg` varchar(250) CHARACTER SET latin1 COLLATE latin1_swedish_ci GENERATED ALWAYS AS (ifnull(json_unquote(json_extract(`data`,'$.indek.chr.g')),'')) VIRTUAL NULL,
  `vchrh` varchar(250) CHARACTER SET latin1 COLLATE latin1_swedish_ci GENERATED ALWAYS AS (ifnull(json_unquote(json_extract(`data`,'$.indek.chr.h')),'')) VIRTUAL NULL,
  `vinta` double GENERATED ALWAYS AS (cast(ifnull(json_unquote(json_extract(`data`,'$.indek.int.a')),0) as double)) VIRTUAL NULL,
  `vintb` double GENERATED ALWAYS AS (cast(ifnull(json_unquote(json_extract(`data`,'$.indek.int.b')),0) as double)) VIRTUAL NULL,
  `vintc` double GENERATED ALWAYS AS (cast(ifnull(json_unquote(json_extract(`data`,'$.indek.int.c')),0) as double)) VIRTUAL NULL,
  `vintd` double GENERATED ALWAYS AS (cast(ifnull(json_unquote(json_extract(`data`,'$.indek.int.d')),0) as double)) VIRTUAL NULL,
  `vinte` double GENERATED ALWAYS AS (cast(ifnull(json_unquote(json_extract(`data`,'$.indek.int.e')),0) as double)) VIRTUAL NULL,
  `vintf` double GENERATED ALWAYS AS (cast(ifnull(json_unquote(json_extract(`data`,'$.indek.int.f')),0) as double)) VIRTUAL NULL,
  `vintg` double GENERATED ALWAYS AS (cast(ifnull(json_unquote(json_extract(`data`,'$.indek.int.g')),0) as double)) VIRTUAL NULL,
  `vinth` double GENERATED ALWAYS AS (cast(ifnull(json_unquote(json_extract(`data`,'$.indek.int.h')),0) as double)) VIRTUAL NULL,
  `vinti` double GENERATED ALWAYS AS (cast(ifnull(json_unquote(json_extract(`data`,'$.indek.int.i')),0) as double)) VIRTUAL NULL,
  `vintj` double GENERATED ALWAYS AS (cast(ifnull(json_unquote(json_extract(`data`,'$.indek.int.j')),0) as double)) VIRTUAL NULL,
  `vdata` date GENERATED ALWAYS AS (ifnull(json_unquote(json_extract(`data`,'$.indek.dat.a')),'0000-00-00')) VIRTUAL NULL,
  `vdatb` date GENERATED ALWAYS AS (ifnull(json_unquote(json_extract(`data`,'$.indek.dat.b')),'0000-00-00')) VIRTUAL NULL,
  `vdatc` date GENERATED ALWAYS AS (ifnull(json_unquote(json_extract(`data`,'$.indek.dat.c')),'0000-00-00')) VIRTUAL NULL,
  `vdatd` date GENERATED ALWAYS AS (ifnull(json_unquote(json_extract(`data`,'$.indek.dat.d')),'0000-00-00')) VIRTUAL NULL,
  `vdate` date GENERATED ALWAYS AS (ifnull(json_unquote(json_extract(`data`,'$.indek.dat.e')),'0000-00-00')) VIRTUAL NULL,
  `vdatf` date GENERATED ALWAYS AS (ifnull(json_unquote(json_extract(`data`,'$.indek.dat.f')),'0000-00-00')) VIRTUAL NULL,
  `vdatg` date GENERATED ALWAYS AS (ifnull(json_unquote(json_extract(`data`,'$.indek.dat.g')),'0000-00-00')) VIRTUAL NULL,
  `vjsna` longtext CHARACTER SET latin1 COLLATE latin1_swedish_ci GENERATED ALWAYS AS (ifnull(json_extract(`data`,'$.indek.jsn.a'),convert(json_array() using utf8mb4))) VIRTUAL NULL,
  `vjsnb` longtext CHARACTER SET latin1 COLLATE latin1_swedish_ci GENERATED ALWAYS AS (ifnull(json_extract(`data`,'$.indek.jsn.b'),convert(json_array() using utf8mb4))) VIRTUAL NULL,
  `vjsnc` longtext CHARACTER SET latin1 COLLATE latin1_swedish_ci GENERATED ALWAYS AS (ifnull(json_extract(`data`,'$.indek.jsn.c'),convert(json_array() using utf8mb4))) VIRTUAL NULL,
  `vjsnd` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin GENERATED ALWAYS AS (ifnull(json_extract(`data`,'$.indek.jsn.d'),convert(json_array() using utf8mb4))) VIRTUAL NULL,
  `vjsnz` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin GENERATED ALWAYS AS (ifnull(json_extract(`data`,'$.indek.jsn.z'),convert(json_array() using utf8mb4))) VIRTUAL NULL,
  PRIMARY KEY (`id`, `partisi`, `subpartisi`) USING BTREE,
  INDEX `id`(`id` ASC) USING BTREE,
  INDEX `partisi`(`partisi` ASC) USING BTREE,
  INDEX `subpartisi`(`subpartisi` ASC) USING BTREE,
  INDEX `status`(`status` ASC) USING BTREE,
  INDEX `cari`(`cari` ASC) USING BTREE,
  INDEX `vinta`(`vinta` ASC) USING BTREE,
  INDEX `vintb`(`vintb` ASC) USING BTREE,
  INDEX `vintc`(`vintc` ASC) USING BTREE,
  INDEX `vintd`(`vintd` ASC) USING BTREE,
  INDEX `vinte`(`vinte` ASC) USING BTREE,
  INDEX `vchra`(`vchra` ASC) USING BTREE,
  INDEX `vchrb`(`vchrb` ASC) USING BTREE,
  INDEX `vchrc`(`vchrc` ASC) USING BTREE,
  INDEX `vchrd`(`vchrd` ASC) USING BTREE,
  INDEX `vchre`(`vchre` ASC) USING BTREE,
  INDEX `vdata`(`vdata` ASC) USING BTREE,
  INDEX `vdatb`(`vdatb` ASC) USING BTREE,
  INDEX `vdatc`(`vdatc` ASC) USING BTREE,
  INDEX `vdatd`(`vdatd` ASC) USING BTREE,
  INDEX `vdate`(`vdate` ASC) USING BTREE,
  INDEX `vchrf`(`vchrf` ASC) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 12050470 CHARACTER SET = latin1 COLLATE = latin1_swedish_ci ROW_FORMAT = Dynamic PARTITION BY LIST COLUMNS (`partisi`)
