DROP TABLE IF EXISTS `zzzrespontaskid`;
CREATE TABLE `zzzrespontaskid`  (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `waktu` timestamp NULL DEFAULT current_timestamp,
  `parameter` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL,
  `respon` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_bin NULL,
  `kode` varchar(250) CHARACTER SET latin1 COLLATE latin1_swedish_ci GENERATED ALWAYS AS (json_value(`parameter`,'$.kodebooking')) VIRTUAL NULL,
  `jenis` varchar(250) CHARACTER SET latin1 COLLATE latin1_swedish_ci GENERATED ALWAYS AS (case when json_value(`parameter`,'$.jenispasien') is not null then 'AddAntrean' when json_value(`parameter`,'$.taskid') is not null then 'TaskID' else '' end) VIRTUAL NULL,
  `waktu_data` datetime GENERATED ALWAYS AS (case when json_value(`parameter`,'$.tanggalperiksa') is not null then cast(concat(json_value(`parameter`,'$.tanggalperiksa'),' 00:00:00') as datetime) when json_value(`parameter`,'$.taskid') is not null then cast(from_unixtime(left(json_value(`parameter`,'$.waktu'),10)) as datetime) else '0000-00-00 00:00:00' end) VIRTUAL NULL,
  `data1` varchar(250) CHARACTER SET latin1 COLLATE latin1_swedish_ci GENERATED ALWAYS AS (case when json_value(`parameter`,'$.tanggalperiksa') is not null then json_value(`parameter`,'$.jenispasien') when json_value(`parameter`,'$.taskid') is not null then json_value(`parameter`,'$.taskid') else '' end) VIRTUAL NULL,
  `respon_data` varchar(250) CHARACTER SET latin1 COLLATE latin1_swedish_ci GENERATED ALWAYS AS (json_value(`respon`,'$.metadata.message')) VIRTUAL NULL,
  PRIMARY KEY (`id`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 1691877 CHARACTER SET = latin1 COLLATE = latin1_swedish_ci ROW_FORMAT = Dynamic;

