CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `all_detail_jm` AS (select `A`.`no_rawat` AS `no_rawat`,`A`.`no_rm` AS `no_rm`,`A`.`tanggal_masuk` AS `tanggal_masuk`,`A`.`nm_pasien` AS `nm_pasien`,`A`.`kd_dokter` AS `kd_dokter`,`A`.`nm_dokter` AS `nm_dokter`,`A`.`nm_sps` AS `nm_sps`,`A`.`tipe_dokter` AS `tipe_dokter`,`A`.`jasa_medis` AS `jasa_medis` from (select `A`.`no_rawat` AS `no_rawat`,`A`.`no_rkm_medis` AS `no_rm`,`A`.`tgl_registrasi` AS `tanggal_masuk`,`B`.`nm_pasien` AS `nm_pasien`,`C`.`kd_dokter` AS `kd_dokter`,`C`.`nm_dokter` AS `nm_dokter`,`C`.`nm_sps` AS `nm_sps`,`C`.`tipe_dokter` AS `tipe_dokter`,`C`.`jasa_medis` AS `jasa_medis` from ((`reg_periksa` `A` left join `pasien` `B` on(`A`.`no_rkm_medis` = `B`.`no_rkm_medis`)) left join (select `A`.`no_rawat` AS `no_rawat`,`A`.`kd_dokter` AS `kd_dokter`,`B`.`nm_dokter` AS `nm_dokter`,`C`.`nm_sps` AS `nm_sps`,sum(`A`.`tarif_tindakandr`) AS `jasa_medis`,'Dokter IGD/Rawat Jalan/Paramedis' AS `tipe_dokter` from ((`rawat_jl_drpr` `A` left join `dokter` `B` on(`A`.`kd_dokter` = `B`.`kd_dokter`)) left join `spesialis` `C` on(`B`.`kd_sps` = `C`.`kd_sps`)) group by `A`.`no_rawat`,`A`.`kd_dokter`) `C` on(`A`.`no_rawat` = `C`.`no_rawat`)) union select `A`.`no_rawat` AS `no_rawat`,`A`.`no_rkm_medis` AS `no_rm`,`A`.`tgl_registrasi` AS `tanggal_masuk`,`B`.`nm_pasien` AS `nm_pasien`,`C`.`kd_dokter` AS `kd_dokter`,`C`.`nm_dokter` AS `nm_dokter`,`C`.`nm_sps` AS `nm_sps`,`C`.`tipe_dokter` AS `tipe_dokter`,`C`.`jasa_medis` AS `jasa_medis` from ((`reg_periksa` `A` left join `pasien` `B` on(`A`.`no_rkm_medis` = `B`.`no_rkm_medis`)) left join (select `A`.`no_rawat` AS `no_rawat`,`A`.`kd_dokter` AS `kd_dokter`,`B`.`nm_dokter` AS `nm_dokter`,`C`.`nm_sps` AS `nm_sps`,sum(`A`.`tarif_tindakandr`) AS `jasa_medis`,'Dokter IGD/Rawat Jalan/Paramedis' AS `tipe_dokter` from ((`rawat_jl_dr` `A` left join `dokter` `B` on(`A`.`kd_dokter` = `B`.`kd_dokter`)) left join `spesialis` `C` on(`B`.`kd_sps` = `C`.`kd_sps`)) group by `A`.`no_rawat`,`A`.`kd_jenis_prw`,`A`.`kd_dokter`) `C` on(`A`.`no_rawat` = `C`.`no_rawat`)) union select `A`.`no_rawat` AS `no_rawat`,`A`.`no_rkm_medis` AS `no_rm`,`A`.`tgl_registrasi` AS `tanggal_masuk`,`B`.`nm_pasien` AS `nm_pasien`,`C`.`kd_dokter` AS `kd_dokter`,`C`.`nm_dokter` AS `nm_dokter`,`C`.`nm_sps` AS `nm_sps`,`C`.`tipe_dokter` AS `tipe_dokter`,`C`.`jasa_medis` AS `jasa_medis` from ((`reg_periksa` `A` left join `pasien` `B` on(`A`.`no_rkm_medis` = `B`.`no_rkm_medis`)) left join (select `A`.`no_rawat` AS `no_rawat`,`A`.`kd_dokter` AS `kd_dokter`,`B`.`nm_dokter` AS `nm_dokter`,`C`.`nm_sps` AS `nm_sps`,sum(`A`.`tarif_tindakandr`) AS `jasa_medis`,'Dokter IGD/Rawat Jalan/Paramedis' AS `tipe_dokter` from ((`rawat_inap_drpr` `A` left join `dokter` `B` on(`A`.`kd_dokter` = `B`.`kd_dokter`)) left join `spesialis` `C` on(`B`.`kd_sps` = `C`.`kd_sps`)) group by `A`.`no_rawat`,`A`.`kd_dokter`) `C` on(`A`.`no_rawat` = `C`.`no_rawat`)) union select `A`.`no_rawat` AS `no_rawat`,`A`.`no_rkm_medis` AS `No_RM`,`A`.`tgl_registrasi` AS `tanggal_masuk`,`B`.`nm_pasien` AS `nm_pasien`,`C`.`kd_dokter` AS `kd_dokter`,`C`.`nm_dokter` AS `nm_dokter`,`C`.`nm_sps` AS `nm_sps`,`C`.`tipe_dokter` AS `tipe_dokter`,`C`.`jasa_medis` AS `jasa_medis` from ((`reg_periksa` `A` left join `pasien` `B` on(`A`.`no_rkm_medis` = `B`.`no_rkm_medis`)) left join (select `A`.`no_rawat` AS `no_rawat`,`A`.`kd_dokter` AS `kd_dokter`,`B`.`nm_dokter` AS `nm_dokter`,`C`.`nm_sps` AS `nm_sps`,sum(`A`.`tarif_tindakandr`) AS `jasa_medis`,'Dokter DPJP' AS `tipe_dokter` from ((`rawat_inap_dr` `A` left join `dokter` `B` on(`A`.`kd_dokter` = `B`.`kd_dokter`)) left join `spesialis` `C` on(`B`.`kd_sps` = `C`.`kd_sps`)) group by `A`.`no_rawat`,`A`.`kd_jenis_prw`,`A`.`kd_dokter`) `C` on(`A`.`no_rawat` = `C`.`no_rawat`)) union select `A`.`no_rawat` AS `no_rawat`,`A`.`no_rkm_medis` AS `No_RM`,`A`.`tgl_registrasi` AS `tanggal_masuk`,`B`.`nm_pasien` AS `nm_pasien`,`C`.`kd_dokter` AS `kd_dokter`,`C`.`nm_dokter` AS `nm_dokter`,`C`.`nm_sps` AS `nm_sps`,`C`.`tipe_dokter` AS `tipe_dokter`,`C`.`jasa_medis` AS `jasa_medis` from ((`reg_periksa` `A` left join `pasien` `B` on(`A`.`no_rkm_medis` = `B`.`no_rkm_medis`)) left join (select `A`.`no_rawat` AS `no_rawat`,`A`.`kd_dokter` AS `kd_dokter`,`B`.`nm_dokter` AS `nm_dokter`,`A`.`tipe_dokter` AS `tipe_dokter`,`A`.`jasa_medis` AS `jasa_medis`,`C`.`nm_sps` AS `nm_sps` from ((((select `operasi`.`no_rawat` AS `no_rawat`,`operasi`.`operator1` AS `kd_dokter`,`operasi`.`biayaoperator1` AS `jasa_medis`,'Dokter Operator 1' AS `tipe_dokter` from `operasi`) union select `operasi`.`no_rawat` AS `no_rawat`,`operasi`.`operator2` AS `operator2`,`operasi`.`biayaoperator1` AS `biayaoperator1`,'Dokter Operator 2' AS `Dokter_Operator_2` from `operasi` union select `operasi`.`no_rawat` AS `no_rawat`,`operasi`.`operator3` AS `operator3`,`operasi`.`biayaoperator1` AS `biayaoperator1`,'Dokter Operator 3' AS `Dokter_Operator_3` from `operasi` union select `operasi`.`no_rawat` AS `no_rawat`,`operasi`.`dokter_anestesi` AS `dokter_anestesi`,`operasi`.`biayadokter_anestesi` AS `biayadokter_anestesi`,'Dokter Anestesi' AS `Dokter_Anestesi` from `operasi` union select `operasi`.`no_rawat` AS `no_rawat`,`operasi`.`dokter_anak` AS `dokter_anak`,`operasi`.`biayadokter_anak` AS `biayadokter_anak`,'Dokter Anak' AS `Dokter_Anak` from `operasi`) `A` left join `dokter` `B` on(`A`.`kd_dokter` = `B`.`kd_dokter`)) left join `spesialis` `C` on(`B`.`kd_sps` = `C`.`kd_sps`))) `C` on(`A`.`no_rawat` = `C`.`no_rawat`)) union select `A`.`no_rawat` AS `no_rawat`,`A`.`no_rkm_medis` AS `No_RM`,`A`.`tgl_registrasi` AS `tanggal_masuk`,`B`.`nm_pasien` AS `nm_pasien`,`C`.`kd_dokter` AS `kd_dokter`,`C`.`nm_dokter` AS `nm_dokter`,`C`.`nm_sps` AS `nm_sps`,`C`.`tipe_dokter` AS `tipe_dokter`,`C`.`jasa_medis` AS `jasa_medis` from ((`reg_periksa` `A` left join `pasien` `B` on(`A`.`no_rkm_medis` = `B`.`no_rkm_medis`)) left join (select `A`.`no_rawat` AS `no_rawat`,`A`.`kd_dokter` AS `kd_dokter`,`A`.`kd_jenis_prw` AS `kd_jenis_prw`,`A`.`tipe_dokter` AS `tipe_dokter`,`A`.`jasa_medis` AS `jasa_medis`,`B`.`nm_dokter` AS `nm_dokter`,`C`.`nm_sps` AS `nm_sps` from ((((select `periksa_radiologi`.`no_rawat` AS `no_rawat`,`periksa_radiologi`.`kd_jenis_prw` AS `kd_jenis_prw`,`periksa_radiologi`.`kd_dokter` AS `kd_dokter`,sum(`periksa_radiologi`.`tarif_tindakan_dokter`) AS `jasa_medis`,'Radiologi' AS `tipe_dokter` from `periksa_radiologi` group by `periksa_radiologi`.`no_rawat`,`periksa_radiologi`.`kd_jenis_prw`) union select `periksa_lab`.`no_rawat` AS `no_rawat`,`periksa_lab`.`kd_jenis_prw` AS `kd_jenis_prw`,`periksa_lab`.`kd_dokter` AS `kd_dokter`,sum(`periksa_lab`.`tarif_tindakan_dokter`) AS `sumtarif_tindakan_dokter`,'Laboratorium' AS `Laboratorium` from `periksa_lab` group by `periksa_lab`.`no_rawat`,`periksa_lab`.`kd_jenis_prw`) `A` left join `dokter` `B` on(`A`.`kd_dokter` = `B`.`kd_dokter`)) left join `spesialis` `C` on(`B`.`kd_sps` = `C`.`kd_sps`))) `C` on(`A`.`no_rawat` = `C`.`no_rawat`))) `A` order by `A`.`no_rawat` desc);

-- ----------------------------
-- View structure for jal
-- ----------------------------
DROP VIEW IF EXISTS `jal`;
CREATE ALGORITHM = UNDEFINED SQL SECURITY DEFINER VIEW `jal` AS select `pasien`.`nm_pasien` AS `nm_pasien`,`pasien`.`jk` AS `jk`,`pasien`.`tgl_lahir` AS `tgl_lahir`,`diagnosa_pasien`.`kd_penyakit` AS `kd_penyakit`,`penyakit`.`nm_penyakit` AS `nm_penyakit`,`reg_periksa`.`no_reg` AS `no_reg`,`reg_periksa`.`no_rawat` AS `no_rawat`,`reg_periksa`.`tgl_registrasi` AS `tgl_registrasi`,`reg_periksa`.`jam_reg` AS `jam_reg`,`reg_periksa`.`kd_dokter` AS `kd_dokter`,`reg_periksa`.`no_rkm_medis` AS `no_rkm_medis`,`reg_periksa`.`kd_poli` AS `kd_poli`,`reg_periksa`.`p_jawab` AS `p_jawab`,`reg_periksa`.`almt_pj` AS `almt_pj`,`reg_periksa`.`hubunganpj` AS `hubunganpj`,`reg_periksa`.`biaya_reg` AS `biaya_reg`,`reg_periksa`.`stts` AS `stts`,`reg_periksa`.`stts_daftar` AS `stts_daftar`,`reg_periksa`.`status_lanjut` AS `status_lanjut`,`reg_periksa`.`kd_pj` AS `kd_pj`,`reg_periksa`.`umurdaftar` AS `umurdaftar`,`reg_periksa`.`sttsumur` AS `sttsumur`,`reg_periksa`.`status_bayar` AS `status_bayar`,`reg_periksa`.`status_poli` AS `status_poli` from (((`reg_periksa` join `pasien` on(`pasien`.`no_rkm_medis` = `reg_periksa`.`no_rkm_medis`)) left join `diagnosa_pasien` on(`diagnosa_pasien`.`no_rawat` = `reg_periksa`.`no_rawat` and `diagnosa_pasien`.`prioritas` = 1)) left join `penyakit` on(`penyakit`.`kd_penyakit` = `diagnosa_pasien`.`kd_penyakit`)) where `reg_periksa`.`no_rawat` = '2024/08/12/000032';

-- ----------------------------
-- Function structure for acakadut
-- ----------------------------
DROP FUNCTION IF EXISTS `acakadut`;
delimiter ;;
CREATE FUNCTION `acakadut`()
 RETURNS longtext CHARSET latin1 COLLATE latin1_swedish_ci
BEGIN
	set @no = 0;
	return concat_ws(char(10),
	concat(@no:=@no+1,' registrasi ranap bayi lahir'),
	'pasien gabung [kamar_inap]',
	'nomor rawat ibu jadi ralan, tapi punya data kamar_inap nya',
	'',
	concat(@no:=@no+1,' registrasi ranap status'),
	'status registrasi [reg_periksa]',
	'ada pasien status_lanjut nya sudah ''ranap'' tapi stts nya masih berisi ''Belum'' '
	'',
	concat(@no:=@no+1,' registrasi antrol'),
	'pasien bisa daftar periksa untuk dokter yang tidak ada jadwalnya pada hari itu.',
	'akibatnya antrol nya gagal',
	'',
	concat(@no:=@no+1,' resep obat'),
	'join antara resep_obat,resep_dokter dan detail_pemberian_obat menggunakan kunci tanggal jam periksa.',
	'kalau tanggal dan jam tidak cocok maka tidak akann muncul di rekap obat'
	)
	;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for acakadutz
-- ----------------------------
DROP PROCEDURE IF EXISTS `acakadutz`;
delimiter ;;
CREATE PROCEDURE `acakadutz`(in jenis text)
px:BEGIN
case jenis
	when 'apa aja' then
		select 		concat_ws(char(10),'tgl 2026-03-25 ada surat kontrol 0173R0420126K001327','dari SEP 0173R0420126V002400 yg terbit tanggal 2026-01-19') kacau;
	
	when 'sep tanpa klaim' then
		select 				sep.no_sep																NOSEP,
									if(sep.jnspelayanan=1,'J','I')						RJRI,
									ifnull(min(inap.tgl_masuk),
										ifnull(min(jalan.tgl_perawatan),
											reg.tgl_registrasi
										)
									)																					TANGGAL,
									reg.kd_pj 																CARA_BAYAR,
									#klaim.subpartisi,
									ifnull(klaim.vchra,'')										PROSES,
									sep.no_rawat															NORAWAT,
									reg.stts																	STATUS_REGISTRASI,
									reg.status_lanjut													STATUS_RAWAT
			from 				rsb221022021.bridging_sep  	sep
			left join 	rsb221022021.zzzdata_jkn
			partition 	(intope_klaim) 							klaim
			on 					klaim.subpartisi=sep.no_sep
			left join 	rsb221022021.reg_periksa    reg
			on 					reg.no_rawat=sep.no_rawat
			left join 	rsb221022021.kamar_inap			inap
			on 					inap.no_rawat=reg.no_rawat
			left join 	rsb221022021.rawat_jl_dr  	jalan 
			on 					jalan.no_rawat=reg.no_rawat
			
			where 			ifnull(klaim.vchra,'') = ''
			
			
			group by 		sep.no_sep,reg.no_rawat
			order by 		ifnull(min(inap.tgl_masuk),
										ifnull(min(jalan.tgl_perawatan),
											reg.tgl_registrasi
										)
									)	
			
			#where 			klaim.subpartisi is null
		;
		
		
	when 'bpjs tidak bisa bridging sep' then
	/*
	penyebab 
	1. tanggal masuk tidak sesuai riwayat sep
	2. ranap tidak ada tanggal masuk kamar inap nya
	*/
		select 				
							if(
								reg.status_lanjut='ralan',
								reg.tgl_registrasi,
								min(kamar.tgl_masuk)
								),
								pas.no_peserta,
								reg.no_rawat,
								reg.status_lanjut,
								zd.vin
	from 				rsb221022021.reg_periksa							reg 
	left join 	rsb221022021.kamar_inap kamar
	on 					kamar.no_rawat=reg.no_rawat
	left join 	rsb221022021.pasien 									pas
	on					pas.no_rkm_medis=reg.no_rkm_medis
	left join		rsb221022021.bridging_sep 						sep
	on 					sep.no_rawat=reg.no_rawat
	
	left join  	sb221022021.zzzdata zd 
	on 					zd.vib=reg.no_rawat
	
	where 			reg.tgl_registrasi >= '2024-07-01'
		and 				reg.stts not in ('batal')
		and 				reg.kd_pj='bpj'
		and 				sep.no_sep is null
		#and 				zd.vic  = '167'
	group by 		reg.no_rawat 
	
	
	;



	when 	'tanggal kacau' then
		select 	reg.no_rawat norawat,
						reg.tgl_registrasi								tanggal_regsitrasi,
						sep.tglsep												tanggal_sep,
						kamar.tgl_masuk										tanggal_masuk,
						date(opr.tgl_operasi)							tanggal_operasi
						
			from 	rsb221022021.reg_periksa					reg
			inner join rsb221022021.bridging_sep		sep
				on 				sep.no_rawat=reg.no_rawat
			inner join 	rsb221022021.kamar_inap			kamar
				on 				kamar.no_rawat=reg.no_rawat
			inner join 	rsb221022021.operasi 				opr
				on 				opr.no_rawat=reg.no_rawat
			where reg.no_rawat='2024/09/09/000349'
		;
						
	when 'pasien-nik ganda' then
		select 			no_ktp,count(no_ktp) jumlah
		from 				rsb221022021.pasien
		where 			no_ktp not in ('-','')
		group by 		no_ktp
		having 			count(no_ktp) > 1
		order by 		count(no_ktp) desc 
		;
	when 'tindakan-kode di data induk tidak ada' then
		select * from (
		select 			
								'rawat_jl_dr' 		tabel,
								Y.kd_jenis_prw 		kode_transaksi,
								X.kd_jenis_prw 		kode_induk,
								X.nm_perawatan		nama,
								Y.no_rawat				norawat
			from 			rsb221022021.rawat_jl_dr		Y
			left join rsb221022021.jns_perawatan 	X
			on 				X.kd_jenis_prw=Y.kd_jenis_prw
			where 		X.kd_jenis_prw is null
		union all
		select 			
								'rawat_jl_drpr' 	tabel,
								Y.kd_jenis_prw 		kode_transaksi,
								X.kd_jenis_prw 		kode_induk,
								X.nm_perawatan		nama,
								Y.no_rawat				norawat
			from 			rsb221022021.rawat_jl_drpr	Y
			left join rsb221022021.jns_perawatan 	X
			on 				X.kd_jenis_prw=Y.kd_jenis_prw
			where 		X.kd_jenis_prw is null
		union all
		select 			
								'rawat_jl_pr' 	tabel,
								Y.kd_jenis_prw 		kode_transaksi,
								X.kd_jenis_prw 		kode_induk,
								X.nm_perawatan		nama,
								Y.no_rawat				norawat
			from 			rsb221022021.rawat_jl_pr	Y
			left join rsb221022021.jns_perawatan 	X
			on 				X.kd_jenis_prw=Y.kd_jenis_prw
			where 		X.kd_jenis_prw is null
		union  all
		select 			
								'rawat_inap_dr' 		tabel,
								Y.kd_jenis_prw 		kode_transaksi,
								X.kd_jenis_prw 		kode_induk,
								X.nm_perawatan		nama,
								Y.no_rawat				norawat
			from 			rsb221022021.rawat_inap_dr		Y
			left join rsb221022021.jns_perawatan_inap 	X
			on 				X.kd_jenis_prw=Y.kd_jenis_prw
			where 		X.kd_jenis_prw is null
		union all
		select 			
								'rawat_inap_drpr' 	tabel,
								Y.kd_jenis_prw 		kode_transaksi,
								X.kd_jenis_prw 		kode_induk,
								X.nm_perawatan		nama,
								Y.no_rawat				norawat
			from 			rsb221022021.rawat_inap_drpr	Y
			left join rsb221022021.jns_perawatan_inap 	X
			on 				X.kd_jenis_prw=Y.kd_jenis_prw
			where 		X.kd_jenis_prw is null
		union all
		select 			
								'rawat_inap_pr' 	tabel,
								Y.kd_jenis_prw 		kode_transaksi,
								X.kd_jenis_prw 		kode_induk,
								X.nm_perawatan		nama,
								Y.no_rawat				norawat
			from 			rsb221022021.rawat_inap_pr	Y
			left join rsb221022021.jns_perawatan_inap 	X
			on 				X.kd_jenis_prw=Y.kd_jenis_prw
			where 		X.kd_jenis_prw is null
		) aT1
		group by 		kode_transaksi,norawat
		order by 		norawat
		
		;
	else
		leave px;
end case
;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for alahMbuhAntrian
