DROP PROCEDURE IF EXISTS `alahMbuhAntrian`;
delimiter ;;
CREATE PROCEDURE `alahMbuhAntrian`(IN aa VARCHAR(255),IN bb LONGTEXT)
BEGIN
insert into rsb221022021.mbuh(a,b) values( aa, bb);	

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for billingEklaim
-- ----------------------------
DROP PROCEDURE IF EXISTS `billingEklaim`;
delimiter ;;
CREATE PROCEDURE `billingEklaim`(noraw VARCHAR(20))
BEGIN
	#2024/03/04/011460
drop
	temporary
	table
	if EXISTS		TMP1, TMP2
;

create
	temporary
	table 			TMP1
							(
							norawat varchar(250),
							proc_non_bedah double,
							proc_bedah double,
							konsul double,
							tenaga_ahli double,
							keperawatan double,
							penunjang double,
							radiologi double,
							laborat double,
							darah double,
							rehab double,
							kamar double,
							intensif double,
							obat double,
							obat_kronis double,
							obat_kemo double,
							alkes double,
							bmhp double,
							sewa_alat double,
							biaya_reg double
							
							)
;
create temporary table TMP2 select nm_perawatan,status,totalbiaya from billing where no_rawat = noraw;

insert into TMP1
						(
						norawat,
						proc_non_bedah,
						proc_bedah,
						konsul,
						tenaga_ahli,
						keperawatan,
						penunjang,
						radiologi,
						laborat,
						darah,
						rehab,
						kamar,
						intensif,
						obat,
						obat_kronis,
						obat_kemo,
						alkes,
						bmhp,
						sewa_alat
						
						)
	values 		(
						noraw,
						(select IFNULL(SUM(totalbiaya),0) from TMP2 where status = 'Ralan Dokter Paramedis'),
						(select IFNULL(SUM(totalbiaya),0) from TMP2 where status = 'Operasi'),
						(select IFNULL(SUM(totalbiaya),0) from TMP2 where status = 'Ranap Dokter' OR status = 'Ralan Dokter' ),
						(select IFNULL(SUM(totalbiaya),0) from TMP2 where status = 'Ranap Dokter Paramedis'),
						(select IFNULL(SUM(totalbiaya),0) from TMP2 where status = 'Ranap Paramedis' OR status = 'Ralan Paramedis'),
						(select IFNULL(SUM(totalbiaya),0) from TMP2 where status = 'penunjang'),
						(select IFNULL(SUM(totalbiaya),0) from TMP2 where status = 'Radiologi'),
						(select IFNULL(SUM(totalbiaya),0) from TMP2 where status = 'Laborat'),
						(select IFNULL(SUM(totalbiaya),0) from TMP2 where status = 'Ranap Paramedis' 	AND nm_perawatan like '%transfusi darah%' ),
						(select IFNULL(SUM(totalbiaya),0) from TMP2 where status = 'rehab' 						AND nm_perawatan like '%rehabilitasi%'),
						(select IFNULL(SUM(totalbiaya),0) from TMP2 where status = 'Kamar' AND nm_perawatan NOT like '%CU%' ),						
						(select IFNULL(SUM(totalbiaya),0) from TMP2 where status = 'intensif' 				AND nm_perawatan like '%CU%'),
-- 						(select IFNULL(SUM(totalbiaya),0) from TMP2 where status = 'Obat' 						AND nm_perawatan NOT REGEXP 'kronis|kemo|alkes|bmhp' ),
						(select IFNULL(SUM(totalbiaya),0) from TMP2 where status = 'Obat' OR status = 'Retur Obat' OR status = 'Resep Pulang' 						 ),
						(select IFNULL(SUM(totalbiaya),0) from TMP2 where status = 'Obat' 						AND nm_perawatan like '%kronis%' ),
						(select IFNULL(SUM(totalbiaya),0) from TMP2 where status = 'Obat' 						AND nm_perawatan like '%kemo%' ),
						(select IFNULL(SUM(totalbiaya),0) from TMP2 where status = 'Obat' 						AND nm_perawatan like '%alkes%'),
						(select IFNULL(SUM(totalbiaya),0) from TMP2 where status = 'Tambahan'),
						(select IFNULL(SUM(totalbiaya),0) from TMP2 where status = 'Harian'  OR status = 'Service')
						)
;

UPDATE TMP1 SET biaya_reg = (select biaya_reg from reg_periksa where no_rawat= noraw )  WHERE norawat = noraw
;

-- select * from TMP1;
select 
			a.*, 
			b.status_lanjut, b.no_rkm_medis, b.kd_dokter,
			c.no_peserta, c.no_ktp, c.nm_pasien, c.jk, c.tgl_lahir, 
			d.tgl_masuk, d.jam_masuk, d.tgl_keluar,
			e.kelas,
			f.nm_dokter,
			g.no_sep,
			IFNULL(h.berat_badan,"") as bbbayi,
			diagnosa.dx, proc.px
			
from TMP1 a 
left join reg_periksa b on b.no_rawat = a.norawat
left join pasien c on c.no_rkm_medis = b.no_rkm_medis
left join pasien_bayi h on h.no_rkm_medis = b.no_rkm_medis
left join kamar_inap d on d.no_rawat = a.norawat
left join kamar e on e.kd_kamar = d.kd_kamar
left join dokter f on f.kd_dokter = b.kd_dokter
left join bridging_sep g on g.no_rawat = b.no_rawat
left join ( select no_rawat, group_concat(`kd_penyakit` separator '#') as `dx` from sim_diagnosa_pasien GROUP BY no_rawat ) as diagnosa
					on diagnosa.no_rawat = a.norawat
left join ( select no_rawat, group_concat(`kode` separator '#') as `px` from sim_prosedur_pasien GROUP BY no_rawat ) as proc
					on proc.no_rawat = a.norawat
limit 1					
;


-- 
-- "select a.no_rawat, a.status_lanjut, e.tgl_masuk, e.jam_masuk, e.tgl_keluar, " +
