delimiter ;

-- ----------------------------
-- Procedure structure for cekantrol
-- ----------------------------
DROP PROCEDURE IF EXISTS `cekantrol`;
delimiter ;;
CREATE PROCEDURE `cekantrol`()
BEGIN
	select 		json_unquote(json_extract(antrol.parameter,'$.kodebooking')) 		kdbooking,
				json_unquote(json_extract(antrol.parameter,'$.jenispasien')) 			jkn,
				json_unquote(json_extract(antrol.parameter,'$.kodepoli')) 				poli,
				json_unquote(json_extract(antrol.parameter,'$.norm')) 					norm,
				json_unquote(json_extract(antrol.parameter,'$.kodedokter')) 			kddokter,
				json_unquote(json_extract(antrol.parameter,'$.namadokter')) 			nmdokter,
				json_unquote(json_extract(antrol.parameter,'$.tanggalperiksa')) 		tglperiksa,
				json_unquote(json_extract(antrol.parameter,'$.jampraktek')) 			jamperiksa,
				jad.jam_mulai,
				dayname(json_unquote(json_extract(antrol.parameter,'$.tanggalperiksa'))) days,
				jad.hari_kerja,
				antrol.respon,
				dok.kd_dokter																dokter
from 			rsb221022021.zzzrespontaskid   antrol
left join 		rsb221022021.maping_dokter_dpjpvclaim     mapdok
	on 		mapdok.kd_dokter_bpjs=json_unquote(json_extract(antrol.parameter,'$.kodedokter'))
left JOIN		rsb221022021.dokter dok
	on 		dok.kd_dokter=mapdok.kd_dokter
left join 		rsb221022021.jadwal 			jad
	on			jad.kd_dokter=dok.kd_dokter
	and 		left(jad.jam_mulai,5)=left(json_unquote(json_extract(antrol.parameter,'$.jampraktek')),5)
	and 		case jad.hari_kerja
					when 'senin' then 'Monday'
					when 'selasa' then 'Tuesday'
					when 'rabu' then 'Wednesday'
					when 'kamis' then 'Thursday'
					when 'jumat' then 'friday'
					when 'sabtu' then 'saturday'
					when 'akhad' then 'sunday'
				end 
								= dayname(json_unquote(json_extract(antrol.parameter,'$.tanggalperiksa'))) 

where 		antrol.waktu >= '2025-03-24 00:00:00'
and 			json_unquote(json_extract(antrol.parameter,'$.jenispasien'))  is not null
and 			json_unquote(json_extract(antrol.parameter,'$.jenispasien')) ='jkn'

order by    json_unquote(json_extract(antrol.parameter,'$.tanggalperiksa')),
				json_unquote(json_extract(antrol.parameter,'$.jampraktek'))
;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for data_penyakit
-- ----------------------------
DROP PROCEDURE IF EXISTS `data_penyakit`;
delimiter ;;
CREATE PROCEDURE `data_penyakit`(IN groupe VARCHAR(50))
BEGIN
-- SP ini berfungsi untuk mengisi daftar kode penyakit di tabel grup penyakit
-- lha fungsine opo? yo embuh...

	DECLARE done INT DEFAULT FALSE;
  DECLARE kode VARCHAR(10);
	DECLARE cur CURSOR FOR select grup_penyet.kode from rsb221022021.grup_penyet where grup_penyet.grup = groupe;
	DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;
	OPEN cur;
	read_loop: LOOP
    FETCH cur INTO kode;
    IF done THEN
      LEAVE read_loop;
    END IF;
    
    -- Perform your logic here with each user_id
    INSERT INTO grup_penyakit select penyakit.kd_penyakit, groupe from rsb221022021.penyakit where penyakit.kd_penyakit like concat( kode, '%');
  END LOOP;

  CLOSE cur;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for debugg
-- ----------------------------
DROP PROCEDURE IF EXISTS `debugg`;
delimiter ;;
CREATE PROCEDURE `debugg`(IN p_no_rkm_medis VARCHAR(20))
BEGIN

    DECLARE t_start DATETIME(6);
    DECLARE t_last DATETIME(6);

    SET t_start = NOW(6);
    SET t_last = t_start;

    /* =========================
       1. CEK PASIEN
       ========================= */
    IF NOT EXISTS (
        SELECT 1
        FROM pasien
        WHERE no_rkm_medis = p_no_rkm_medis
    ) THEN

        SELECT 'Pasien tidak ditemukan' AS tahap,
               TIMESTAMPDIFF(MICROSECOND, t_last, NOW(6)) / 1000000 AS detik;

    ELSE

        SELECT
            '01 - Cek pasien' AS tahap,
            TIMESTAMPDIFF(MICROSECOND, t_last, NOW(6)) / 1000000 AS detik;

        SET t_last = NOW(6);


        /* =========================
           2. IDENTITAS
           ========================= */

        SELECT
            CONCAT(
                '<h2>PROFIL RINGKAS MEDIS RAWAT JALAN</h2>',
                '<table>',
                '<tr><th>No. RM</th><td>',
                CONVERT(p.no_rkm_medis USING utf8mb4),
                '</td></tr>',
                '<tr><th>Nama Pasien</th><td>',
                CONVERT(p.nm_pasien USING utf8mb4),
                '</td></tr>',
                '</table>'
            )
        FROM pasien p
        WHERE p.no_rkm_medis = p_no_rkm_medis;

        SELECT
            '02 - Identitas' AS tahap,
            TIMESTAMPDIFF(MICROSECOND, t_last, NOW(6)) / 1000000 AS detik;

        SET t_last = NOW(6);


        /* =========================
           3. DIAGNOSIS
           ========================= */

        SELECT
            GROUP_CONCAT(
                CONCAT(
                    d.`CODE`,
                    ' - ',
                    d.DESCRIPTION
                )
                ORDER BY d.`CODE`
                SEPARATOR '<br>'
            )
        FROM reg_periksa rp
        JOIN diagnosa_pasien_idrg dp
            ON dp.no_rawat = rp.no_rawat
        JOIN idrg d
            ON d.`CODE` = dp.kd_penyakit
        WHERE rp.no_rkm_medis = p_no_rkm_medis;

        SELECT
            '03 - Diagnosis' AS tahap,
            TIMESTAMPDIFF(MICROSECOND, t_last, NOW(6)) / 1000000 AS detik;

        SET t_last = NOW(6);


        /* =========================
           4. PROSEDUR
           ========================= */

        SELECT
            GROUP_CONCAT(
                CONCAT(
                    idrg.`CODE`,
                    ' - ',
                    idrg.DESCRIPTION
                )
                ORDER BY rp.tgl_registrasi DESC
                SEPARATOR '<br>'
            )
        FROM reg_periksa rp
        JOIN prosedur_pasien_idrg pp
            ON pp.no_rawat = rp.no_rawat
        JOIN idrg
            ON idrg.`CODE` = pp.kode
        WHERE rp.no_rkm_medis = p_no_rkm_medis;

        SELECT
            '04 - Prosedur' AS tahap,
            TIMESTAMPDIFF(MICROSECOND, t_last, NOW(6)) / 1000000 AS detik;

        SET t_last = NOW(6);


        /* =========================
           5. RAWAT INAP
           ========================= */

        SELECT
            GROUP_CONCAT(
                CONCAT(
                    ki.tgl_masuk,
                    ' - ',
                    ki.tgl_keluar,
                    ' - ',
                    ki.kd_kamar
                )
                ORDER BY ki.tgl_masuk DESC
                SEPARATOR '<br>'
            )
        FROM kamar_inap ki
        JOIN reg_periksa rp
            ON rp.no_rawat = ki.no_rawat
        WHERE rp.no_rkm_medis = p_no_rkm_medis;

        SELECT
            '05 - Rawat inap' AS tahap,
            TIMESTAMPDIFF(MICROSECOND, t_last, NOW(6)) / 1000000 AS detik;

        SET t_last = NOW(6);


        /* =========================
           6. OBAT
           ========================= */

        SELECT
            GROUP_CONCAT(
                CONCAT(
                    dpo.kode_brng,
                    ' - ',
                    db.nama_brng,
                    ' - ',
                    COUNT(DISTINCT dpo.tgl_perawatan)
                )
                SEPARATOR '<br>'
            )
        FROM detail_pemberian_obat dpo
        JOIN reg_periksa rp
            ON rp.no_rawat = dpo.no_rawat
        JOIN databarang db
            ON db.kode_brng = dpo.kode_brng
        WHERE rp.no_rkm_medis = p_no_rkm_medis
        GROUP BY dpo.kode_brng, db.nama_brng;


        SELECT
            '06 - Obat' AS tahap,
            TIMESTAMPDIFF(MICROSECOND, t_last, NOW(6)) / 1000000 AS detik;

        SET t_last = NOW(6);


        /* =========================
           TOTAL
           ========================= */

        SELECT
            'TOTAL' AS tahap,
            TIMESTAMPDIFF(MICROSECOND, t_start, NOW(6)) / 1000000 AS detik;

    END IF;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for debug_prmrj
-- ----------------------------
DROP PROCEDURE IF EXISTS `debug_prmrj`;
delimiter ;;
CREATE PROCEDURE `debug_prmrj`(IN p_no_rkm_medis VARCHAR(20))
BEGIN

    DECLARE v_html LONGTEXT DEFAULT '';
    DECLARE v_identitas LONGTEXT DEFAULT '';
    DECLARE v_diagnosis LONGTEXT DEFAULT '';
    DECLARE v_prosedur LONGTEXT DEFAULT '';
    DECLARE v_ranap LONGTEXT DEFAULT '';
    DECLARE v_obat LONGTEXT DEFAULT '';

    DECLARE t_start DATETIME(6);
    DECLARE t_last DATETIME(6);

    /* =====================================================
       TEMP TABLE UNTUK HASIL PROFILING
       ===================================================== */

    DROP TEMPORARY TABLE IF EXISTS tmp_debug_prmrj;

    CREATE TEMPORARY TABLE tmp_debug_prmrj (
        urutan INT,
        tahap VARCHAR(100),
        waktu_detik DECIMAL(12,6)
    ) ENGINE=MEMORY;


    SET t_start = NOW(6);
    SET t_last = t_start;


    /* =====================================================
       01. CEK PASIEN
       ===================================================== */

    IF NOT EXISTS (
        SELECT 1
        FROM pasien
        WHERE no_rkm_medis = p_no_rkm_medis
    ) THEN

        INSERT INTO tmp_debug_prmrj
        VALUES (
            1,
            'Cek pasien',
            TIMESTAMPDIFF(
                MICROSECOND,
                t_last,
                NOW(6)
            ) / 1000000
        );

        SELECT
            urutan,
            tahap,
            waktu_detik
        FROM tmp_debug_prmrj
        ORDER BY urutan;

    ELSE


        /* =================================================
           02. HTML HEADER
           ================================================= */

        SET v_html = CONVERT(
            CONCAT(
                '<html>',
                '<head>',
                '<meta charset="UTF-8">',
                '<style>',

                'body{',
                    'font-family:Arial,sans-serif;',
                    'font-size:12px;',
                    'color:#333;',
                    'margin:10px;',
                '}',

                'h2{',
                    'margin:0 0 10px 0;',
                '}',

                'h3{',
                    'background:#eeeeee;',
                    'padding:7px;',
                    'margin-top:15px;',
                    'margin-bottom:5px;',
                    'border-left:4px solid #555;',
                '}',

                'table{',
                    'border-collapse:collapse;',
                    'width:100%;',
                    'margin-bottom:10px;',
                '}',

                'th{',
                    'background:#eeeeee;',
                    'text-align:left;',
                    'padding:6px;',
                    'border:1px solid #cccccc;',
                '}',

                'td{',
                    'padding:6px;',
                    'border:1px solid #cccccc;',
                    'vertical-align:top;',
                '}',

                '.tanggal{',
                    'white-space:nowrap;',
                '}',

                '.kosong{',
                    'color:#888888;',
                    'font-style:italic;',
                '}',

                '</style>',
                '</head>',
                '<body>'
            )
            USING utf8mb4
        );

        INSERT INTO tmp_debug_prmrj
        VALUES (
            2,
            'HTML Header',
            TIMESTAMPDIFF(
                MICROSECOND,
                t_last,
                NOW(6)
            ) / 1000000
        );

        SET t_last = NOW(6);


        /* =================================================
           03. IDENTITAS PASIEN
           ================================================= */

        SELECT CONVERT(
            CONCAT(

                '<h2>PROFIL RINGKAS MEDIS RAWAT JALAN</h2>',

                '<table>',

                '<tr>',
                '<th width="25%">No. RM</th>',
                '<td>',
                COALESCE(
                    CONVERT(
                        p.no_rkm_medis
                        USING utf8mb4
                    ),
                    ''
                ),
                '</td>',
                '</tr>',

                '<tr>',
                '<th>Nama Pasien</th>',
                '<td>',
                COALESCE(
                    CONVERT(
                        p.nm_pasien
                        USING utf8mb4
                    ),
                    ''
                ),
                '</td>',
                '</tr>',

                '<tr>',
                '<th>Tanggal Lahir</th>',
                '<td>',
                COALESCE(
                    DATE_FORMAT(
                        p.tgl_lahir,
                        '%d-%m-%Y'
                    ),
                    ''
                ),
                '</td>',
                '</tr>',

                '<tr>',
                '<th>Jenis Kelamin</th>',
                '<td>',
                CASE
                    WHEN p.jk = 'L'
                        THEN 'Laki-laki'
                    WHEN p.jk = 'P'
                        THEN 'Perempuan'
                    ELSE ''
                END,
                '</td>',
                '</tr>',

                '</table>'

            )
            USING utf8mb4
        )
        INTO v_identitas
        FROM pasien p
        WHERE p.no_rkm_medis = p_no_rkm_medis;


        INSERT INTO tmp_debug_prmrj
        VALUES (
            3,
            'Identitas Pasien',
            TIMESTAMPDIFF(
                MICROSECOND,
                t_last,
                NOW(6)
            ) / 1000000
        );

        SET t_last = NOW(6);


        /* =================================================
           04. DIAGNOSIS
           ================================================= */

        SELECT CONVERT(
            COALESCE(
                (
                    SELECT GROUP_CONCAT(
                        CONVERT(
                            CONCAT(

                                '<tr>',

                                '<td>',
                                COALESCE(
                                    CONVERT(
                                        x.`CODE`
                                        USING utf8mb4
                                    ),
                                    ''
                                ),
                                '</td>',

                                '<td>',
                                COALESCE(
                                    CONVERT(
                                        x.DESCRIPTION
                                        USING utf8mb4
                                    ),
                                    ''
                                ),
                                '</td>',

                                '<td align="center">',
                                x.frekuensi,
                                'x',
                                '</td>',

                                '<td class="tanggal">',
                                COALESCE(
                                    DATE_FORMAT(
                                        x.terakhir,
                                        '%d-%m-%Y'
                                    ),
                                    ''
                                ),
                                '</td>',

                                '</tr>'

                            )
                            USING utf8mb4
                        )

                        ORDER BY
                            x.frekuensi DESC,
                            x.terakhir DESC

                        SEPARATOR ''
                    )

                    FROM
                    (
                        SELECT
                            d.`CODE`,
                            d.DESCRIPTION,
                            COUNT(*) AS frekuensi,
                            MAX(
                                rp.tgl_registrasi
                            ) AS terakhir

                        FROM reg_periksa rp

                        JOIN diagnosa_pasien_idrg dp
                            ON dp.no_rawat =
                                rp.no_rawat

                        JOIN idrg d
                            ON d.`CODE` =
                                dp.kd_penyakit

                        WHERE
                            rp.no_rkm_medis =
                                p_no_rkm_medis

                        GROUP BY
                            d.`CODE`,
                            d.DESCRIPTION

                    ) x
                ),

                '<tr>',
                '<td colspan="4" class="kosong">',
                'Tidak ada riwayat diagnosis.',
                '</td>',
                '</tr>'

            )
            USING utf8mb4
        )
        INTO v_diagnosis;


        INSERT INTO tmp_debug_prmrj
        VALUES (
            4,
            'Diagnosis',
            TIMESTAMPDIFF(
                MICROSECOND,
                t_last,
                NOW(6)
            ) / 1000000
        );

        SET t_last = NOW(6);


        /* =================================================
           05. PROSEDUR
           ================================================= */

        SELECT CONVERT(
            COALESCE(
                (
                    SELECT GROUP_CONCAT(
                        CONVERT(
                            CONCAT(

                                '<tr>',

                                '<td class="tanggal">',
                                COALESCE(
                                    DATE_FORMAT(
                                        x.tgl_registrasi,
                                        '%d-%m-%Y'
                                    ),
                                    ''
                                ),
                                '</td>',

                                '<td>',
                                COALESCE(
                                    CONVERT(
                                        x.kode
                                        USING utf8mb4
                                    ),
                                    ''
                                ),
                                '</td>',

                                '<td>',
                                COALESCE(
                                    CONVERT(
                                        x.deskripsi
                                        USING utf8mb4
                                    ),
                                    ''
                                ),
                                '</td>',

                                '</tr>'

                            )
                            USING utf8mb4
                        )

                        ORDER BY
                            x.tgl_registrasi DESC

                        SEPARATOR ''
                    )

                    FROM
                    (
                        SELECT
                            rp.tgl_registrasi,
                            idrg.`CODE` AS kode,
                            idrg.DESCRIPTION AS deskripsi

                        FROM reg_periksa rp

                        JOIN prosedur_pasien_idrg pp
                            ON pp.no_rawat =
                                rp.no_rawat

                        JOIN idrg
                            ON idrg.`CODE` =
                                pp.kode

                        WHERE
                            rp.no_rkm_medis =
                                p_no_rkm_medis

                    ) x
                ),

                '<tr>',
                '<td colspan="3" class="kosong">',
                'Tidak ada riwayat prosedur.',
                '</td>',
                '</tr>'

            )
            USING utf8mb4
        )
        INTO v_prosedur;


        INSERT INTO tmp_debug_prmrj
        VALUES (
            5,
            'Prosedur',
            TIMESTAMPDIFF(
                MICROSECOND,
                t_last,
                NOW(6)
            ) / 1000000
        );

        SET t_last = NOW(6);


        /* =================================================
           06. RAWAT INAP
           ================================================= */

        SELECT CONVERT(
            COALESCE(
                (
                    SELECT GROUP_CONCAT(
                        CONVERT(
                            CONCAT(

                                '<tr>',

                                '<td class="tanggal">',
                                COALESCE(
                                    DATE_FORMAT(
                                        x.tgl_masuk,
                                        '%d-%m-%Y'
                                    ),
                                    ''
                                ),
                                '</td>',

                                '<td class="tanggal">',

                                CASE

                                    WHEN
                                        x.tgl_keluar IS NULL
                                        OR x.tgl_keluar =
                                            '0000-00-00'

                                    THEN
                                        'Masih Dirawat'

                                    ELSE
                                        DATE_FORMAT(
                                            x.tgl_keluar,
                                            '%d-%m-%Y'
                                        )

                                END,

                                '</td>',

                                '<td>',
                                COALESCE(
                                    CONVERT(
                                        x.kd_kamar
                                        USING utf8mb4
                                    ),
                                    ''
                                ),
                                '</td>',

                                '</tr>'

                            )
                            USING utf8mb4
                        )

                        ORDER BY
                            x.tgl_masuk DESC

                        SEPARATOR ''
                    )

                    FROM
                    (
                        SELECT
                            ki.no_rawat,
                            ki.tgl_masuk,
                            ki.tgl_keluar,
                            ki.kd_kamar

                        FROM kamar_inap ki

                        JOIN reg_periksa rp
                            ON rp.no_rawat =
                                ki.no_rawat

                        WHERE
                            rp.no_rkm_medis =
                                p_no_rkm_medis

                        GROUP BY
                            ki.no_rawat,
                            ki.tgl_masuk,
                            ki.tgl_keluar,
                            ki.kd_kamar

                    ) x
                ),

                '<tr>',
                '<td colspan="3" class="kosong">',
                'Tidak ada riwayat rawat inap.',
                '</td>',
                '</tr>'

            )
            USING utf8mb4
        )
        INTO v_ranap;


        INSERT INTO tmp_debug_prmrj
        VALUES (
            6,
            'Rawat Inap',
            TIMESTAMPDIFF(
                MICROSECOND,
                t_last,
                NOW(6)
            ) / 1000000
        );

        SET t_last = NOW(6);


        /* =================================================
           07. OBAT
           ================================================= */

        SELECT CONVERT(
            COALESCE(
                (
                    SELECT GROUP_CONCAT(
                        CONVERT(
                            CONCAT(

                                '<tr>',

                                '<td>',
                                COALESCE(
                                    CONVERT(
                                        x.kode_brng
                                        USING utf8mb4
                                    ),
                                    ''
                                ),
                                '</td>',

                                '<td>',
                                COALESCE(
                                    CONVERT(
                                        x.nama_brng
                                        USING utf8mb4
                                    ),
                                    ''
                                ),
                                '</td>',

                                '<td align="center">',
                                COALESCE(
                                    x.jumlah_hari,
                                    0
                                ),
                                ' hari',
                                '</td>',

                                '<td align="right">',
                                COALESCE(
                                    FORMAT(
                                        x.total_jumlah,
                                        2
                                    ),
                                    '0'
                                ),
                                '</td>',

                                '<td class="tanggal">',
                                COALESCE(
                                    DATE_FORMAT(
                                        x.terakhir,
                                        '%d-%m-%Y'
                                    ),
                                    ''
                                ),
                                '</td>',

                                '</tr>'

                            )
                            USING utf8mb4
                        )

                        ORDER BY
                            x.jumlah_hari DESC,
                            x.terakhir DESC

                        SEPARATOR ''
                    )

                    FROM
                    (
                        SELECT
                            CONVERT(
                                dpo.kode_brng
                                USING utf8mb4
                            ) AS kode_brng,

                            CONVERT(
                                db.nama_brng
                                USING utf8mb4
                            ) AS nama_brng,

                            COUNT(
                                DISTINCT
                                dpo.tgl_perawatan
                            ) AS jumlah_hari,

                            SUM(
                                dpo.jml
                            ) AS total_jumlah,

                            MAX(
                                dpo.tgl_perawatan
                            ) AS terakhir

                        FROM detail_pemberian_obat dpo

                        JOIN reg_periksa rp
                            ON rp.no_rawat =
                                dpo.no_rawat

                        JOIN databarang db
                            ON db.kode_brng =
                                dpo.kode_brng

                        WHERE
                            rp.no_rkm_medis =
                                p_no_rkm_medis

                        GROUP BY
                            dpo.kode_brng,
                            db.nama_brng

                    ) x
                ),

                '<tr>',
                '<td colspan="5" class="kosong">',
                'Tidak ada riwayat obat.',
                '</td>',
                '</tr>'

            )
            USING utf8mb4
        )
        INTO v_obat;


        INSERT INTO tmp_debug_prmrj
        VALUES (
            7,
            'Obat',
            TIMESTAMPDIFF(
                MICROSECOND,
                t_last,
                NOW(6)
            ) / 1000000
        );

        SET t_last = NOW(6);


        /* =================================================
           08. GABUNG HTML
           ================================================= */

        SET v_html = CONVERT(
            CONCAT(

                v_html,

                v_identitas,

                '<h3>Diagnosis yang Sering / Riwayat Diagnosis</h3>',
                '<table>',
                '<tr>',
                '<th>Kode</th>',
                '<th>Diagnosis</th>',
                '<th>Frekuensi</th>',
                '<th>Terakhir</th>',
                '</tr>',
                v_diagnosis,
                '</table>',

                '<h3>Riwayat Prosedur</h3>',
                '<table>',
                '<tr>',
                '<th>Tanggal</th>',
                '<th>Kode</th>',
                '<th>Prosedur</th>',
                '</tr>',
                v_prosedur,
                '</table>',

                '<h3>Riwayat Rawat Inap</h3>',
                '<table>',
                '<tr>',
                '<th>Masuk</th>',
                '<th>Keluar</th>',
                '<th>Kamar</th>',
                '</tr>',
                v_ranap,
                '</table>',

                '<h3>Obat yang Sering Digunakan</h3>',
                '<table>',
                '<tr>',
                '<th>Kode</th>',
                '<th>Nama Obat</th>',
                '<th>Jumlah Hari</th>',
                '<th>Total Jumlah</th>',
                '<th>Terakhir</th>',
                '</tr>',
                v_obat,
                '</table>',

                '</body>',
                '</html>'

            )
            USING utf8mb4
        );


        INSERT INTO tmp_debug_prmrj
        VALUES (
            8,
            'Final CONCAT HTML',
            TIMESTAMPDIFF(
                MICROSECOND,
                t_last,
                NOW(6)
            ) / 1000000
        );


        /* =================================================
           09. TOTAL
           ================================================= */

        INSERT INTO tmp_debug_prmrj
        VALUES (
            9,
            'TOTAL',
            TIMESTAMPDIFF(
                MICROSECOND,
                t_start,
                NOW(6)
            ) / 1000000
        );


        /* =================================================
           HASIL DEBUG
           ================================================= */

        SELECT
            urutan,
            tahap,
            waktu_detik
        FROM tmp_debug_prmrj
        ORDER BY urutan;

    END IF;

END
;;
delimiter ;

-- ----------------------------
-- Function structure for fn_Khanza_billing_ranap
-- ----------------------------
DROP FUNCTION IF EXISTS `fn_Khanza_billing_ranap`;
delimiter ;;
CREATE FUNCTION `fn_Khanza_billing_ranap`(p_no_rawat VARCHAR(17))
 RETURNS double
  READS SQL DATA 
BEGIN
  RETURN
      IFNULL((SELECT SUM(biaya) FROM periksa_lab WHERE no_rawat=p_no_rawat),0)
    + IFNULL((SELECT SUM(biaya_item) FROM detail_periksa_lab WHERE no_rawat=p_no_rawat),0)
    + IFNULL((SELECT SUM(biaya) FROM periksa_radiologi WHERE no_rawat=p_no_rawat),0)
    + IFNULL((SELECT SUM(biayaoperator1+biayaoperator2+biayaoperator3+biayaasisten_operator1+biayaasisten_operator2+biayaasisten_operator3+biayainstrumen+biayadokter_anak+biayaperawaat_resusitas+biayadokter_anestesi+biayaasisten_anestesi+biayaasisten_anestesi2+biayabidan+biayabidan2+biayabidan3+biayaperawat_luar+biayaalat+biayasewaok+akomodasi+bagian_rs+biaya_omloop+biaya_omloop2+biaya_omloop3+biaya_omloop4+biaya_omloop5+biayasarpras+biaya_dokter_pjanak+biaya_dokter_umum)
              FROM operasi WHERE no_rawat=p_no_rawat),0)
    + IFNULL((SELECT biaya_reg FROM reg_periksa WHERE no_rawat=p_no_rawat),0)
    + IFNULL((SELECT SUM(total) FROM detail_pemberian_obat WHERE no_rawat=p_no_rawat),0)
    + IFNULL((SELECT SUM(besar_tagihan) FROM tagihan_obat_langsung WHERE no_rawat=p_no_rawat),0)
    + IFNULL((SELECT SUM(hargasatuan*jumlah) FROM beri_obat_operasi WHERE no_rawat=p_no_rawat),0)
    + IFNULL((SELECT SUM(biaya_rawat) FROM rawat_inap_dr WHERE no_rawat=p_no_rawat),0)
    + IFNULL((SELECT SUM(biaya_rawat) FROM rawat_inap_drpr WHERE no_rawat=p_no_rawat),0)
    + IFNULL((SELECT SUM(biaya_rawat) FROM rawat_inap_pr WHERE no_rawat=p_no_rawat),0)
    + IFNULL((SELECT SUM(biaya_rawat) FROM rawat_jl_dr WHERE no_rawat=p_no_rawat),0)
    + IFNULL((SELECT SUM(biaya_rawat) FROM rawat_jl_drpr WHERE no_rawat=p_no_rawat),0)
    + IFNULL((SELECT SUM(biaya_rawat) FROM rawat_jl_pr WHERE no_rawat=p_no_rawat),0)
    + IFNULL((SELECT SUM(besar_biaya) FROM tambahan_biaya WHERE no_rawat=p_no_rawat),0)
    -- CATATAN: kode Java asli MENAMBAH pengurangan_biaya (bukan mengurangi).
    -- Dipertahankan agar hasil sama; cek apakah nilainya memang tersimpan negatif.
    + IFNULL((SELECT SUM(besar_pengurangan) FROM pengurangan_biaya WHERE no_rawat=p_no_rawat),0)
    + IFNULL((SELECT SUM(ttl_biaya) FROM kamar_inap WHERE no_rawat=p_no_rawat),0)
    + IFNULL((SELECT SUM(biaya_sekali.besar_biaya)
              FROM biaya_sekali INNER JOIN kamar_inap ON kamar_inap.kd_kamar=biaya_sekali.kd_kamar
              WHERE kamar_inap.no_rawat=p_no_rawat),0)
    + IFNULL((SELECT SUM(biaya_harian.jml*biaya_harian.besar_biaya*kamar_inap.lama)
              FROM kamar_inap INNER JOIN biaya_harian ON kamar_inap.kd_kamar=biaya_harian.kd_kamar
              WHERE kamar_inap.no_rawat=p_no_rawat),0)
    - IFNULL((SELECT SUM(subtotal) FROM detreturjual
              WHERE no_retur_jual LIKE CONCAT('%',p_no_rawat,'%')),0)
    + IFNULL((SELECT SUM(total) FROM resep_pulang WHERE no_rawat=p_no_rawat),0);
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for load_prmrj
-- ----------------------------
DROP PROCEDURE IF EXISTS `load_prmrj`;
delimiter ;;
CREATE PROCEDURE `load_prmrj`(IN p_no_rkm_medis VARCHAR(20))
BEGIN

    DECLARE v_html LONGTEXT DEFAULT '';
    DECLARE v_obat LONGTEXT DEFAULT '';

    /* =========================================================
       HTML HEADER
       ========================================================= */

    SET v_html = CONVERT(
        '<html>
        <head>
        <meta charset="UTF-8">
        <style>
            body {
                font-family: Arial, sans-serif;
                font-size: 10px;
                color: #222;
                margin: 10px;
            }

            h2 {
                margin-top: 10px;
                margin-bottom: 8px;
            }

            h3 {
                margin-top: 15px;
                margin-bottom: 5px;
                color: #333;
            }

            table {
                width: 100%;
                border-collapse: collapse;
                margin-bottom: 10px;
            }

            th {
                background-color: #eeeeee;
                border: 1px solid #999999;
                padding: 5px;
                text-align: center;
            }

            td {
                border: 1px solid #999999;
                padding: 5px;
                vertical-align: top;
            }

            .tanggal {
                white-space: nowrap;
            }

            .kosong {
                text-align: center;
                color: #777777;
            }
        </style>
        </head>
        <body>'
        USING utf8mb4
    );


    /* =========================================================
       IDENTITAS PASIEN
       ========================================================= */

    SELECT
        CONVERT(
            CONCAT(
                v_html,

                '<h2>Profil Ringkas Medis Rawat Jalan</h2>',

                '<table>',

                '<tr>',
                '<td width="150"><b>No. RM</b></td>',
                '<td>',
                COALESCE(CONVERT(p.no_rkm_medis USING utf8mb4), ''),
                '</td>',
                '</tr>',

                '<tr>',
                '<td><b>Nama Pasien</b></td>',
                '<td>',
                COALESCE(CONVERT(p.nm_pasien USING utf8mb4), ''),
                '</td>',
                '</tr>',

								'<tr>',
								'<td><b>Tanggal Lahir</b></td>',
								'<td>',
								COALESCE(DATE_FORMAT(p.tgl_lahir, '%d-%m-%Y'), ''),
								' (',
								COALESCE(CONCAT(rp.umurdaftar, ' ', rp.sttsumur), ''),
								')',
								'</td>',
								'</tr>',

                '<tr>',
                '<td><b>Jenis Kelamin</b></td>',
                '<td>',
                CASE
                    WHEN p.jk = 'L' THEN 'Laki-laki'
                    WHEN p.jk = 'P' THEN 'Perempuan'
                    ELSE COALESCE(CONVERT(p.jk USING utf8mb4), '')
                END,
                '</td>',
                '</tr>',

                '</table>'
            )
            USING utf8mb4
        )
    INTO v_html
    FROM pasien p
		LEFT JOIN reg_periksa rp
				ON rp.no_rkm_medis = p.no_rkm_medis
		WHERE p.no_rkm_medis = p_no_rkm_medis
		ORDER BY rp.tgl_registrasi DESC
		LIMIT 1;


    /* =========================================================
       DIAGNOSIS
       ========================================================= */

    SET v_html = CONVERT(
        CONCAT(
            v_html,

            '<h3>Diagnosis / Riwayat Diagnosis</h3>',

            '<table>',

            '<tr>',
            '<th>Kode</th>',
            '<th>Diagnosis</th>',
            '<th>Frekuensi</th>',
            '<th>Terakhir</th>',
            '</tr>',

            COALESCE(

                (
                    SELECT GROUP_CONCAT(
                        CONVERT(
                            CONCAT(
                                '<tr>',

                                '<td>',
                                COALESCE(
                                    CONVERT(x.CODE USING utf8mb4),
                                    ''
                                ),
                                '</td>',

                                '<td>',
                                COALESCE(
                                    CONVERT(x.DESCRIPTION USING utf8mb4),
                                    ''
                                ),
                                '</td>',

                                '<td align="center">',
                                COALESCE(x.frekuensi, 0),
                                '</td>',

                                '<td class="tanggal">',
                                COALESCE(
                                    DATE_FORMAT(
                                        x.terakhir,
                                        '%d-%m-%Y'
                                    ),
                                    ''
                                ),
                                '</td>',

                                '</tr>'
                            )
                            USING utf8mb4
                        )
                        ORDER BY
                            x.frekuensi DESC,
                            x.terakhir DESC
                        SEPARATOR ''
                    )
                    FROM
                    (
                        SELECT
                            d.CODE,
                            d.DESCRIPTION,
                            COUNT(*) AS frekuensi,
                            MAX(rp.tgl_registrasi) AS terakhir
                        FROM reg_periksa rp
                        JOIN diagnosa_pasien_idrg dp
                            ON dp.no_rawat = rp.no_rawat
                        JOIN idrg d
                            ON d.CODE = dp.kd_penyakit
                        WHERE rp.no_rkm_medis = p_no_rkm_medis AND d.CODE NOT LIKE 'Z%'
                        GROUP BY
                            d.CODE,
                            d.DESCRIPTION
                    ) x
                ),

                '<tr>',
                '<td colspan="4" class="kosong">',
                'Tidak ada riwayat diagnosis.',
                '</td>',
                '</tr>'

            ),

            '</table>'
        )
        USING utf8mb4
    );


    /* =========================================================
       PROSEDUR
       ========================================================= */

    SET v_html = CONVERT(
        CONCAT(
            v_html,

            '<h3>Prosedur yang Dilakukan</h3>',

            '<table>',

            '<tr>',
            '<th>Kode</th>',
            '<th>Prosedur</th>',
            '<th>Frekuensi</th>',
            '<th>Terakhir</th>',
            '</tr>',

            COALESCE(

                (
                    SELECT GROUP_CONCAT(
                        CONVERT(
                            CONCAT(
                                '<tr>',

                                '<td>',
                                COALESCE(
                                    CONVERT(x.kode USING utf8mb4),
                                    ''
                                ),
                                '</td>',

                                '<td>',
                                COALESCE(
                                    CONVERT(x.DESCRIPTION USING utf8mb4),
                                    ''
                                ),
                                '</td>',

                                '<td align="center">',
                                COALESCE(x.frekuensi, 0),
                                '</td>',

                                '<td class="tanggal">',
                                COALESCE(
                                    DATE_FORMAT(
                                        x.terakhir,
                                        '%d-%m-%Y'
                                    ),
                                    ''
                                ),
                                '</td>',

                                '</tr>'
                            )
                            USING utf8mb4
                        )
                        ORDER BY
                            x.frekuensi DESC,
                            x.terakhir DESC
                        SEPARATOR ''
                    )
                    FROM
                    (
                        SELECT
                            pp.kode,
                            d.DESCRIPTION,
                            COUNT(*) AS frekuensi,
                            MAX(rp.tgl_registrasi) AS terakhir
                        FROM reg_periksa rp
                        JOIN prosedur_pasien_idrg pp
                            ON pp.no_rawat = rp.no_rawat
                        JOIN idrg d
                            ON d.CODE = pp.kode
                        WHERE rp.no_rkm_medis = p_no_rkm_medis
                        GROUP BY
                            pp.kode,
                            d.DESCRIPTION
                    ) x
                ),

                '<tr>',
                '<td colspan="4" class="kosong">',
                'Tidak ada riwayat prosedur.',
                '</td>',
                '</tr>'

            ),

            '</table>'
        )
        USING utf8mb4
    );


    /* =========================================================
       RAWAT INAP
       ========================================================= */

    SET v_html = CONVERT(
        CONCAT(
            v_html,

            '<h3>Riwayat Rawat Inap</h3>',

            '<table>',

            '<tr>',
            '<th>No. Rawat</th>',
            '<th>Tanggal Masuk</th>',
            '<th>Tanggal Keluar</th>',
            '<th>Kamar</th>',
            '</tr>',

            COALESCE(

                (
                    SELECT GROUP_CONCAT(
                        CONVERT(
                            CONCAT(
                                '<tr>',

                                '<td>',
                                COALESCE(
                                    CONVERT(x.no_rawat USING utf8mb4),
                                    ''
                                ),
                                '</td>',

                                '<td class="tanggal">',
                                COALESCE(
                                    DATE_FORMAT(
                                        x.tgl_masuk,
                                        '%d-%m-%Y'
                                    ),
                                    ''
                                ),
                                '</td>',

                                '<td class="tanggal">',
                                COALESCE(
                                    DATE_FORMAT(
                                        x.tgl_keluar,
                                        '%d-%m-%Y'
                                    ),
                                    ''
                                ),
                                '</td>',

                                '<td>',
                                COALESCE(
                                    CONVERT(x.kd_kamar USING utf8mb4),
                                    ''
                                ),
                                '</td>',

                                '</tr>'
                            )
                            USING utf8mb4
                        )
                        ORDER BY
                            x.tgl_masuk DESC
                        SEPARATOR ''
                    )
                    FROM
                    (
                        SELECT
                            ki.no_rawat,
                            ki.tgl_masuk,
                            ki.tgl_keluar,
                            ki.kd_kamar
                        FROM kamar_inap ki
                        JOIN reg_periksa rp
                            ON rp.no_rawat = ki.no_rawat
                        WHERE rp.no_rkm_medis = p_no_rkm_medis
                        GROUP BY
                            ki.no_rawat,
                            ki.tgl_masuk,
                            ki.tgl_keluar,
                            ki.kd_kamar
                    ) x
                ),

                '<tr>',
                '<td colspan="4" class="kosong">',
                'Tidak ada riwayat rawat inap.',
                '</td>',
                '</tr>'

            ),

            '</table>'
        )
        USING utf8mb4
    );


    /* =========================================================
       OBAT
       
       PENTING:
       Query ini menggunakan PREPARE karena query dengan
       p_no_rkm_medis secara langsung terbukti membutuhkan
       ±10 detik, sedangkan PREPARE hanya ±0,002 detik.
       ========================================================= */

    SET @v_obat = '';

    SET @sql_obat = '
        SELECT GROUP_CONCAT(
            CONVERT(
                CONCAT(
                    ''<tr>'',

                    ''<td>'',
                    COALESCE(
                        CONVERT(x.kode_brng USING utf8mb4),
                        ''''
                    ),
                    ''</td>'',

                    ''<td>'',
                    COALESCE(
                        CONVERT(x.nama_brng USING utf8mb4),
                        ''''
                    ),
                    ''</td>'',

                    ''<td align="center">'',
                    COALESCE(x.jumlah_hari, 0),
                    ''x'',
                    ''</td>'',

                    ''<td align="right">'',
                    COALESCE(
                        FORMAT(x.total_jumlah, 2),
                        ''0''
                    ),
                    ''</td>'',

                    ''<td class="tanggal">'',
                    COALESCE(
                        DATE_FORMAT(
                            x.terakhir,
                            ''%d-%m-%Y''
                        ),
                        ''''
                    ),
                    ''</td>'',

                    ''</tr>''
                )
                USING utf8mb4
            )
            ORDER BY
                x.jumlah_hari DESC,
                x.terakhir DESC
            SEPARATOR ''''
        )
        INTO @v_obat
        FROM
        (
            SELECT
                CONVERT(
                    dpo.kode_brng USING utf8mb4
                ) AS kode_brng,

                CONVERT(
                    db.nama_brng USING utf8mb4
                ) AS nama_brng,

                COUNT(
                    DISTINCT dpo.tgl_perawatan
                ) AS jumlah_hari,

                SUM(
                    dpo.jml
                ) AS total_jumlah,

                MAX(
                    dpo.tgl_perawatan
                ) AS terakhir

            FROM detail_pemberian_obat dpo

            JOIN reg_periksa rp
                ON rp.no_rawat = dpo.no_rawat

            JOIN databarang db
                ON db.kode_brng = dpo.kode_brng

            WHERE rp.no_rkm_medis = ?
						
								AND (
										db.kode_kategori IS NULL
										OR db.kode_kategori NOT IN (''K14'', ''K15'')
								)

            GROUP BY
                dpo.kode_brng,
                db.nama_brng
        ) x
    ';


    SET @medis_obat = p_no_rkm_medis;

    PREPARE stmt_obat FROM @sql_obat;

    EXECUTE stmt_obat USING @medis_obat;

    DEALLOCATE PREPARE stmt_obat;


    SET v_obat = COALESCE(
        @v_obat,
        '<tr>',
        '<td colspan="5" class="kosong">',
        'Tidak ada riwayat obat.',
        '</td>',
        '</tr>'
    );


    SET v_html = CONVERT(
        CONCAT(
            v_html,

            '<h3>Obat yang Digunakan</h3>',

            '<table>',

            '<tr>',
            '<th>Kode</th>',
            '<th>Nama Obat</th>',
            '<th>Muncul di Resep</th>',
            '<th>Total Jumlah</th>',
            '<th>Terakhir</th>',
            '</tr>',

            v_obat,

            '</table>'
        )
        USING utf8mb4
    );


    /* =========================================================
       PENUTUP HTML
       ========================================================= */

    SET v_html = CONVERT(
        CONCAT(
            v_html,
            '</body>',
            '</html>'
        )
        USING utf8mb4
    );


    /* =========================================================
       HASIL
       ========================================================= */

    SELECT v_html AS html;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for paCekErrorTabel
-- ----------------------------
DROP PROCEDURE IF EXISTS `paCekErrorTabel`;
delimiter ;;
CREATE PROCEDURE `paCekErrorTabel`(IN PARAM JSON)
px:BEGIN
	declare 			vTabel varchar(250) default '';
	declare			crTabel	cursor for select		concat(
															table_schema,
															'.',
															table_name
															)
													from	information_schema.TABLES
	
	;
	
	DECLARE
		CONTINUE 
		HANDLER 
		FOR
		SQLEXCEPTION
	BEGIN
		GET
			DIAGNOSTICS
			CONDITION			1			@GxPesan		=	MESSAGE_TEXT,
													@GxNomor		=	MYSQL_ERRNO,
													@GxStatus 	= RETURNED_SQLSTATE
		;
	END
	;
	
	SET											@GxPesan			=	'',
													@GxNomor			=	0,
													@GxStatus 		= 0,
													@sqqq			=	''
	;
	
/*
	open 								crTabel;
				
				lo:loop
					FETCH 			crtabel INTO vTabel;
					
					
					IF 					ifnull(vTabel,'')  = '' THEN
						  LEAVE 		lo; -- Exit the loop if no more rows
					END IF;
					
					set 				@sqqq  = ''
					
					
				end loop
				;
			close 						crPindai;
	*/
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for pxDasar_UbahKelas
-- ----------------------------
DROP PROCEDURE IF EXISTS `pxDasar_UbahKelas`;
delimiter ;;
CREATE PROCEDURE `pxDasar_UbahKelas`(IN argNORAWAT VARCHAR(250),IN argDARI VARCHAR(250), IN argJADI VARCHAR(250))
px:BEGIN
	
	declare 										pAsuransi varchar(250) default ifnull((select kd_pj from rsb221022021.reg_periksa where no_rawat  = argNORAWAT),'');
	
	DECLARE
		CONTINUE
		HANDLER 
		FOR
		SQLEXCEPTION
	BEGIN
		GET
			DIAGNOSTICS
			CONDITION			1	@GxPesan		=	MESSAGE_TEXT,
										@GxNomor		=	MYSQL_ERRNO,
										@GxStatus 		= 	RETURNED_SQLSTATE
		;
	END
	;
	
	SET	@GxPesan		=	'',
			@GxNomor		=	0,
			@GxStatus 		= 	0
	;
	
	/*
	if pAsuransi not like 'umu' then
		leave px;
	end if
	;
	*/
	
	#/* rawat_inap_dr
	
	update  					rsb221022021.rawat_inap_dr					dari
	inner join 				rsb221022021.jns_perawatan_inap				ind
		on 					dari.no_rawat=argNORAWAT
		and 					ind.kd_jenis_prw=dari.kd_jenis_prw
	inner join 				rsb221022021.jns_perawatan_inap				jadi
		on 					jadi.nm_perawatan=ind.nm_perawatan
		and 					jadi.kd_pj='-'
		and 					jadi.kelas=argJADI
	set 						dari.material=jadi.material,
								dari.tarif_tindakandr=jadi.tarif_tindakandr,
								dari.biaya_rawat=jadi.total_byrdrpr
	;
	
	
	#*/
	
	
	#/* periksa_lab
	
		update				rsb221022021.periksa_lab								dari
		inner join 			rsb221022021.jns_perawatan_lab						ind
			on 				dari.no_rawat=argNORAWAT
			and 				ind.kd_jenis_prw=dari.kd_jenis_prw
		inner join 			rsb221022021.jns_perawatan_lab						jadi
			on 				jadi.nm_perawatan=ind.nm_perawatan
			and 				jadi.kd_pj='-'
			and 				jadi.kelas=argJADI
		
		
		set 					dari.bagian_rs=jadi.bagian_rs,
								dari.bhp=jadi.bhp,
								dari.tarif_tindakan_dokter=jadi.tarif_tindakan_dokter,
								dari.biaya=jadi.total_byr
		WHERE				dari.status='Ranap'
	;
	#*/
	
	
	#/* periksa_radiologi
	
		update 				rsb221022021.periksa_radiologi						dari
		inner join 			rsb221022021.jns_perawatan_radiologi				ind
			on 				dari.no_rawat=argNORAWAT
			and 				ind.kd_jenis_prw=dari.kd_jenis_prw
		inner join 			rsb221022021.jns_perawatan_radiologi				jadi
			on 				jadi.nm_perawatan=ind.nm_perawatan
			and 				jadi.kd_pj='-'
			and 				jadi.kelas=argJADI
		
	
		set 					dari.bagian_rs=jadi.bagian_rs,
								dari.bhp=jadi.bhp,
								dari.tarif_tindakan_dokter=jadi.tarif_tindakan_dokter,
								dari.biaya=jadi.total_byr
	  WHERE					dari.status='Ranap'
	;
	
	#*/
	
	
	
	
	/*
	select				dari.*,
								ind.nm_perawatan,
								ind.kelas,
								ind.kode_paket,
								jadi.*
		
		from				
	*/
	
		update 				rsb221022021.operasi												dari
		inner join 			rsb221022021.paket_operasi									ind
			on 				dari.no_rawat=argNORAWAT
			and 				ind.kode_paket=dari.kode_paket
		inner join 			rsb221022021.paket_operasi									jadi
			on 				jadi.nm_perawatan=ind.nm_perawatan
			and 				jadi.kd_pj='-'
			and 				jadi.kelas=argJADI
		
		
		set 					dari.biayaoperator1=jadi.operator1,
								dari.biayaoperator2=jadi.operator2,
								dari.biayaoperator3=jadi.operator3,
								dari.biayaasisten_operator1=jadi.asisten_operator1,
								dari.biayaasisten_operator2=jadi.asisten_operator2,
								dari.biayaasisten_operator3=jadi.asisten_operator3,
								dari.biayainstrumen=jadi.instrumen,
								dari.biayadokter_anak=jadi.dokter_anak,
								dari.biayadokter_anestesi=jadi.dokter_anestesi,
								dari.biayaasisten_anestesi=jadi.asisten_anestesi,
								dari.biayaasisten_anestesi2=jadi.asisten_anestesi2,
								dari.biayabidan=jadi.bidan,
								dari.biayabidan2=jadi.bidan2,
								dari.biayabidan3=jadi.bidan3,
								dari.biayaalat=jadi.alat,
								dari.biayasewaok=jadi.sewa_ok,
								dari.bagian_rs=jadi.bagian_rs,
								dari.biaya_omloop=jadi.omloop,
								dari.biaya_omloop2=jadi.omloop2,
								dari.biaya_omloop3=jadi.omloop3,
								dari.biaya_omloop4=jadi.omloop4,
								dari.biaya_omloop5=jadi.omloop5
								
	;
	
	select						dari.*,
								ind.nm_perawatan,
								ind.kelas,
								ind.kode_paket,
								jadi.*
		from				
		/*update*/			rsb221022021.operasi												dari
		inner join 			rsb221022021.paket_operasi									ind
			on 				dari.no_rawat=argNORAWAT
			and 				ind.kode_paket=dari.kode_paket
		inner join 			rsb221022021.paket_operasi									jadi
			on 				jadi.nm_perawatan=ind.nm_perawatan
			and 				jadi.kd_pj='-'
			and 				jadi.kelas=argJADI
		/*
		set dari.? = jadi.? 
		*/
	;
	
	
	
	
	select @GxPesan;
	
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for pxErr_BandingJumlahRegPeriksa
-- ----------------------------
DROP PROCEDURE IF EXISTS `pxErr_BandingJumlahRegPeriksa`;
delimiter ;;
CREATE PROCEDURE `pxErr_BandingJumlahRegPeriksa`()
BEGIN
	
	DECLARE
		CONTINUE
		HANDLER 
		FOR
		SQLEXCEPTION
	BEGIN
		GET
			DIAGNOSTICS
			CONDITION			1			@GxPesan		=	MESSAGE_TEXT,
													@GxNomor		=	MYSQL_ERRNO,
													@GxStatus 	= RETURNED_SQLSTATE
		;
	END
	;
	
	SET											@GxPesan			=	'',
													@GxNomor			=	0,
													@GxStatus 		= 0
	;


	set 					@dari 	= '2024-09-01',
								@hingga	= DATE_ADD(@dari,interval 180 day)
	;
	drop 
		temporary 
		table 
		if exists 	tmpAreg_periksa,tmpBreg_periksa,
								tmpApasien,tmpBpasien
	;
	set 					@sq	=	concat(
											"create temporary table tmpAreg_periksa",
											" select 		'reg_periksa' tabel, tgl_registrasi,count(no_rawat) jumlahA",
											" from 			rsb221022021_err.reg_periksa",
											" where 		tgl_registrasi between '",@dari,"' and '",@hingga,"'",
											" group by 	tgl_registrasi"
											)
	;
	prepare 			sq 
		from  			@sq;
	execute 			sq;
	set 					@sq = concat(
											"create temporary table tmpBreg_periksa",
											" select 		'reg_periksa' tabel, tgl_registrasi,count(no_rawat) jumlahB",
											" from 			rsb221022021.reg_periksa",
											" where 		tgl_registrasi between '",@dari,"' and '",@hingga,"'",
											" group by 	tgl_registrasi"
											)
	;
	prepare 			sq 
		from  			@sq;
	execute 			sq;
	select 				A.*,
								B.jumlahB,
								jumlahB-jumlahA selisih
		from 				tmpAreg_periksa 	A
		left join 	tmpBreg_periksa  	B
			on 				B.tgl_registrasi=A.tgl_registrasi
	;
	
	set 					@sq	=	concat(
											"create temporary table tmpApasien",
											" select 		'pasien' tabel, tgl_daftar,count(no_rkm_medis) jumlahA",
											" from 			rsb221022021_err.pasien",
											" where 		tgl_daftar between '",@dari,"' and '",@hingga,"'",
											" group by 	tgl_daftar"
											)
	;
	prepare 			sq 
		from  			@sq;
	execute 			sq;
	
	set 					@sq	=	concat(
											"create temporary table tmpBpasien",
											" select 		'pasien' tabel, tgl_daftar,count(no_rkm_medis) jumlahB",
											" from 			rsb221022021.pasien",
											" where 		tgl_daftar between '",@dari,"' and '",@hingga,"'",
											" group by 	tgl_daftar"
											)
	;
	prepare 			sq 
		from  			@sq;
	execute 			sq;
	
	select 				A.*,
								B.jumlahB,
								jumlahB-jumlahA selisih
		from 				tmpApasien A
		left join 	tmpBpasien B
			on 				B.tgl_daftar=A.tgl_daftar
	;
	
	
	
	
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for pxErr_BandingNoRawat
-- ----------------------------
DROP PROCEDURE IF EXISTS `pxErr_BandingNoRawat`;
delimiter ;;
CREATE PROCEDURE `pxErr_BandingNoRawat`()
px:BEGIN

drop temporary table if exists 	tmpa,tmpb,
																tmpab,tmpba,
																tmpc,
																tmpabcm,tmpabcmok,
																tmpsmrmktp
;
#create temporary table tmpmuat
create 
	temporary 
	table 					tmpa
	select 					apas.no_rkm_medis 						Ano_rkm_medis,
									apas.nm_pasien								Anm_pasien,
									apas.no_ktp										Ano_ktp,
									areg.tgl_registrasi						Atgl_registrasi,
									areg.no_rawat									Ano_rawat,
									areg.kd_poli 									Akd_poli,
									areg.status_lanjut						Astatus_lanjut
		from 					rsb221022021_err.pasien 			apas
		inner join 		rsb221022021_err.reg_periksa 	areg
			on 					areg.no_rkm_medis=apas.no_rkm_medis
			where 			areg.tgl_registrasi>='2024-09-01'
			order by 		areg.no_rawat
;
create 
	temporary 
	table 					tmpb
	select 					apas.no_rkm_medis							Bno_rkm_medis,
									apas.nm_pasien								Bnm_pasien,
									apas.no_ktp										Bno_ktp,
									areg.tgl_registrasi						Btgl_registrasi,
									areg.no_rawat									Bno_rawat,
									areg.kd_poli 									Bkd_poli,
									areg.status_lanjut						Bstatus_lanjut
		from 					rsb221022021.pasien 					apas
		inner join 		rsb221022021.reg_periksa 			areg
			on 					areg.no_rkm_medis=apas.no_rkm_medis
			where 			areg.tgl_registrasi between '2024-09-01' and '2024-10-18'
			order by 		areg.no_rawat
;

create
	temporary
	table 					tmpab
	select					tmpa.*,
									tmpb.*
		from 					tmpa
		left 	join 		tmpb
			on 					tmpb.Bno_rawat=tmpa.Ano_rawat
			and 				tmpb.Bno_ktp=tmpa.Ano_ktp
			and 				tmpb.Bnm_pasien=tmpa.Anm_pasien
			and 				tmpb.Btgl_registrasi=tmpa.Atgl_registrasi
			and 				tmpb.Bkd_poli=tmpa.Akd_poli
		where 				tmpb.Bno_rkm_medis is null
;

alter
	table 					tmpab
	drop						Bno_rkm_medis,
	drop						Bnm_pasien,
	drop 						Bno_ktp,
	drop						Btgl_registrasi,
	drop						Bno_rawat,
	drop 						Bkd_poli,
	drop 						Bstatus_lanjut
;

create
	temporary
	table 					tmpba
	select					tmpa.*,
									tmpb.*
		from 					tmpa
		right 	join 	tmpb
			on 					tmpb.Bno_rawat=tmpa.Ano_rawat
			and 				tmpb.Bno_ktp=tmpa.Ano_ktp
			and 				tmpb.Bnm_pasien=tmpa.Anm_pasien
			and 				tmpb.Btgl_registrasi=tmpa.Atgl_registrasi
			and 				tmpb.Bkd_poli=tmpa.Akd_poli
		where 				tmpa.Ano_rkm_medis is null
;

alter
	table 					tmpba
	drop						Ano_rkm_medis,
	drop						Anm_pasien,
	drop 						Ano_ktp,
	drop						Atgl_registrasi,
	drop						Ano_rawat,
	drop 						Akd_poli,
	drop 						Astatus_lanjut
;


create
	temporary
	table 					tmpc
	select					tmpab.*,
									tmpba.*
		from 					tmpab
		left 	join 		tmpba
			on 					tmpba.Bno_ktp=tmpab.Ano_ktp
			and 				tmpba.Bnm_pasien=tmpab.Anm_pasien
			and 				tmpba.Btgl_registrasi=tmpab.Atgl_registrasi
	union all
	select					tmpab.*,
									tmpba.*
		from 					tmpab
		right join 		tmpba
			on 					tmpba.Bno_ktp=tmpab.Ano_ktp
			and 				tmpba.Bnm_pasien=tmpab.Anm_pasien
			and 				tmpba.Btgl_registrasi=tmpab.Atgl_registrasi
		#where 				tmpa.Ano_rkm_medis is null
;

create
	temporary
	table 					tmpabcm
		select 				cm.*,
									tmpa.*,
									tmpb.*
		from 					rsb221022021_err.zcasemix cm
		left join 		tmpa
			on					tmpa.Anm_pasien=cm.nama
		left join 		tmpb
			on					tmpb.Bnm_pasien=cm.nama
			and 				tmpb.Bno_ktp=tmpa.Ano_ktp
			and 				tmpb.Btgl_registrasi=tmpa.Atgl_registrasi
			and 				tmpb.Bkd_poli=tmpa.Akd_poli
	
;
create
	temporary
	table 					tmpabcmok
	select 					Ano_rawat,
									Bno_rawat
		from 					tmpabcm
		where 				Ano_rawat is not null
			and 				Ano_rawat not like Bno_rawat
;

select * from tmpabcmok;

select 	a.*,
				b.*,
				c.*
	from 				tmpabcmok 										a
	left join 	rsb221022021_err.rawat_jl_dr 	b
		on 				b.no_rawat=a.Ano_rawat
	left join 	rsb221022021_err.rawat_jl_dr 	c
		on 				c.no_rawat=a.Bno_rawat
		and 			c.tgl_perawatan=b.tgl_perawatan
		and 			c.jam_rawat=b.jam_rawat
		and 			c.kd_jenis_prw=b.kd_jenis_prw
;
	



/*
leave px;
select * from tmpab where Anm_pasien in (
																				select nama from rsb221022021_err.zcasemix
																				);
select * from tmpba;
*/
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for pxErr_BandingzCasemix
-- ----------------------------
DROP PROCEDURE IF EXISTS `pxErr_BandingzCasemix`;
delimiter ;;
CREATE PROCEDURE `pxErr_BandingzCasemix`()
px:BEGIN

drop
	temporary
	table
	if EXISTS				tmpa,
									tmpb,
									tmpzcma,
									tmpupdate1
;

create 
	temporary 
	table 					tmpa
	select 					apas.no_rkm_medis 						Ano_rkm_medis,
									apas.nm_pasien								Anm_pasien,
									apas.no_ktp										Ano_ktp,
									areg.tgl_registrasi						Atgl_registrasi,
									areg.no_rawat									Ano_rawat,
									areg.kd_poli 									Akd_poli,
									areg.status_lanjut						Astatus_lanjut,
									max(areg.no_rawat)						Ano_rawat_z,
									max(areg.tgl_registrasi)			Atgl_registrasi_z
		from 					rsb221022021_err.pasien 			apas
		inner join 		rsb221022021_err.reg_periksa 	areg
			on 					areg.no_rkm_medis=apas.no_rkm_medis
			where 			areg.tgl_registrasi>='2024-09-01'
			group by 		areg.no_rawat
			order by 		areg.no_rawat
			
;

create 
	temporary 
	table 					tmpb
	select 					apas.no_rkm_medis 						Bno_rkm_medis,
									apas.nm_pasien								Bnm_pasien,
									apas.no_ktp										Bno_ktp,
									areg.tgl_registrasi						Btgl_registrasi,
									areg.no_rawat									Bno_rawat,
									areg.kd_poli 									Bkd_poli,
									areg.status_lanjut						Bstatus_lanjut,
									max(areg.no_rawat)						Bno_rawat_z,
									max(areg.tgl_registrasi)			Btgl_registrasi_z
		from 					rsb221022021.pasien 			apas
		inner join 		rsb221022021.reg_periksa 	areg
			on 					areg.no_rkm_medis=apas.no_rkm_medis
			where 			areg.tgl_registrasi >= '2024-09-01'
			group by 		areg.no_rawat
			order by 		areg.no_rawat
;

create
	temporary
	table						tmpzcma
	select 					
									'tmpzcma'												tmp,
									zcm.*,
									tmpa.*,
									tmpb.*
		from 					rsb221022021_err.zcasemix 			zcm
		left join 		tmpa
			on 					tmpa.Anm_pasien=zcm.nama
		left join 		tmpb
			on 					tmpb.Bnm_pasien=zcm.nama
			and 				tmpb.Bno_ktp=tmpa.Ano_ktp
			and 				tmpb.Btgl_registrasi=tmpa.Atgl_registrasi
			and 				tmpb.Bno_rawat_z=tmpa.Ano_rawat_z
	;
	
	
	create
		temporary
		table					tmpupdate1
		select 				Ano_rawat,
									Bno_rawat
			from 				tmpzcma
			where 			Bno_rawat_z IS NOT NULL
				and 			Ano_rawat_z=Bno_rawat_z
			
	;
	
	set 						
									@tabel 		=	'rawat_jl_drpr',
									@kode 		= 'kd_jenis_prw',
									@tanggal 	= 'tgl_perawatan',
									@jam 			= 'jam_rawat',
									@sq  			= 
									concat(
									"select 				ud.*,",
									"								a.no_rawat 						Anorawat,",
									"								a.<:kode:>								Akode,",
									"								a.<:tanggal:>								Atanggal,",
									"								a.<:jam:>										Ajam,",
									"								b.no_rawat							Bnorawat,",
									"								b.<:kode:>								Bkode,",
									"								b.<:tanggal:>								Btanggal,",
									"								b.<:jam:>										Bjam",
									"	from 					rsb221022021_err.tmpupdate1		ud",
									"	left join 		rsb221022021_err.rawat_jl_dr 	a",
									"		on 					a.no_rawat=ud.Ano_rawat",
									"	left join 		rsb221022021.<:tabel:> 				b",
									"		on 					b.no_rawat=ud.Bno_rawat",
									"		and 				b.<:kode:>=a.<:kode:>",
									"		and 				b.<:tanggal:>=a.<:tanggal:>",
									"		and 				b.<:jam:>=a.<:jam:>"
									),
									@sq = replace(@sq,'<:kode:>',@kode),
									@sq = replace(@sq,'<:tanggal:>',@tanggal),
									@sq = replace(@sq,'<:jam:>',@jam),
									@sq = replace(@sq,'<:tabel:>',@tabel)
	;
	
	prepare sq from @sq;
	execute sq;
	
select * from tmpupdate1;
