-- ----------------------------
-- Procedure structure for pxErr_Banding_copy1
-- ----------------------------
DROP PROCEDURE IF EXISTS `pxErr_Banding_copy1`;
delimiter ;;
CREATE PROCEDURE `pxErr_Banding_copy1`(IN arTABEL VARCHAR(250), IN arKODE VARCHAR(250), IN arTANGGAL VARCHAR(250), IN arJAM VARCHAR(250))
BEGIN

drop temporary table if exists 	tmpa,
																tmpb,
																tmpab,
																tmpaa,
																tmpbb,
																tmpaabb,
																tmpsudah,
																tmpbelum
;


create
	temporary
	table					tmpa
	select 				t.no_rawat										anorawat,
								t.kd_jenis_prw								akdrawat,
								t.tgl_perawatan								atanggal,
								t.jam_rawat										ajam,
								r.no_rkm_medis								anorm,
								p.no_ktp											anoktp,
								p.nm_pasien										anmpasien
		from 				rsb221022021_err.rawat_jl_dr	t
		inner join 	rsb221022021_err.reg_periksa 	r
			on 				r.no_rawat=t.no_rawat
		inner join 	rsb221022021_err.pasien 			p
			on 				p.no_rkm_medis=r.no_rkm_medis
		where 			t.tgl_perawatan	>= '2024-09-03'
		order by 		t.tgl_perawatan,
								t.jam_rawat,
								t.kd_jenis_prw
;

create
	temporary
	table					tmpb
	select 				t.no_rawat										bnorawat,
								t.kd_jenis_prw								bkdrawat,
								t.tgl_perawatan								btanggal,
								t.jam_rawat										bjam_rawat,
								r.no_rkm_medis								bnorm,
								p.no_ktp											bnoktp,
								p.nm_pasien										bnmpasien
		from 				rsb221022021.rawat_jl_dr	t
		inner join 	rsb221022021.reg_periksa 	r
			on 				r.no_rawat=t.no_rawat
		inner join 	rsb221022021.pasien 			p
			on 				p.no_rkm_medis=r.no_rkm_medis
		where 			t.tgl_perawatan	between '2024-09-03' and '2024-09-05'
		order by 		t.tgl_perawatan,
								t.jam_rawat,
								t.kd_jenis_prw
;

CREATE
	TEMPORARY
	TABLE					tmpab
select 					*
	from
	(
	select 				a.*,
								b.*
		from 				tmpa			a
		left join 	tmpb 			b
			on 				bnoktp=anoktp
			and 			btanggal=atanggal
			and 			bjam_rawat=ajam
			and 			bnorawat=anorawat
	union all
	select 				a.*,
								b.*
		from 				tmpa			a
		right join 	tmpb 			b
			on 				bnoktp=anoktp
			and 			btanggal=atanggal
			and 			bjam_rawat=ajam
			and 			bnorawat=anorawat
	) 						aT1
	where 				anorawat is null
		or 					bnorawat is null
;

create
	TEMPORARY
	table					tmpaa
	select 				*
		from 				tmpab
		where 			bnorawat is null
;

alter
	table 				tmpaa
	drop 					bnorawat,
	drop 					bnorm,
	drop 					bnmpasien,
	drop 					bnoktp,
	drop 					btanggal,
	drop 					bjam_rawat,
	drop 					bkdrawat
;


create
	TEMPORARY
	table					tmpbb
	select 				*
		from 				tmpab
		where 			anorawat is null
;


alter
	table 				tmpbb
	drop 					anorawat,
	drop 					anorm,
	drop 					anmpasien,
	drop 					anoktp,
	drop 					atanggal,
	drop 					ajam,
	drop 					akdrawat
;

create
	TEMPORARY
	table 				tmpaabb
select 					a.*,
								b.*
	from 					tmpaa			a
	left join 		tmpbb 		b
		on 					bnoktp=anoktp
		and 				bkdrawat=akdrawat
		and 				btanggal=atanggal
;

create
	TEMPORARY
	table 				tmpsudah
	select 				*
		from 				tmpaabb
		where 			bnorawat is not null
;


create
	TEMPORARY
	table 				tmpbelum
	select 				*
		from 				tmpaabb
		where 			bnorawat is null
;
#select * from tmpab;


select * from tmpsudah;
select * from tmpbelum;
				
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for pxErr_Norawat_Hilang
-- ----------------------------
DROP PROCEDURE IF EXISTS `pxErr_Norawat_Hilang`;
delimiter ;;
CREATE PROCEDURE `pxErr_Norawat_Hilang`(IN arTABEL VARCHAR(250), IN arKODE VARCHAR(250), IN arTANGGAL VARCHAR(250), IN arJAM VARCHAR(250))
px:BEGIN

DECLARE
		CONTINUE
		HANDLER 
		FOR
		SQLEXCEPTION
	BEGIN
		GET
			DIAGNOSTICS
			CONDITION			1			@GxPesan		=	MESSAGE_TEXT,
													@GxNomor		=	MYSQL_ERRNO,
													@GxStatus 	= RETURNED_SQLSTATE
		;
	END
	;
	
	SET											@GxPesan			=	'',
													@GxNomor			=	0,
													@GxStatus 		= 0,
													@xDokter 			=	''
	;
	
	select 			a.vchra,
					a.vchrb,
					a.data,
					b.no_rawat,
					json_detailed(json_extract(a.data,'$.biayagrup'))
	from 			rsb221022021.zzzdata_keuangan a
	left join 		rsb221022021.reg_periksa   b
	on 			b.no_rawat=a.vchra
	left join 		rsb221022021.operasi 			c
	on 			c.no_rawat=a.vchra
	where 		a.subpartisi='biayalayan-rawat'
	and 			a.vdata > '2025-01-01'
	and 			b.no_rawat is null
	and 			json_length(json_extract(a.data,'$.biayagrup')) > 1
	order by 		a.vchra
	;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for pxErr_ProsesInduk
-- ----------------------------
DROP PROCEDURE IF EXISTS `pxErr_ProsesInduk`;
delimiter ;;
CREATE PROCEDURE `pxErr_ProsesInduk`(IN arTABEL VARCHAR(250))
px:BEGIN

DECLARE
		CONTINUE
		HANDLER 
		FOR
		SQLEXCEPTION
	BEGIN
		GET
			DIAGNOSTICS
			CONDITION			1			@GxPesan		=	MESSAGE_TEXT,
													@GxNomor		=	MYSQL_ERRNO,
													@GxStatus 	= RETURNED_SQLSTATE
		;
	END
	;
	
	SET											@GxPesan			=	'',
													@GxNomor			=	0,
													@GxStatus 		= 0
	;
	


	select 			a.kd_jenis_prw,
							b.kd_jenis_prw
		from 			rsb221022021_err.jns_perawatan_inap 	a
		left join rsb221022021.jns_perawatan_inap 			b
			on 			b.kd_jenis_prw=a.kd_jenis_prw
		where 		b.kd_jenis_prw is null
	;
	select @GxPesan;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for pxErr_ProsesTindakan
-- ----------------------------
DROP PROCEDURE IF EXISTS `pxErr_ProsesTindakan`;
delimiter ;;
CREATE PROCEDURE `pxErr_ProsesTindakan`(IN arTABEL VARCHAR(250), IN arKODE VARCHAR(250), IN arTANGGAL VARCHAR(250), IN arJAM VARCHAR(250))
px:BEGIN

DECLARE
		CONTINUE
		HANDLER 
		FOR
		SQLEXCEPTION
	BEGIN
		GET
			DIAGNOSTICS
			CONDITION			1			@GxPesan		=	MESSAGE_TEXT,
													@GxNomor		=	MYSQL_ERRNO,
													@GxStatus 	= RETURNED_SQLSTATE
		;
	END
	;
	
	SET											@GxPesan			=	'',
													@GxNomor			=	0,
													@GxStatus 		= 0,
													@xDokter 			=	''
	;
	
	CASE
		WHEN 									arTABEL IN 	(
																			'rawat_jl_dr',
																			'rawat_jl_drpr',
																			'rawat_inap_dr',
																			'rawat_inap_drpr',
																			'periksa_lab',
																			'periksa_radiologi'
																			)	THEN
																				SET @xDokter  = 'kd_dokter';
		WHEN 									arTABEL IN 	(
																			'rawat_jl_pr',
																			'rawat_inap_pr'
																			)	THEN
																				SET @xDokter  = 'nip';
		ELSE																SET @xDokter  = '';
	END CASE
	;

drop temporary table if exists 	tmpa,#DATA LAMA
																tmpb,#DATA BARU
																tmpc,#NORAWAT LAMA YANG TIDAK ADA DI BARU
																tmpab,#JOIN LAMA DAN BARU
																tmpabc,
																tmpdata,
																tmpreg
;



#DATA LAMA
set							@sq = concat(
											"create",
											"	temporary",
											"	table					tmpa",
											"	select 				t.no_rawat										anorawat,",
											"								t.",@xDokter,"								akddokter,",
											"								",arKODE,"										akdrawat,",
											"								",arTANGGAL,"									atanggal,",
											"								",arJAM,"											ajam,",
											"								r.no_rkm_medis								anorm,",
											"								p.no_ktp											anoktp,",
											"								p.nm_pasien										anmpasien",
											"		from 				rsb221022021_err.",arTABEL,"	t",
											"		inner join 	rsb221022021_err.reg_periksa 	r",
											"			on 				r.no_rawat=t.no_rawat",
											"		inner join 	rsb221022021_err.pasien 			p",
											"			on 				p.no_rkm_medis=r.no_rkm_medis",
											"		where 			",arTANGGAL,"	>= '2024-09-01'",
											"		order by 		",arTANGGAL,",",
											"								",arJAM,",",
											"								",arKODE," "
											)
;

#select @sq;
prepare sq from @sq;
execute sq;

#DATA BARU
set							@sq = concat(
											"create",
											"	temporary",
											"	table					tmpb",
											"	select 				t.no_rawat									bnorawat,",
											"								t.",@xDokter,"							bkddokter,",
											"								",arKODE,"									bkdrawat,",
											"								",arTANGGAL,"								btanggal,",
											"								",arJAM,"										bjam,",
											"								r.no_rkm_medis							bnorm,",
											"								p.no_ktp										bnoktp,",
											"								p.nm_pasien									bnmpasien",
											"		from 				rsb221022021.",arTABEL,"		t",
											"		inner join 	rsb221022021.reg_periksa 		r",
											"			on 				r.no_rawat=t.no_rawat",
											"		inner join 	rsb221022021.pasien 			p",
											"			on 				p.no_rkm_medis=r.no_rkm_medis",
											"		where 			",arTANGGAl,"	>= '2024-09-01'",
											#"		where 			",arTANGGAl,"	between '2024-09-03' and '2024-09-10' ",
											"		order by 		",arTANGGAL,",",
											"								",arJAM,",",
											"								",arKODE," "
												)
;

prepare sq from @sq;
execute sq;


#MENCARI YANG DATA LAMA YANG TIDAK ADA DI DATA BARU ( BELUM DIENTRI ULANG )
create
	temporary
	table 					tmpab
	select 					a.*,
									b.*
		from 					tmpa			a
		left join 		tmpb 			b
			on 					bnoktp=anoktp
			and 				bnmpasien=anmpasien
			and 				bkdrawat=akdrawat
			and 				bkddokter=akddokter
			and 				btanggal=atanggal
			and 				bjam=ajam
			and 				b.bnorawat=a.anorawat
		where 				b.bnorawat is null
#where a.anorawat = '2024/08/29/000205'
;

#select @GxPesan;

alter
	table 					tmpab
	drop  					bnorawat,
	drop 						bkdrawat,
	drop 						bkddokter,
	drop 						btanggal,
	drop 						bjam,
	drop 						bnorm,
	drop 						bnoktp,
	drop 						bnmpasien	
;


create
	temporary
	table 					tmpabc
	select 					a.*,
									b.*
		from 					tmpab			a
		left join 		tmpb 			b
			on 					bnoktp=anoktp
			and 				bnmpasien=anmpasien
			and 				bkdrawat=akdrawat
			and 				bkddokter=akddokter
			and 				btanggal=atanggal
		where 				ifnull(a.anorawat,'') not like ifnull(b.bnorawat,'')
#where a.anorawat = '2024/08/29/000205'
;


alter
	table 					tmpabc
	drop 						anorm,
	drop 						anoktp,
	drop 						anmpasien,
	drop 						bkdrawat,
	drop 						bkddokter,
	drop 						btanggal,
	drop 						bjam,
	drop 						bnorm,
	drop 						bnoktp,
	drop 						bnmpasien	
;

set 							@sq = 
									concat(
									"create temporary table tmpreg",
									#"insert ignore into rsb221022021.",arTABEL," ",
									#"insert into rsb221022021.",arTABEL," ",#BUAT LIHAT ERRO SAAT INSERT
									"	select 			",
									#"							a.bnorawat,"
									"							b.*",
									"	from 				tmpabc 												a",
									"	inner join 	rsb221022021_err.",arTABEL," 	b",
									"		on 				b.no_rawat			=a.anorawat",
									"		and				",@xDokter,"		=a.akddokter",
									"		and 			",arKODE,"			=a.akdrawat",
									"		and 			",arTANGGAL,"		=a.atanggal",
									"		and 			",arJAM,"				=a.ajam",
									"	where 			bnorawat is null"
									#"		where anorawat = '2024/09/04/000090'"
									" "
									)
;

prepare 					sq
	from 						@sq
;
execute 					sq;

select						a.*,
									b.no_rawat,
									c.nm_pasien,
									c.no_rkm_medis,
									d.nm_pasien,
									d.no_rkm_medis
	from 						rsb221022021_err.reg_periksa  a
	left join 			rsb221022021.reg_periksa 			b
		on 						b.no_rawat=a.no_rawat
	left join   		rsb221022021_err.pasien 			c
		on 						c.no_rkm_medis=a.no_rkm_medis
	left join 			rsb221022021.pasien 					d
		on 						d.nm_pasien=c.nm_pasien
		and 					d.no_ktp=c.no_ktp
		and 					d.tgl_lahir=c.tgl_lahir
	where 					b.no_rawat is null
;


#select * from tmpreg;
select @GxPesan;

END
;;
delimiter ;

