											"		inner join 	rsb221022021_err.reg_periksa 	r",
											"			on 				r.no_rawat=t.no_rawat",
											"		inner join 	rsb221022021_err.pasien 			p",
											"			on 				p.no_rkm_medis=r.no_rkm_medis",
											"		where 			",arTANGGAL,"	>= '2024-09-01'",
											"		order by 		",arTANGGAL,",",
											"								",arJAM,",",
											"								",arKODE," "
											)
;

#select @sq;
prepare sq from @sq;
execute sq;

#DATA BARU
set							@sq = concat(
											"create",
											"	temporary",
											"	table					tmpb",
											"	select 				t.no_rawat									bnorawat,",
											"								t.",@xDokter,"							bkddokter,",
											"								",arKODE,"									bkdrawat,",
											"								",arTANGGAL,"								btanggal,",
											"								",arJAM,"										bjam,",
											"								r.no_rkm_medis							bnorm,",
											"								p.no_ktp										bnoktp,",
											"								p.nm_pasien									bnmpasien",
											"		from 				rsb221022021.",arTABEL,"		t",
											"		inner join 	rsb221022021.reg_periksa 		r",
											"			on 				r.no_rawat=t.no_rawat",
											"		inner join 	rsb221022021.pasien 			p",
											"			on 				p.no_rkm_medis=r.no_rkm_medis",
											"		where 			",arTANGGAl,"	>= '2024-09-01'",
											#"		where 			",arTANGGAl,"	between '2024-09-03' and '2024-09-10' ",
											"		order by 		",arTANGGAL,",",
											"								",arJAM,",",
											"								",arKODE," "
												)
;

prepare sq from @sq;
execute sq;


#MENCARI YANG DATA LAMA YANG TIDAK ADA DI DATA BARU ( BELUM DIENTRI ULANG )
create
	temporary
	table 					tmpab
	select 					a.*,
									b.*
		from 					tmpa			a
		left join 		tmpb 			b
			on 					bnoktp=anoktp
			and 				bnmpasien=anmpasien
			and 				bkdrawat=akdrawat
			and 				bkddokter=akddokter
			and 				btanggal=atanggal
			and 				bjam=ajam
			and 				b.bnorawat=a.anorawat
		where 				b.bnorawat is null
#where a.anorawat = '2024/08/29/000205'
;

#select @GxPesan;

alter
	table 					tmpab
	drop  					bnorawat,
	drop 						bkdrawat,
	drop 						bkddokter,
	drop 						btanggal,
	drop 						bjam,
	drop 						bnorm,
	drop 						bnoktp,
	drop 						bnmpasien	
;


create
	temporary
	table 					tmpabc
	select 					a.*,
									b.*
		from 					tmpab			a
		left join 		tmpb 			b
			on 					bnoktp=anoktp
			and 				bnmpasien=anmpasien
			and 				bkdrawat=akdrawat
			and 				bkddokter=akddokter
			and 				btanggal=atanggal
		where 				ifnull(a.anorawat,'') not like ifnull(b.bnorawat,'')
#where a.anorawat = '2024/08/29/000205'
;


alter
	table 					tmpabc
	drop 						anorm,
	drop 						anoktp,
	drop 						anmpasien,
	drop 						bkdrawat,
	drop 						bkddokter,
	drop 						btanggal,
	drop 						bjam,
	drop 						bnorm,
	drop 						bnoktp,
	drop 						bnmpasien	
;

set 							@sq = 
									concat(
									"insert into 	rsb221022021_err.rawat_inap_dr_00",
									#"	select 			*"
									"	select 			",
									#"							a.bnorawat,"
									"							b.*",
									"	from 				tmpabc 												a",
									"	inner join 	rsb221022021_err.",arTABEL," 	b",
									"		on 				b.no_rawat			=a.anorawat",
									"		and				",@xDokter,"		=a.akddokter",
									"		and 			",arKODE,"			=a.akdrawat",
									"		and 			",arTANGGAL,"		=a.atanggal",
									"		and 			",arJAM,"				=a.ajam",
									"	where 			bnorawat is null"
									" "
									)
;

prepare 					sq
	from 						@sq
;
execute 					sq;

#select * from tmpdata;
select @GxPesan;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for pxPenilaianAwalUlang
-- ----------------------------
DROP PROCEDURE IF EXISTS `pxPenilaianAwalUlang`;
delimiter ;;
CREATE PROCEDURE `pxPenilaianAwalUlang`()
  COMMENT 'penanda penilain awal ulang dengan angka saja'
px:BEGIN
	
	declare vmod int default 4;
	declare vbataswaktu int default 4;
	declare vtanggala date default DATE_ADD(now(),interval -3 month);
	declare vtanggalz date default date(now());
	
	DECLARE
		CONTINUE
		HANDLER
		FOR
		SQLEXCEPTION
	BEGIN
		GET
			DIAGNOSTICS
			CONDITION			1				@GxPesan		=	MESSAGE_TEXT,
														@GxNomor		=	MYSQL_ERRNO,
														@GxStatus 	= RETURNED_SQLSTATE
		;
	END
	;
	
	SET												@GxPesan			=	'',
														@GxNomor			=	0,
														@GxStatus 		= 0
	;
	
	drop 
		temporary 
		table 
		if exists 							tmppak;
	create 
		temporary 
		table 									tmppak
		select 									b.norm,
														b.poli,
														mod(b.ke,vmod)		ke
														#,vtanggala,vtanggalz
			from									rsb221022021.reg_periksa a
			left join 						(
														select 			no_rkm_medis 				norm,
																				kd_poli    					poli,
																				count(no_rkm_medis) ke
															from 			rsb221022021.reg_periksa
															where 		tgl_registrasi between vtanggala and vtanggalz
															group by 	no_rkm_medis,kd_poli
														) b
				on 									b.norm=a.no_rkm_medis
					and 							b.poli=a.kd_poli
					
				where 							a.tgl_registrasi = date(now())
			
	;
	
	
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for pxPenilaianAwalUlang2
-- ----------------------------
DROP PROCEDURE IF EXISTS `pxPenilaianAwalUlang2`;
delimiter ;;
CREATE PROCEDURE `pxPenilaianAwalUlang2`()
px:BEGIN
	
	declare vmod int default 4;
	declare vbataswaktu int default 4;
	declare vtanggala date default DATE_ADD(now(),interval -4 month);
	declare vtanggalz date default date(now());
	
	DECLARE
		CONTINUE
		HANDLER
		FOR
		SQLEXCEPTION
	BEGIN
		GET
			DIAGNOSTICS
			CONDITION			1				@GxPesan		=	MESSAGE_TEXT,
														@GxNomor		=	MYSQL_ERRNO,
														@GxStatus 	= RETURNED_SQLSTATE
		;
	END
	;
	
	SET												@GxPesan			=	'',
														@GxNomor			=	0,
														@GxStatus 		= 0
	;
	
	drop temporary table if exists tmppak;
	create temporary table 		tmppak
	select 										norm,poli,concat(mod(jumlah,vmod),' ',tanggal,' | Kel : ',kelut,if(rencana='','',concat(' | Ren : ',rencana))) catatan from (
			select 								norm,poli,tanggal,kelut,rencana,count(poli) jumlah from (
					select 						norm,poli,tglreg,tanggal,kelut,rencana from (
							select 				pasreg.no_rkm_medis norm,
														riwreg.no_rawat,
														riwreg.tgl_registrasi tglreg,
														riwreg.kd_poli,
														#paralan.tanggal,
														
														concat(
														ifnull(replace(paralan.no_rawat,	paralan.no_rawat,	riwreg.kd_poli),''),
														ifnull(replace(paigd.no_rawat,		paigd.no_rawat,		riwreg.kd_poli),''),
														ifnull(replace(paog.no_rawat,			paog.no_rawat,		riwreg.kd_poli),''),
														ifnull(replace(pagi.no_rawat,			pagi.no_rawat,		riwreg.kd_poli),''),
														ifnull(replace(paby.no_rawat,			paby.no_rawat,		riwreg.kd_poli),''),
														ifnull(replace(papsi.no_rawat,		papsi.no_rawat,		riwreg.kd_poli),''),
														ifnull(replace(pager.no_rawat,		pager.no_rawat,		riwreg.kd_poli),'')
														#ifnull(replace(pamata.no_rawat,		pamata.no_rawat,	riwreg.kd_poli),'')
														) 																						poli,
														
														ifnull(paralan.no_rawat,'')										paralan,
														ifnull(paigd.no_rawat,'')											paigd,
														ifnull(paog.no_rawat,'') 											pakebidanan,
														ifnull(pagi.no_rawat,'') 											pagigi,
														ifnull(paby.no_rawat,'') 											pabayi,
														ifnull(papsi.no_rawat,'') 										papsikiatri,
														ifnull(pager.no_rawat,'') 										pageriatri,
														#ifnull(pamata.no_rawat,'') 										pamata
														
														
														concat(
														ifnull(paralan.tanggal,''),										#tglralan,
														ifnull(paigd.tanggal,''),											#tgligd,
														ifnull(paog.tanggal,''), 											#tglkebidanan,
														ifnull(pagi.tanggal,''), 											#tglgigi,
														ifnull(paby.tanggal,''), 											#tglbayi,
														ifnull(papsi.tanggal,''), 											#tglpsikiatri,
														ifnull(pager.tanggal,'') 											#tglgeriatri,
														#ifnull(pamata.tanggal,'') 										padmata
														) 			tanggal,
														
														concat(
														ifnull(paralan.keluhan_utama,'')							,#kelutralan,
														ifnull(paigd.keluhan_utama,'')								,#kelutigd,
														ifnull(paog.keluhan_utama,'') 								,#kelutkebidanan,
														ifnull(pagi.keluhan_utama,'') 								,#kelutgigi,
														ifnull(paby.keluhan_utama,'') 								,#kelutbayi,
														ifnull(papsi.keluhan_utama,'') 								,#kelutpsikiatri,
														ifnull(pager.keluhan_utama,'') 								#kelutgeriatri
														#ifnull(pamata.no_rawat,'') 										padmata
														)   kelut,
														
														
														concat(
														ifnull(paralan.rencana,'')							,#kelutralan,
														ifnull(paigd.rencana,'')								,#kelutigd,
														#ifnull(paog.rencana,'') 								,#kelutkebidanan,
														ifnull(pagi.rencana,'') 								,#kelutgigi,
														ifnull(paby.rencana,'') 								,#kelutbayi,
														ifnull(papsi.rencana,'') 								,#kelutpsikiatri,
														ifnull(pager.rencana,'') 								#kelutgeriatri
														#ifnull(pamata.no_rawat,'') 										padmata
														)   rencana
														
														
													
							from 					reg_periksa 																	pasreg
							left join 		reg_periksa																		riwreg
								on 					riwreg.no_rkm_medis=pasreg.no_rkm_medis	
							left join			penilaian_awal_keperawatan_ralan 							paralan
								on 					paralan.no_rawat=riwreg.no_rawat
								and 				date(paralan.tanggal) between vtanggala and vtanggalz
								
							left join			penilaian_awal_keperawatan_igd 								paigd
								on 					paigd.no_rawat=riwreg.no_rawat
								and 				date(paigd.tanggal) between vtanggala and vtanggalz
							
							left join			penilaian_awal_keperawatan_kebidanan 					paog
								on 					paog.no_rawat=riwreg.no_rawat
								and 				date(paog.tanggal) between vtanggala and vtanggalz
							
							left join			penilaian_awal_keperawatan_gigi 							pagi
								on 					pagi.no_rawat=riwreg.no_rawat
								and 				date(pagi.tanggal) between vtanggala and vtanggalz
							
							left join			penilaian_awal_keperawatan_ralan_bayi 				paby
								on 					paby.no_rawat=riwreg.no_rawat
								and 				date(paby.tanggal) between vtanggala and vtanggalz
							
							left join			penilaian_awal_keperawatan_ralan_psikiatri 		papsi
								on 					papsi.no_rawat=riwreg.no_rawat
								and 				date(papsi.tanggal) between vtanggala and vtanggalz
							
							left join			penilaian_awal_keperawatan_ralan_geriatri 		pager
								on 					pager.no_rawat=riwreg.no_rawat
								and 				date(pager.tanggal) between vtanggala and vtanggalz
							
							
							#left join			penilaian_awal_keperawatan_mata 							pamata
							#	on 					pamata.no_rawat=riwreg.no_rawat
							
							where 				pasreg.tgl_registrasi = date(now())
								and 				pasreg.status_lanjut = 'ralan'
								and 				pasreg.stts not in ('batal')
#and pasreg.no_rkm_medis='041171'

							group by 			pasreg.no_rkm_medis,riwreg.no_rawat
							
							
							order by 			paralan.tanggal desc
							
					) 								aT1 where poli not like '' order by tglreg
			)											aT2 group by norm, poli 
	) 												aT3
	;
	
	#select @GxPesan;
	
select *  from tmppak;
	
END
;;
delimiter ;

