-- ----------------------------
-- Procedure structure for pxTabel
-- ----------------------------
DROP PROCEDURE IF EXISTS `pxTabel`;
delimiter ;;
CREATE PROCEDURE `pxTabel`(IN PARAM JSON)
px:BEGIN
	DECLARE									p  					JSON 					DEFAULT PARAM;
	DECLARE									pTx 				VARCHAR(250)	DEFAULT JSON_UNQUOTE(JSON_EXTRACT(p,'$.tx'));
	
	DECLARE 								vTeks				TEXT;
	
	DECLARE 								vJumlah,
													vHitung 		INT DEFAULT 0;

	DECLARE
		CONTINUE 
		HANDLER 
		FOR
		SQLEXCEPTION
	BEGIN
		GET
			DIAGNOSTICS
			CONDITION			1			@GxPesan		=	MESSAGE_TEXT,
													@GxNomor		=	MYSQL_ERRNO,
													@GxStatus 	= RETURNED_SQLSTATE
		;
	END
	;
	
	SET											@GxPesan			=	'',
													@GxNomor			=	0,
													@GxStatus 		= 0
	;
	
	#select aaa from rsb221022021.pasien;
	#select @pxTabel_GxPesan,@pxTabel_GxNomor,@pxTabel_GxStatus;
	
	CASE 										pTx
		WHEN 									'+zzzdata' THEN#{"tx":"+"}
			CREATE
					TABLE						rsb221022021.zzzdata
													(
													id						BIGINT									AUTO_INCREMENT,
													waktu					TIMESTAMP 							DEFAULT CURRENT_TIMESTAMP,
													waktuu				TIMESTAMP 							DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
													status 				INT 										DEFAULT 1 COMMENT '0=nonaktif. 1=awal. 2=siap dilanjutkan',
													partisi 			VARCHAR(250)						DEFAULT '',
													subpartisi 		VARCHAR(250)						DEFAULT '',
													data 					JSON 										DEFAULT JSON_OBJECT(),
													cari 					VARCHAR(500) 						DEFAULT '',
													via 					VARCHAR(250)						GENERATED ALWAYS AS ( IFNULL(JSON_UNQUOTE(JSON_EXTRACT(data, '$.indek.a')),'')) VIRTUAL,
													vib 					VARCHAR(250)						GENERATED ALWAYS AS ( IFNULL(JSON_UNQUOTE(JSON_EXTRACT(data, '$.indek.b')),'')) VIRTUAL,
													vic 					VARCHAR(250)						GENERATED ALWAYS AS ( IFNULL(JSON_UNQUOTE(JSON_EXTRACT(data, '$.indek.c')),'')) VIRTUAL,
													vid 					VARCHAR(250)						GENERATED ALWAYS AS ( IFNULL(JSON_UNQUOTE(JSON_EXTRACT(data, '$.indek.d')),'')) VIRTUAL,
													vie 					VARCHAR(250)						GENERATED ALWAYS AS ( IFNULL(JSON_UNQUOTE(JSON_EXTRACT(data, '$.indek.e')),'')) VIRTUAL,
													vif 					VARCHAR(250)						GENERATED ALWAYS AS ( IFNULL(JSON_UNQUOTE(JSON_EXTRACT(data, '$.indek.f')),'')) VIRTUAL,
													vig 					VARCHAR(250)						GENERATED ALWAYS AS ( IFNULL(JSON_UNQUOTE(JSON_EXTRACT(data, '$.indek.g')),'')) VIRTUAL,
													vih 					VARCHAR(250)						GENERATED ALWAYS AS ( IFNULL(JSON_UNQUOTE(JSON_EXTRACT(data, '$.indek.h')),'')) VIRTUAL,
													vii 					VARCHAR(250)						GENERATED ALWAYS AS ( IFNULL(JSON_UNQUOTE(JSON_EXTRACT(data, '$.indek.i')),'')) VIRTUAL,
													vij 					VARCHAR(250)						GENERATED ALWAYS AS ( IFNULL(JSON_UNQUOTE(JSON_EXTRACT(data, '$.indek.j')),'')) VIRTUAL,
													vik 					VARCHAR(250)						GENERATED ALWAYS AS ( IFNULL(JSON_UNQUOTE(JSON_EXTRACT(data, '$.indek.k')),'')) VIRTUAL,
													vil 					VARCHAR(250)						GENERATED ALWAYS AS ( IFNULL(JSON_UNQUOTE(JSON_EXTRACT(data, '$.indek.l')),'')) VIRTUAL,
													vim 					VARCHAR(250)						GENERATED ALWAYS AS ( IFNULL(JSON_UNQUOTE(JSON_EXTRACT(data, '$.indek.m')),'')) VIRTUAL,
													vin 					VARCHAR(250)						GENERATED ALWAYS AS ( IFNULL(JSON_UNQUOTE(JSON_EXTRACT(data, '$.indek.n')),'')) VIRTUAL,
													vio 					VARCHAR(250)						GENERATED ALWAYS AS ( IFNULL(JSON_UNQUOTE(JSON_EXTRACT(data, '$.indek.o')),'')) VIRTUAL,
													vip 					VARCHAR(250)						GENERATED ALWAYS AS ( IFNULL(JSON_UNQUOTE(JSON_EXTRACT(data, '$.indek.p')),'')) VIRTUAL,
													viq 					VARCHAR(250)						GENERATED ALWAYS AS ( IFNULL(JSON_UNQUOTE(JSON_EXTRACT(data, '$.indek.q')),'')) VIRTUAL,
													vir 					VARCHAR(250)						GENERATED ALWAYS AS ( IFNULL(JSON_UNQUOTE(JSON_EXTRACT(data, '$.indek.r')),'')) VIRTUAL,
													vis 					VARCHAR(250)						GENERATED ALWAYS AS ( IFNULL(JSON_UNQUOTE(JSON_EXTRACT(data, '$.indek.s')),'')) VIRTUAL,
													vit 					VARCHAR(250)						GENERATED ALWAYS AS ( IFNULL(JSON_UNQUOTE(JSON_EXTRACT(data, '$.indek.t')),'')) VIRTUAL,
													viu 					VARCHAR(250)						GENERATED ALWAYS AS ( IFNULL(JSON_UNQUOTE(JSON_EXTRACT(data, '$.indek.u')),'')) VIRTUAL,
													viv 					VARCHAR(250)						GENERATED ALWAYS AS ( IFNULL(JSON_UNQUOTE(JSON_EXTRACT(data, '$.indek.v')),'')) VIRTUAL,
													viw 					VARCHAR(250)						GENERATED ALWAYS AS ( IFNULL(JSON_UNQUOTE(JSON_EXTRACT(data, '$.indek.w')),'')) VIRTUAL,
													vix 					VARCHAR(250)						GENERATED ALWAYS AS ( IFNULL(JSON_UNQUOTE(JSON_EXTRACT(data, '$.indek.x')),'')) VIRTUAL,
													viy 					VARCHAR(250)						GENERATED ALWAYS AS ( IFNULL(JSON_UNQUOTE(JSON_EXTRACT(data, '$.indek.y')),'')) VIRTUAL,
													viz 					VARCHAR(250)						GENERATED ALWAYS AS ( IFNULL(JSON_UNQUOTE(JSON_EXTRACT(data, '$.indek.z')),'')) VIRTUAL,
													PRIMARY KEY		(
																				id,
																				partisi,
																				subpartisi
																				),
													INDEX 				(id),
													INDEX 				(partisi),
													INDEX 				(subpartisi),
													INDEX 				(status),
													INDEX 				(cari),
													INDEX 				(via),
													INDEX 				(vib),
													INDEX 				(vic),
													INDEX 				(vid),
													INDEX 				(vie),
													INDEX 				(vif),
													INDEX 				(vig),
													INDEX 				(vih),
													INDEX 				(vii),
													INDEX 				(vij),
													INDEX 				(vik),
													INDEX 				(vil),
													INDEX 				(vim),
													INDEX 				(vin),
													INDEX 				(vio),
													INDEX 				(vip),
													INDEX 				(viq),
													INDEX 				(vir),
													INDEX 				(vis),
													INDEX 				(vit),
													INDEX 				(viu),
													INDEX 				(viv),
													INDEX 				(viw),
													INDEX 				(vix),
													INDEX 				(viy),
													INDEX 				(viz)
													)
													PARTITION BY 	LIST 														COLUMNS (partisi)
														(
														PARTITION 	x 															VALUES IN (''),
														PARTITION 	tembolok 												VALUES IN ('tembolok'),
														PARTITION 	tugas														VALUES IN ('tugas'),
														PARTITION 	pengguna												VALUES IN ('pengguna'),
														PARTITION 	keu_jasadokter_sementara				VALUES IN ('keu_jasadokter_sementara'),#parkir jasa dokter sementara
														PARTITION 	keu_jasadokter_gagal						VALUES IN ('keu_jasadokter_gagal'),
														PARTITION 	keu_jasadokter_muat							VALUES IN ('keu_jasadokter_muat'),
														PARTITION 	keu_jasadokter_hitung						VALUES IN ('keu_jasadokter_hitung'),
														PARTITION 	keu_jasadokter_bayar						VALUES IN ('keu_jasadokter_bayar'),
														PARTITION 	keu_jasadokter_kembali					VALUES IN ('keu_jasadokter_kembali'),
														PARTITION 	keu_jasadokter_pending					VALUES IN ('keu_jasadokter_pending'),
														PARTITION 	keu_jasadokter_verpas						VALUES IN ('keu_jasadokter_verpas'),
														PARTITION 	keu_jasadokter_batal						VALUES IN ('keu_jasadokter_batal'),
														PARTITION 	keu_jasadokter_total						VALUES IN ('keu_jasadokter_total'),#jasa dokter total
														PARTITION 	keu_jasadokter_tambahan					VALUES IN ('keu_jasadokter_tambahan'),#tambahan
														PARTITION 	keu_jasadokter_potongan					VALUES IN ('keu_jasadokter_potongan'),#piutang, diskon, pemabyaran piutang
														PARTITION 	keu_jasadokter_revisi						VALUES IN ('keu_jasadokter_revisi'),#revisi pada yang sudah dibayar
														PARTITION 	keu_jasadokter_revisiganda			VALUES IN ('keu_jasadokter_revisiganda'),#revisi bayar ganda
														PARTITION 	keu_jasadokter_analisa					VALUES IN ('keu_jasadokter_analisa'),#untuk menganalisa
														PARTITION 	keu_jasadokter_jknx							VALUES IN ('keu_jasadokter_jknx'),
														
														PARTITION 	keu_biayarawat									VALUES IN ('keu_biayarawat')#untuk menganalisa
														
														)
				;
				
				select @GxPesan;
		
		
		
		WHEN 									'+zzzdata_jkn_sep' THEN#{"tx":"+zzzdata_jkn_sep"}
			CREATE
					TABLE						rsb221022021.zzzdata_jkn_sep
													(
													#id						BIGINT									AUTO_INCREMENT,
													waktu					TIMESTAMP 							DEFAULT CURRENT_TIMESTAMP,
													waktuu				TIMESTAMP 							DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
													status 				INT 										DEFAULT 1 COMMENT '0=nonaktif. 1=awal. 2=siap dilanjutkan',
													partisi 			VARCHAR(250)						DEFAULT '',
													subpartisi 		VARCHAR(250)						DEFAULT '',
													data 					JSON 										DEFAULT JSON_OBJECT(),
													cari 					VARCHAR(500) 						DEFAULT '',
													via 					VARCHAR(250)						GENERATED ALWAYS AS ( IFNULL(JSON_UNQUOTE(JSON_EXTRACT(data, '$.indek.a')),'')) VIRTUAL,
													vib 					VARCHAR(250)						GENERATED ALWAYS AS ( IFNULL(JSON_UNQUOTE(JSON_EXTRACT(data, '$.indek.b')),'')) VIRTUAL,
													vic 					VARCHAR(250)						GENERATED ALWAYS AS ( IFNULL(JSON_UNQUOTE(JSON_EXTRACT(data, '$.indek.c')),'')) VIRTUAL,
													vid 					VARCHAR(250)						GENERATED ALWAYS AS ( IFNULL(JSON_UNQUOTE(JSON_EXTRACT(data, '$.indek.d')),'')) VIRTUAL,
													vie 					VARCHAR(250)						GENERATED ALWAYS AS ( IFNULL(JSON_UNQUOTE(JSON_EXTRACT(data, '$.indek.e')),'')) VIRTUAL,
													vif 					VARCHAR(250)						GENERATED ALWAYS AS ( IFNULL(JSON_UNQUOTE(JSON_EXTRACT(data, '$.indek.f')),'')) VIRTUAL,
													vig 					VARCHAR(250)						GENERATED ALWAYS AS ( IFNULL(JSON_UNQUOTE(JSON_EXTRACT(data, '$.indek.g')),'')) VIRTUAL,
													vih 					VARCHAR(250)						GENERATED ALWAYS AS ( IFNULL(JSON_UNQUOTE(JSON_EXTRACT(data, '$.indek.h')),'')) VIRTUAL,
													vii 					VARCHAR(250)						GENERATED ALWAYS AS ( IFNULL(JSON_UNQUOTE(JSON_EXTRACT(data, '$.indek.i')),'')) VIRTUAL,
													vij 					VARCHAR(250)						GENERATED ALWAYS AS ( IFNULL(JSON_UNQUOTE(JSON_EXTRACT(data, '$.indek.j')),'')) VIRTUAL,
													vik 					VARCHAR(250)						GENERATED ALWAYS AS ( IFNULL(JSON_UNQUOTE(JSON_EXTRACT(data, '$.indek.k')),'')) VIRTUAL,
													vil 					VARCHAR(250)						GENERATED ALWAYS AS ( IFNULL(JSON_UNQUOTE(JSON_EXTRACT(data, '$.indek.l')),'')) VIRTUAL,
													vim 					VARCHAR(250)						GENERATED ALWAYS AS ( IFNULL(JSON_UNQUOTE(JSON_EXTRACT(data, '$.indek.m')),'')) VIRTUAL,
													vin 					VARCHAR(250)						GENERATED ALWAYS AS ( IFNULL(JSON_UNQUOTE(JSON_EXTRACT(data, '$.indek.n')),'')) VIRTUAL,
													vio 					VARCHAR(250)						GENERATED ALWAYS AS ( IFNULL(JSON_UNQUOTE(JSON_EXTRACT(data, '$.indek.o')),'')) VIRTUAL,
													vip 					VARCHAR(250)						GENERATED ALWAYS AS ( IFNULL(JSON_UNQUOTE(JSON_EXTRACT(data, '$.indek.p')),'')) VIRTUAL,
													viq 					VARCHAR(250)						GENERATED ALWAYS AS ( IFNULL(JSON_UNQUOTE(JSON_EXTRACT(data, '$.indek.q')),'')) VIRTUAL,
													vir 					VARCHAR(250)						GENERATED ALWAYS AS ( IFNULL(JSON_UNQUOTE(JSON_EXTRACT(data, '$.indek.r')),'')) VIRTUAL,
													vis 					VARCHAR(250)						GENERATED ALWAYS AS ( IFNULL(JSON_UNQUOTE(JSON_EXTRACT(data, '$.indek.s')),'')) VIRTUAL,
													vit 					VARCHAR(250)						GENERATED ALWAYS AS ( IFNULL(JSON_UNQUOTE(JSON_EXTRACT(data, '$.indek.t')),'')) VIRTUAL,
													viu 					VARCHAR(250)						GENERATED ALWAYS AS ( IFNULL(JSON_UNQUOTE(JSON_EXTRACT(data, '$.indek.u')),'')) VIRTUAL,
													viv 					VARCHAR(250)						GENERATED ALWAYS AS ( IFNULL(JSON_UNQUOTE(JSON_EXTRACT(data, '$.indek.v')),'')) VIRTUAL,
													viw 					VARCHAR(250)						GENERATED ALWAYS AS ( IFNULL(JSON_UNQUOTE(JSON_EXTRACT(data, '$.indek.w')),'')) VIRTUAL,
													vix 					VARCHAR(250)						GENERATED ALWAYS AS ( IFNULL(JSON_UNQUOTE(JSON_EXTRACT(data, '$.indek.x')),'')) VIRTUAL,
													viy 					VARCHAR(250)						GENERATED ALWAYS AS ( IFNULL(JSON_UNQUOTE(JSON_EXTRACT(data, '$.indek.y')),'')) VIRTUAL,
													viz 					VARCHAR(250)						GENERATED ALWAYS AS ( IFNULL(JSON_UNQUOTE(JSON_EXTRACT(data, '$.indek.z')),'')) VIRTUAL,
													PRIMARY KEY		(
																				#id,
																				partisi,
																				subpartisi
																				),
													#INDEX 				(id),
													INDEX 				(partisi),
													INDEX 				(subpartisi),
													INDEX 				(status),
													INDEX 				(cari),
													INDEX 				(via),
													INDEX 				(vib),
													INDEX 				(vic),
													INDEX 				(vid),
													INDEX 				(vie),
													INDEX 				(vif),
													INDEX 				(vig),
													INDEX 				(vih),
													INDEX 				(vii),
													INDEX 				(vij),
													INDEX 				(vik),
													INDEX 				(vil),
													INDEX 				(vim),
													INDEX 				(vin),
													INDEX 				(vio),
													INDEX 				(vip),
													INDEX 				(viq),
													INDEX 				(vir),
													INDEX 				(vis),
													INDEX 				(vit),
													INDEX 				(viu),
													INDEX 				(viv),
													INDEX 				(viw),
													INDEX 				(vix),
													INDEX 				(viy),
													INDEX 				(viz)
													)
													PARTITION BY 	LIST 														COLUMNS (partisi)
														(
														PARTITION 	x 															VALUES IN (''),
														PARTITION 	tugas														VALUES IN ('tugas'),
														PARTITION 	intope_riwayat_sep							VALUES IN ('intope_riwayat_sep'),
														PARTITION 	intope_riwayat_klaim						VALUES IN ('intope_riwayat_klaim')
														)
				;
				
				select @GxPesan;
		
		
		
		WHEN 									'partisi+' THEN#{"tx":"partisi+"} 
			ALTER TABLE rsb221022021.zzzdata ADD PARTITION (PARTITION keu_jasadokter_gagal VALUES IN ('keu_jasadokter_gagal'));
			
		WHEN 									'teksketabel' THEN
			SET 								vTeks 	= JSON_UNQUOTE(JSON_EXTRACT(p,'$.teks')),
													vJumlah = LENGTH(vTeks)-LENGTH(REPLACE(vTeks,' ','')) + 1
			;
#select vTeks,vJumlah;
			DROP
				TEMPORARY
				TABLE
				IF EXISTS 				TMP1,TMPTekTab
			;
			CREATE
				TEMPORARY
				TABLE							TMP1(xKATA VARCHAR(250))
			;
			
#select SUBSTRING_INDEX(SUBSTRING_INDEX(vTeks,' ',2),' ',-1) aaaa;
	#select * from TMP1;
			WHILE 							vHitung < vJumlah DO
				SET								vHitung=vHitung+1;
				INSERT INTO				TMP1 VALUES(SUBSTRING_INDEX(SUBSTRING_INDEX(vTeks,' ',vHitung),' ',-1));
			END WHILE
			;
			SET 								@xNomor=0;
			CREATE
				TEMPORARY
				TABLE							TMPTekTab
				SELECT						xKATA A,
													IF(ANGKA 		IS NOT NULL,	'ANGKA',
														IF(DESIMAL	IS NOT NULL,	'DESIMAL',
															IF(JAM 			IS NOT NULL,	'JAM',
																IF(TANGGAL 	IS NOT NULL,	'TANGGAL',
																	IF(BULAN 		IS NOT NULL,	'BULAN',
																		IF(HARI			IS NOT NULL,	'HARI',
																			IF(SAAT			IS NOT NULL,	'SAAT',
																				IF(NORAWAT	IS NOT NULL,	'NORAWAT',
																					IF(NORM			IS NOT NULL,	'NORM',
																						IF(NOSEP		IS NOT NULL,	'NOSEP',
																							'TEKS'
																							)
																						)
																					)
																				)
																			)
																		)
																	)
																)
															)
														)	B,
													IF(ANGKA 		IS NOT NULL,	ANGKA,
														IF(DESIMAL	IS NOT NULL,	DESIMAL,
															IF(JAM 			IS NOT NULL,	JAM,
																IF(TANGGAL 	IS NOT NULL,	TANGGAL,
																	IF(BULAN 		IS NOT NULL,	BULAN,
																		IF(HARI			IS NOT NULL,	HARI,
																			IF(SAAT			IS NOT NULL,	SAAT,
																				IF(NORAWAT	IS NOT NULL,	NORAWAT,
																					IF(NORM			IS NOT NULL,	NORM,
																						IF(NOSEP			IS NOT NULL,	NOSEP,
																							xKATA
																							)
																						)
																					)
																				)
																			)
																		)
																	)
																)
															)
														)	C,
													@xNomor:=@xNomor + 1 NO
					FROM
					(
					SELECT					xKATA,
													@x:=f_KriteriaANGKA		(xKATA)	ANGKA,
													@x:=f_KriteriaDESIMAL	(xKATA)	DESIMAL,
													@x:=f_KriteriaJAM			(xKATA)	JAM,
													@x:=f_KriteriaTANGGAL	(xKATA)	TANGGAL,
													@x:=f_KriteriaBULAN		(xKATA)	BULAN,
													@x:=f_KriteriaHARI		(xKATA)	HARI,
													@x:=f_KriteriaSAAT		(xKATA)	SAAT,
													@x:=f_KriteriaNORAWAT	(xKATA)	NORAWAT,
													@x:=f_KriteriaNORM		(xKATA)	NORM,
													@x:=f_KriteriaNOSEP		(xKATA)	NOSEP,
													xKATA													TEKS
						FROM 					TMP1
						WHERE 				xKATA <> ''
					) 							aT1
			;
#select @GxPesan;
			DROP
				TEMPORARY
				TABLE
				IF EXISTS 				TMP1
			;
		#select @Gxpesan aaa;
		
	END CASE
	;
	
	
	
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for pxUbahTarif
-- ----------------------------
DROP PROCEDURE IF EXISTS `pxUbahTarif`;
delimiter ;;
CREATE PROCEDURE `pxUbahTarif`(IN arNORAWAT VARCHAR(250))
px:BEGIN
	DECLARE									pNRwt VARCHAR(250) DEFAULT arNORAWAT;
	DECLARE
		CONTINUE
		HANDLER 
		FOR
		SQLEXCEPTION
	BEGIN
		GET
			DIAGNOSTICS
			CONDITION			1			@GGl		=	MESSAGE_TEXT,
													@GGNo		=	MYSQL_ERRNO,
													@GGSt 	= RETURNED_SQLSTATE
		;
	END
	;
	
	SET											@GGl		=	'',
													@GGNo		=	0,
													@GGSt 	= 0
	;
	
	select * from json_table('[1,2,3]', '$[*]' columns (a int path '$')) as a;
	
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for pxUbah_KelasTarif
-- ----------------------------
DROP PROCEDURE IF EXISTS `pxUbah_KelasTarif`;
delimiter ;;
CREATE PROCEDURE `pxUbah_KelasTarif`(IN argNORAWAT VARCHAR(250),IN argDARI VARCHAR(250), IN argJADI VARCHAR(250))
px:BEGIN
	
	declare 										pAsuransi varchar(250) default ifnull((select kd_pj from rsb221022021.reg_periksa where no_rawat  = argNORAWAT),'');
	
	DECLARE
		CONTINUE
		HANDLER 
		FOR
		SQLEXCEPTION
	BEGIN
		GET
			DIAGNOSTICS
			CONDITION			1	@GxPesan		=	MESSAGE_TEXT,
										@GxNomor		=	MYSQL_ERRNO,
										@GxStatus 		= 	RETURNED_SQLSTATE
		;
	END
	;
	
	SET								@GxPesan		=	'',
										@GxNomor		=	0,
										@GxStatus 		= 	0
	;
	
	/*
	if pAsuransi not like 'umu' then
		leave px;
	end if
	;
	*/
	
	#/* rawat_inap_dr
	
	update  							rsb221022021.rawat_inap_dr					dari
	inner join 						rsb221022021.jns_perawatan_inap				ind
		on 							dari.no_rawat=argNORAWAT
		and 							ind.kd_jenis_prw=dari.kd_jenis_prw
	inner join 						rsb221022021.jns_perawatan_inap				jadi
		on 							jadi.nm_perawatan=ind.nm_perawatan
		and 							jadi.kd_pj='-'
		and 							jadi.kelas=argJADI
	set 								dari.material=jadi.material,
										dari.tarif_tindakandr=jadi.tarif_tindakandr,
										dari.biaya_rawat=jadi.total_byrdrpr
	;
	
	
	#*/
	
	
	#/* periksa_lab
	
		update									rsb221022021.periksa_lab								dari
		inner join 								rsb221022021.jns_perawatan_lab						ind
			on 									dari.no_rawat=argNORAWAT
			and 									ind.kd_jenis_prw=dari.kd_jenis_prw
		inner join 								rsb221022021.jns_perawatan_lab						jadi
			on 									jadi.nm_perawatan=ind.nm_perawatan
			and 									jadi.kd_pj='-'
			and 									jadi.kelas=argJADI
		
		
		set 										dari.bagian_rs=jadi.bagian_rs,
													dari.bhp=jadi.bhp,
													dari.tarif_tindakan_dokter=jadi.tarif_tindakan_dokter,
													dari.biaya=jadi.total_byr
		WHERE									dari.status='Ranap'
	;
	#*/
	
	
	#/* periksa_radiologi
	
		update 									rsb221022021.periksa_radiologi						dari
		inner join 								rsb221022021.jns_perawatan_radiologi				ind
			on 									dari.no_rawat=argNORAWAT
			and 									ind.kd_jenis_prw=dari.kd_jenis_prw
		inner join 								rsb221022021.jns_perawatan_radiologi				jadi
			on 									jadi.nm_perawatan=ind.nm_perawatan
			and 									jadi.kd_pj='-'
			and 									jadi.kelas=argJADI
		
	
		set 				dari.bagian_rs=jadi.bagian_rs,
								dari.bhp=jadi.bhp,
								dari.tarif_tindakan_dokter=jadi.tarif_tindakan_dokter,
								dari.biaya=jadi.total_byr
	  WHERE				dari.status='Ranap'
	;
	
	#*/
	
	
	
	
	/*
	select				dari.*,
								ind.nm_perawatan,
								ind.kelas,
								ind.kode_paket,
								jadi.*
		
		from				
	*/
	
		update 			rsb221022021.operasi												dari
		inner join 		rsb221022021.paket_operasi									ind
			on 			dari.no_rawat=argNORAWAT
			and 			ind.kode_paket=dari.kode_paket
		inner join 		rsb221022021.paket_operasi									jadi
			on 			jadi.nm_perawatan=ind.nm_perawatan
			and 			jadi.kd_pj='-'
			and 			jadi.kelas=argJADI
		
		
		set 					dari.biayaoperator1=jadi.operator1,
								dari.biayaoperator2=jadi.operator2,
								dari.biayaoperator3=jadi.operator3,
								dari.biayaasisten_operator1=jadi.asisten_operator1,
								dari.biayaasisten_operator2=jadi.asisten_operator2,
								dari.biayaasisten_operator3=jadi.asisten_operator3,
								dari.biayainstrumen=jadi.instrumen,
								dari.biayadokter_anak=jadi.dokter_anak,
								dari.biayadokter_anestesi=jadi.dokter_anestesi,
								dari.biayaasisten_anestesi=jadi.asisten_anestesi,
								dari.biayaasisten_anestesi2=jadi.asisten_anestesi2,
								dari.biayabidan=jadi.bidan,
								dari.biayabidan2=jadi.bidan2,
								dari.biayabidan3=jadi.bidan3,
								dari.biayaalat=jadi.alat,
								dari.biayasewaok=jadi.sewa_ok,
								dari.bagian_rs=jadi.bagian_rs,
								dari.biaya_omloop=jadi.omloop,
								dari.biaya_omloop2=jadi.omloop2,
								dari.biaya_omloop3=jadi.omloop3,
								dari.biaya_omloop4=jadi.omloop4,
								dari.biaya_omloop5=jadi.omloop5
								
	;
	
	select				dari.*,
								ind.nm_perawatan,
								ind.kelas,
								ind.kode_paket,
								jadi.*
		from				
		/*update*/	rsb221022021.operasi												dari
		inner join 	rsb221022021.paket_operasi									ind
			on 				dari.no_rawat=argNORAWAT
			and 			ind.kode_paket=dari.kode_paket
		inner join 	rsb221022021.paket_operasi									jadi
			on 				jadi.nm_perawatan=ind.nm_perawatan
			and 			jadi.kd_pj='-'
			and 			jadi.kelas=argJADI
		/*
		set dari.? = jadi.? 
		*/
	;
	
	
	
	
	select @GxPesan;
	
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for pxUbah_Norawat
-- ----------------------------
DROP PROCEDURE IF EXISTS `pxUbah_Norawat`;
delimiter ;;
CREATE PROCEDURE `pxUbah_Norawat`(IN arNORAWATA VARCHAR(250),IN arNORAWATB VARCHAR(250))
px:BEGIN
	DECLARE									pNoA VARCHAR(250) DEFAULT arNORAWATA;
	DECLARE									pNoB VARCHAR(250) DEFAULT arNORAWATB;
	DECLARE
		CONTINUE
		HANDLER 
		FOR
		SQLEXCEPTION
	BEGIN
		GET
			DIAGNOSTICS
			CONDITION			1						@GGl		=	MESSAGE_TEXT,
															@GGNo		=	MYSQL_ERRNO,
															@GGSt 	= RETURNED_SQLSTATE
		;
	END
	;
	
	SET													@GGl		=	'',
															@GGNo		=	0,
															@GGSt 	= 0
	;
	
	update	rsb221022021.rawat_jl_dr				set no_rawat = pNoB where no_rawat = pNoA;
	update	rsb221022021.rawat_jl_drpr			set no_rawat = pNoB where no_rawat = pNoA;
	update	rsb221022021.rawat_jl_pr				set no_rawat = pNoB where no_rawat = pNoA;
	update	rsb221022021.rawat_inap_dr			set no_rawat = pNoB where no_rawat = pNoA;
	update	rsb221022021.rawat_inap_drpr		set no_rawat = pNoB where no_rawat = pNoA;
	update	rsb221022021.rawat_inap_pr			set no_rawat = pNoB where no_rawat = pNoA;
	update	rsb221022021.periksa_lab				set no_rawat = pNoB where no_rawat = pNoA;
	update	rsb221022021.periksa_radiologi		set no_rawat = pNoB where no_rawat = pNoA;
	update	rsb221022021.operasi					set no_rawat = pNoB where no_rawat = pNoA;
	
	select @GGl;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for pz_Tugas_Data
-- ----------------------------
DROP PROCEDURE IF EXISTS `pz_Tugas_Data`;
delimiter ;;
CREATE PROCEDURE `pz_Tugas_Data`(IN argTUGAS VARCHAR(250))
px:BEGIN
	declare 					xJS1,
										xJS2,
										xJS3,
										xJS4,
										xJS5 			json;
	declare 					xI1,
										xI2  			integer default 0;
	
	declare 					xDt1,
										xDt2,
										xDt3			date default '0000-00-00';
	declare 					xVC1
															varchar(250) default '';
	
	DECLARE
		CONTINUE
		HANDLER 
		FOR
		SQLEXCEPTION
	BEGIN
		GET
			DIAGNOSTICS
			CONDITION			1			@GxPesan		=	MESSAGE_TEXT,
													@GxNomor		=	MYSQL_ERRNO,
													@GxStatus 	= RETURNED_SQLSTATE
		;
	END
	;
	
	SET											@GxPesan			=	'',
													@GxNomor			=	0,
													@GxStatus 		= 0
	;
	
	case argTUGAS
		
		when 'edit intope sep indek' then
			update rsb221022021.zzzdata_jkn
				partition (intope_sep)
				#use index(vinta)
				set 			data  = json_set(data,
													'$.indek.int',	json_object('a',cast(json_unquote(json_extract(data,'$.jnsPelayanan')) as UNSIGNED))/*,
													'$.indek.chr.b',	json_unquote(json_extract(data,'$.norm')),
													'$.indek.chr.c',	json_unquote(json_extract(data,'$.noKartu')),
													'$.indek.chr.d',	json_unquote(json_extract(data,'$.ppkPelayanan'))*/
													)
					where 	vinta = 0
			;
		when 'edit intope sep norawat' then
				SET group_concat_max_len=1073741824;
				set xJS1 = 	(
										select 		json_arrayagg(jag) from (
										select 		json_object(
															'nojkn',				ifnull(pas.no_peserta,''),
															'norawat',			ifnull(reg.no_rawat,''),
															'rjri',					ifnull(reg.status_lanjut,''),
															'tglreg',				ifnull(reg.tgl_registrasi,'0000-00-00'),
															'tglrj',				ifnull(min(rj.tgl_perawatan),'0000-00-00'),
															'tglri',				ifnull(min(inap.tgl_masuk),'0000-00-00')
															) 							jag
											from				rsb221022021.reg_periksa 	reg
											left join   rsb221022021.pasien 			pas
												on 				pas.no_rkm_medis=reg.no_rkm_medis
											left join 	rsb221022021.kamar_inap inap
												on 				inap.no_rawat=reg.no_rawat
											left join 	rsb221022021.rawat_jl_dr 				rj
												on 				rj.no_rawat=reg.no_rawat
											where 			reg.tgl_registrasi >='2024-01-01'
												and 			reg.kd_pj = 'bpj'
												and 			reg.stts not in ('batal')
												and 			pas.no_peserta not in ('','-')
											group by 		reg.no_rawat
											) aT1
										)
				;
		when 'rapel intope sep' then
			insert into rsb221022021.zzzdata_tugas
				partition (tx)
									(
									#partisi,
									subpartisi,
									parameter
									)
				select		
									#'tx',
									'rsb221022021_jkn.pxIntOpe',#	tx		{"tx": "intope_jkn_sep", "norawat": "2024/01/02/000105"}
									json_object('grup','spf','tx','intope_jkn_sep','norawat',no_rawat)
					from 		rsb221022021.reg_periksa
					where 	tgl_registrasi >= '2024-12-17'
						and 	kd_pj = 'bpj'
						and 	stts not in ('batal')
#limit 10
#and no_rawat = '2024/12/15/000036'
					#limit 5
			;
		when 'rapel intope klaim' then
				set xDt1 = '2024-01-01',
						xDt2 = date(now())
				;
				set xJS1 = json_array(xDt1);
				while xDt1 < xDt2 do
					set xDt1 = DATE_ADD(xDt1,interval 1 day),
							xJS1 = JSON_ARRAY_APPEND(xJS1, '$', xDt1)
					;
				end while
				;

				set xI1 = json_length(xJS1);
				
				while xI2 < xI1 do
					set xVC1 = cast(json_unquote(json_extract(xJS1,concat('$[',xI2,']'))) as char);
					insert into rsb221022021.zzzdata_tugas
						partition (tx)
											(
											partisi,
											subpartisi,
											parameter
											)
						values 		(
											'tx',
											'rsb221022021_jkn.pxIntOpe',#	tx{"tx": "intope_jkn_sep", "norawat": "2024/01/02/000105"}
											json_object('grup','spf','tx','intope_jkn_klaim','param',concat(xVC1,'/1/1'))
											),
											(
											'tx',
											'rsb221022021_jkn.pxIntOpe',#	tx{"tx": "intope_jkn_sep", "norawat": "2024/01/02/000105"}
											json_object('grup','spf','tx','intope_jkn_klaim','param',concat(xVC1,'/1/2'))
											),
											(
											'tx',
											'rsb221022021_jkn.pxIntOpe',#	tx{"tx": "intope_jkn_sep", "norawat": "2024/01/02/000105"}
											json_object('grup','spf','tx','intope_jkn_klaim','param',concat(xVC1,'/1/3'))
											),
											(
											'tx',
											'rsb221022021_jkn.pxIntOpe',#	tx{"tx": "intope_jkn_sep", "norawat": "2024/01/02/000105"}
											json_object('grup','spf','tx','intope_jkn_klaim','param',concat(xVC1,'/2/1'))
											),
											(
											'tx',
											'rsb221022021_jkn.pxIntOpe',#	tx{"tx": "intope_jkn_sep", "norawat": "2024/01/02/000105"}
											json_object('grup','spf','tx','intope_jkn_klaim','param',concat(xVC1,'/2/2'))
											),
											(
											'tx',
											'rsb221022021_jkn.pxIntOpe',#	tx{"tx": "intope_jkn_sep", "norawat": "2024/01/02/000105"}
											json_object('grup','spf','tx','intope_jkn_klaim','param',concat(xVC1,'/2/3'))
											)
					;
					set xI2 = xI2 + 1;
				end while
				;

			select @GxPesan;	
				
				
				
				
	end case
	;
	
	
	
	
	
	
	
	
	
	
	
	
	
	
	
	
	
	
	
	
	
	
	
	
	
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for pz_Tugas_Tabel
-- ----------------------------
DROP PROCEDURE IF EXISTS `pz_Tugas_Tabel`;
delimiter ;;
CREATE PROCEDURE `pz_Tugas_Tabel`(IN argTUGAS VARCHAR(250))
px:BEGIN
	declare 					xJS1,
										xJS2,
										xJS3,
										xJS4,
										xJS5 			json;
	declare 					xI1,
										xI2  			integer default 0;
	
	declare 					xDt1,
										xDt2,
										xDt3			date default '0000-00-00';
	declare 					xVC1
															varchar(250) default '';
	
	DECLARE
		CONTINUE
		HANDLER 
		FOR
		SQLEXCEPTION
	BEGIN
		GET
			DIAGNOSTICS
			CONDITION			1			@GxPesan		=	MESSAGE_TEXT,
													@GxNomor		=	MYSQL_ERRNO,
													@GxStatus 	= RETURNED_SQLSTATE
		;
	END
	;
	
	SET											@GxPesan			=	'',
													@GxNomor			=	0,
													@GxStatus 		= 0
	;
	
	case argTUGAS
		
		when 'lihat trigger' then
			show triggers;
		
				
	end case
	;
	
	
	
	
	
	
	
	
	
	
	
	
	
	
	
	
	
	
	
	
	
	
	
	
	
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for show_perubahan_PENUNJANG_UMUM_BJK
-- ----------------------------
DROP PROCEDURE IF EXISTS `show_perubahan_PENUNJANG_UMUM_BJK`;
delimiter ;;
CREATE PROCEDURE `show_perubahan_PENUNJANG_UMUM_BJK`(norawat VARCHAR(20))
BEGIN
	
	# perbandingan tarif ranap umum dan BJK
	# TABEL periksa_lab
	select jpawal.kd_jenis_prw kdawal, jptuj.kd_jenis_prw kdtuj, jptuj.nm_perawatan,periksa_lab.biaya, jptuj.total_byr
	from periksa_lab 
			inner join jns_perawatan_lab jpawal on periksa_lab.kd_jenis_prw = jpawal.kd_jenis_prw
			LEFT join jns_perawatan_lab jptuj on jptuj.kd_jenis_prw = CONCAT("BJK",jpawal.kd_jenis_prw)
	where periksa_lab.no_rawat = norawat;
	
	# perbandingan tarif ranap umum dan BJK
	# TABEL detail_periksa_lab
	select jpawal.kd_jenis_prw kdawal, jptuj.kd_jenis_prw kdtuj, jptuj.Pemeriksaan,detail_periksa_lab.biaya_item, jptuj.biaya_item
	from detail_periksa_lab 
			inner join template_laboratorium jpawal on detail_periksa_lab.kd_jenis_prw = jpawal.kd_jenis_prw and detail_periksa_lab.id_template= jpawal.id_template
			LEFT join template_laboratorium jptuj on jptuj.kd_jenis_prw = CONCAT("BJK",jpawal.kd_jenis_prw) and jptuj.Pemeriksaan = jpawal.Pemeriksaan
	where detail_periksa_lab.no_rawat = norawat AND detail_periksa_lab.biaya_item <> 0;
	

	# perbandingan tarif ranap umum dan BJK
	# TABEL periksa_radiologi
	select jpawal.kd_jenis_prw kdawal, jptuj.kd_jenis_prw kdtuj, jptuj.nm_perawatan,periksa_radiologi.biaya, jptuj.total_byr
	from periksa_radiologi 
			inner join jns_perawatan_radiologi jpawal on periksa_radiologi.kd_jenis_prw = jpawal.kd_jenis_prw
			LEFT join jns_perawatan_radiologi jptuj on jptuj.kd_jenis_prw = CONCAT("BJK",jpawal.kd_jenis_prw)
	where periksa_radiologi.no_rawat = norawat; #AND jptuj.kd_pj like 'BJK';

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for show_perubahan_RANAP_UMUM_BJK
-- ----------------------------
DROP PROCEDURE IF EXISTS `show_perubahan_RANAP_UMUM_BJK`;
delimiter ;;
CREATE PROCEDURE `show_perubahan_RANAP_UMUM_BJK`(norawat VARCHAR(20))
BEGIN
	
	# perbandingan tarif ranap umum dan BJK
	# TABEL rawat_inap_dr
	select jpawal.kd_jenis_prw kdawal, jptuj.kd_jenis_prw kdtuj, jptuj.nm_perawatan,rawat_inap_dr.biaya_rawat, jptuj.total_byrdr
	from rawat_inap_dr 
			inner join jns_perawatan_inap jpawal on rawat_inap_dr.kd_jenis_prw = jpawal.kd_jenis_prw
			LEFT join jns_perawatan_inap jptuj on jptuj.kd_jenis_prw = CONCAT("BJK",jpawal.kd_jenis_prw)
	where rawat_inap_dr.no_rawat = '2024/09/20/000251'; #AND jptuj.kd_pj like 'BJK';
	
	# perbandingan tarif ranap umum dan BJK
	# TABEL rawat_inap_pr
	select jpawal.kd_jenis_prw kdawal, jptuj.kd_jenis_prw kdtuj, jptuj.nm_perawatan,rawat_inap_pr.biaya_rawat, jptuj.total_byrpr
	from rawat_inap_pr 
			inner join jns_perawatan_inap jpawal on rawat_inap_pr.kd_jenis_prw = jpawal.kd_jenis_prw
			LEFT join jns_perawatan_inap jptuj on jptuj.kd_jenis_prw = CONCAT("BJK",jpawal.kd_jenis_prw)
	where rawat_inap_pr.no_rawat = '2024/09/20/000251'; #AND jptuj.kd_pj like 'BJK';
	
	
	# perbandingan tarif ranap umum dan BJK
	# TABEL rawat_inap_drpr
	select jpawal.kd_jenis_prw kdawal, jptuj.kd_jenis_prw kdtuj, jptuj.nm_perawatan,rawat_inap_drpr.biaya_rawat, jptuj.total_byrdrpr
	from rawat_inap_drpr 
			inner join jns_perawatan_inap jpawal on rawat_inap_drpr.kd_jenis_prw = jpawal.kd_jenis_prw
			LEFT join jns_perawatan_inap jptuj on jptuj.kd_jenis_prw = CONCAT("BJK",jpawal.kd_jenis_prw)
	where rawat_inap_drpr.no_rawat = '2024/09/20/000251'; #AND jptuj.kd_pj like 'BJK';

END
;;
delimiter ;

