-- ----------------------------
-- Procedure structure for SPIndukPasien
-- ----------------------------
DROP PROCEDURE IF EXISTS `SPIndukPasien`;
delimiter ;;
CREATE PROCEDURE `SPIndukPasien`(IN PARAM TEXT)
BEGIN
	declare p text default concat('%',replace(PARAM,' ','%'),'%');
	select	* from pasien where concat(alamat,nm_pasien,tgl_lahir,no_rkm_medis,tgl_lahir,nm_pasien,alamat) like p;
END
;;
delimiter ;

-- ----------------------------
-- Function structure for SPLIT_COUNT
-- ----------------------------
DROP FUNCTION IF EXISTS `SPLIT_COUNT`;
delimiter ;;
CREATE FUNCTION `SPLIT_COUNT`(str TEXT, delim VARCHAR(16))
 RETURNS int(11)
  DETERMINISTIC
BEGIN
  IF str IS NULL OR str = '' THEN
    RETURN 0;
  END IF;
  RETURN (CHAR_LENGTH(str) - CHAR_LENGTH(REPLACE(str, delim, '')))
         / CHAR_LENGTH(delim) + 1;
END
;;
delimiter ;

-- ----------------------------
-- Function structure for SPLIT_STR
-- ----------------------------
DROP FUNCTION IF EXISTS `SPLIT_STR`;
delimiter ;;
CREATE FUNCTION `SPLIT_STR`(str TEXT, delim VARCHAR(16), pos INT)
 RETURNS text CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci
  DETERMINISTIC
BEGIN
  IF pos < 1 OR pos > SPLIT_COUNT(str, delim) THEN
    RETURN NULL;
  END IF;
  RETURN SUBSTRING_INDEX(SUBSTRING_INDEX(str, delim, pos), delim, -1);
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for sp_keu_tarif_kamar_inap
-- ----------------------------
DROP PROCEDURE IF EXISTS `sp_keu_tarif_kamar_inap`;
delimiter ;;
CREATE PROCEDURE `sp_keu_tarif_kamar_inap`()
begin 
  WITH RECURSIVE seq AS (
    SELECT 1 AS n
    UNION ALL
    SELECT n + 1 FROM seq
    WHERE n < (SELECT MAX(SPLIT_COUNT(kd_kamar, ' ')) FROM kamar)
  )
  , list_kamar as (
      SELECT 
        p.kelas,
        SPLIT_STR(p.kd_kamar, ' ', s.n)  AS keterangan,
        p.trf_kamar as tarif
    FROM kamar p
    JOIN seq s ON s.n <= SPLIT_COUNT(p.kd_kamar, ' ')
    where statusdata = "1"
    and kelas != "Kelas Utama"
    ORDER BY p.kelas, s.n
  )
  select  
    kelas, 
    tarif ,
    group_concat(distinct keterangan separator ", ") as keterangan
  from list_kamar 
  where keterangan COLLATE utf8mb4_general_ci in (
    "Alamanda",
    "Aster",
    "Amarylis",
    "Bougenville",
    "Anggrek",
    "Anyelir",
    "Begonia",
    "Bergenia",
    "Bouvardia"
  ) group by kelas, tarif order by kelas desc
  ;
end
;;
delimiter ;

-- ----------------------------
-- Procedure structure for sp_keu_tarif_kamar_khusus
-- ----------------------------
DROP PROCEDURE IF EXISTS `sp_keu_tarif_kamar_khusus`;
delimiter ;;
CREATE PROCEDURE `sp_keu_tarif_kamar_khusus`()
begin 
  WITH RECURSIVE seq AS (
    SELECT 1 AS n
    UNION ALL
    SELECT n + 1 FROM seq
    WHERE n < (SELECT MAX(SPLIT_COUNT(kd_kamar, ' ')) FROM kamar)
  )
  , list_kamar as (
      SELECT 
        p.kd_bangsal,
        SPLIT_STR(p.kd_kamar, ' ', s.n)  AS keterangan,
        p.trf_kamar as tarif
    FROM kamar p
    JOIN seq s ON s.n <= SPLIT_COUNT(p.kd_kamar, ' ')
    where statusdata = "1"
    and kelas = "Kelas Utama"
    ORDER BY p.kelas, s.n
  )
  select  
    case 
      when kd_bangsal = "PRINA" then "Ruang Perina"
      when kd_bangsal = "ISO" then "Ruang Isolasi"
    else kd_bangsal end as kd_bangsal,
    tarif
  from list_kamar group by case 
      when kd_bangsal = "PRINA" then "Ruang Perina"
      when kd_bangsal = "ISO" then "Ruang Isolasi"
    else kd_bangsal end, tarif order by case 
      when kd_bangsal = "PRINA" then "Ruang Perina"
      when kd_bangsal = "ISO" then "Ruang Isolasi"
    else kd_bangsal end desc
  ;
end
;;
delimiter ;

-- ----------------------------
-- Procedure structure for sp_keu_tarif_laboratorium
-- ----------------------------
DROP PROCEDURE IF EXISTS `sp_keu_tarif_laboratorium`;
delimiter ;;
CREATE PROCEDURE `sp_keu_tarif_laboratorium`()
bEGIN
  with lab as (
    SELECT concat(grup, lvl, urut) as grp, name, kategori, kelas, tariff
    FROM (
        SELECT  p.kd_jenis_prw AS grup
                , 0 AS lvl, 0 AS urut
                , p.nm_perawatan AS name
                , p.kategori
                , 'Paket Pemeriksaan' AS category
                , p.total_byr AS tariff
                , p.kelas
        FROM jns_perawatan_lab p
        WHERE p.status = '1' and p.kd_pj = "-" and p.kelas

        UNION ALL

        SELECT c.kd_jenis_prw, 1, c.urut,
               concat("  ",c.Pemeriksaan), p.kategori, 'Item Pemeriksaan', c.biaya_item, p.kelas
        FROM template_laboratorium c
        JOIN jns_perawatan_lab p 
        ON p.kd_jenis_prw = c.kd_jenis_prw
        WHERE p.status = '1' and p.kd_pj = "-" and p.kelas
    ) x
    ORDER BY grup, lvl, urut, name
  )

  select 
      name
      , sum(case when kelas = "Kelas 3" then tariff else 0 end) as kelas_3
      , sum(case when kelas = "Kelas 2" then tariff else 0 end) as kelas_2
      , sum(case when kelas = "Kelas 1" then tariff else 0 end) as kelas_1
      , sum(case when kelas = "Kelas VIP" then tariff else 0 end) as kelas_vip
      , sum(case when kelas = "Kelas VVIP" then tariff else 0 end) as kelas_vvip
      , sum(case when kelas = "Kelas Utama" then tariff else 0 end) as kamar_khusus
      , sum(case when kelas = "Rawat Jalan" then tariff else 0 end) as rawat_jalan
  from lab
  group by name
  order by grp;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for sp_keu_tarif_operasi_bedah
-- ----------------------------
DROP PROCEDURE IF EXISTS `sp_keu_tarif_operasi_bedah`;
delimiter ;;
CREATE PROCEDURE `sp_keu_tarif_operasi_bedah`(IN regex VARCHAR(200), IN not_regex VARCHAR(200)
    , p_name_split BOOLEAN -- 1 split hanya untuk nama jenis operasi nya (Besar, Kecil, Sedang) mengikuti yang ada pada kolom nm_perawatan, 0 menampilkan apa adanya
    , p_show_partial BOOLEAN -- 1 tidak menampilkan sewa_ok + alat, 0 menampilkan semuanya
    , p_show_inap BOOLEAN
    , p_show_khusus BOOLEAN
    , p_show_jalan BOOLEAN)
begin

  IF p_show_partial THEN
    SET @sql = '
      with filter_operasi as (
        select 
          kode_paket
          ,';
          
     IF p_name_split THEN 
      set @sql = concat(@sql, 'SPLIT_STR(nm_perawatan, " - ", 2) as tipe_operasi');
     ELSE
      set @sql = concat(@sql, 'nm_perawatan');
     END IF;
     
     SET @sql = concat(@sql,'
          , kelas
              , sewa_ok + alat as bagian_rs
              , operator1 + operator2 + operator3 
                + dokter_pjanak + dokter_anak + dokter_anestesi 
                + dokter_umum
                + asisten_operator1 + asisten_operator2 + asisten_operator3 
                + asisten_anestesi + asisten_anestesi2 
                + instrumen + perawaat_resusitas 
                + bidan + bidan2 + bidan3 
                + perawat_luar 
                + akomodasi + bagian_rs + sarpras
                + omloop + omloop2 + omloop3 + omloop4 + omloop5 as tarif
            from paket_operasi  where kd_pj = "-" 
            and nm_perawatan regexp ?
            and nm_perawatan not regexp ?
          )');
          
    IF p_name_split THEN 
      set @sql = concat(@sql, 'select SPLIT_STR(tipe_operasi, " ", 2) as tipe_operasi');
    ELSE 
      set @sql = concat(@sql, 'select nm_perawatan');
    END IF;
    
  ELSE 
  
    SET @sql = '
      with filter_operasi as (
        select 
          kode_paket
          ,';
          
     IF p_name_split THEN 
      set @sql = concat(@sql, 'SPLIT_STR(nm_perawatan, " - ", 2) as tipe_operasi');
     ELSE
      set @sql = concat(@sql, 'nm_perawatan');
     END IF;
     
     SET @sql = concat(@sql,'
          , kelas
          , sewa_ok + alat as bagian_rs
          , operator1 + operator2 + operator3 
            + dokter_pjanak + dokter_anak + dokter_anestesi 
            + dokter_umum 
            + asisten_operator1 + asisten_operator2 + asisten_operator3 
            + asisten_anestesi + asisten_anestesi2 
            + instrumen + perawaat_resusitas 
            + bidan + bidan2 + bidan3 
            + perawat_luar 
            + sewa_ok + alat + akomodasi + bagian_rs + sarpras
            + omloop + omloop2 + omloop3 + omloop4 + omloop5
          as tarif
        from paket_operasi  where kd_pj = "-" 
        and nm_perawatan regexp ?
        and nm_perawatan not regexp ?)');
        
      IF p_name_split THEN 
        set @sql = concat(@sql, 'select SPLIT_STR(tipe_operasi, " ", 2) as tipe_operasi');
      ELSE 
        set @sql = concat(@sql, 'select nm_perawatan');
      END IF;
  END IF;
  
  IF p_show_inap THEN
    SET @sql = CONCAT(@sql, '
    , sum(case when kelas = "Kelas 3" then tarif else 0 end) as kelas_3
    , sum(case when kelas = "Kelas 2" then tarif else 0 end) as kelas_2
    , sum(case when kelas = "Kelas 1" then tarif else 0 end) as kelas_1
    , sum(case when kelas = "Kelas VIP" then tarif else 0 end) as kelas_vip
    , sum(case when kelas = "Kelas VVIP" then tarif else 0 end) as kelas_vvip');
  END IF;
  
  IF p_show_khusus THEN
    SET @sql = CONCAT(@sql, ', sum(case when kelas = "ICU" then tarif else 0 end) as kamar_khusus');
  END IF;
  
  IF p_show_jalan THEN
    SET @sql = CONCAT(@sql, ', sum(case when kelas = "Rawat Jalan" then tarif else 0 end) as rawat_jalan');
  END IF;    
  
  IF p_name_split THEN
  
    SET @sql = CONCAT(
      @sql,
      '
        from filter_operasi
        group by SPLIT_STR(tipe_operasi, " ", 2)
        order by SPLIT_STR(tipe_operasi, " ", 2)
      '
    );
  ELSE 
    SET @sql = CONCAT(
      @sql,
      '
        from filter_operasi
        group by nm_perawatan
        order by nm_perawatan
      '
    );
  END IF;
  
  IF p_show_inap THEN
    SET @sql = CONCAT(@sql, ', sum(case when kelas = "Kelas 3" then tarif else 0 end) desc');
  END IF;
  
  SET @p1 = regex;
  SET @p2= not_regex;
  
  PREPARE stmt FROM @sql;
  EXECUTE stmt USING @p1, @p2;
  DEALLOCATE PREPARE stmt;
end
;;
delimiter ;

-- ----------------------------
-- Procedure structure for sp_keu_tarif_operasi_tindakan
-- ----------------------------
DROP PROCEDURE IF EXISTS `sp_keu_tarif_operasi_tindakan`;
delimiter ;;
CREATE PROCEDURE `sp_keu_tarif_operasi_tindakan`(IN regex VARCHAR(200), IN not_regex VARCHAR(200)
, j_doctor BOOLEAN
, p_show_inap BOOLEAN
, p_show_khusus BOOLEAN 
, p_show_jalan BOOLEAN)
begin
  IF j_doctor THEN
    SET @sql = '
          with filter_operasi as 
            (
                select kode_paket, nm_perawatan, kelas
                , sewa_ok + alat as bagian_rs
                , operator1+operator2+operator3+dokter_pjanak+dokter_anak+dokter_anestesi+asisten_operator1+asisten_operator2+asisten_operator3+asisten_anestesi+asisten_anestesi2+instrumen+perawaat_resusitas+bidan+bidan2+bidan3+perawat_luar+akomodasi+bagian_rs+omloop+omloop2+omloop3+omloop4+omloop5+sarpras+dokter_umum as tarif
              from paket_operasi  where kd_pj = "-" 
              and nm_perawatan regexp ?
              and nm_perawatan not regexp ?)
              
            select 
            nm_perawatan
        ';
  ELSE 
    SET @sql = '
      with filter_operasi as 
            (
                select kode_paket, nm_perawatan, kelas
                , sewa_ok + alat as bagian_rs
                , operator1+operator2+operator3+dokter_pjanak+dokter_anak+dokter_anestesi+asisten_operator1+asisten_operator2+asisten_operator3+asisten_anestesi+asisten_anestesi2+instrumen+perawaat_resusitas+bidan+bidan2+bidan3+perawat_luar+sewa_ok+alat+akomodasi+bagian_rs+omloop+omloop2+omloop3+omloop4+omloop5+sarpras+dokter_umum as tarif
              from paket_operasi  where kd_pj = "-" 
              and nm_perawatan regexp ?
              and nm_perawatan not regexp ?)
              
            select 
            nm_perawatan
  ';
  END IF;
  
  IF p_show_inap THEN
    SET @sql = CONCAT(@sql, ', sum(case when kelas = "Kelas 3" then tarif else 0 end) as kelas_3
      , sum(case when kelas = "Kelas 2" then tarif else 0 end) as kelas_2
      , sum(case when kelas = "Kelas 1" then tarif else 0 end) as kelas_1
      , sum(case when kelas = "Kelas VIP" then tarif else 0 end) as kelas_vip
      , sum(case when kelas = "Kelas VVIP" then tarif else 0 end) as kelas_vvip');
  END IF;
  
  IF p_show_khusus THEN
    SET @sql = CONCAT(@sql, ', sum(case when kelas = "ICU" then tarif else 0 end) as kamar_khusus');
  END IF;
  
  IF p_show_jalan THEN
    SET @sql = CONCAT(@sql, ', sum(case when kelas = "Rawat Jalan" then tarif else 0 end) as rawat_jalan');
  END IF;    
  
  
  SET @sql = CONCAT(
    @sql,
    '
      from filter_operasi
      group by nm_perawatan
      order by nm_perawatan
    '
  );
  
  IF p_show_inap THEN
    SET @sql = CONCAT(@sql, ', sum(case when kelas = "Kelas 3" then tarif else 0 end) desc');
  END IF;
  
  SET @p1 = regex;
  SET @p2= not_regex;
  
  PREPARE stmt FROM @sql;
  EXECUTE stmt USING @p1, @p2;
  DEALLOCATE PREPARE stmt;

end
;;
delimiter ;

-- ----------------------------
-- Procedure structure for sp_keu_tarif_prosedur_inap
-- ----------------------------
DROP PROCEDURE IF EXISTS `sp_keu_tarif_prosedur_inap`;
delimiter ;;
CREATE PROCEDURE `sp_keu_tarif_prosedur_inap`()
begin
  select nm_perawatan, 
    sum(case when kelas = "Kelas 3" then total_byrdrpr else 0 end) as kelas_3,
    sum(case when kelas = "Kelas 2" then total_byrdrpr else 0 end) as kelas_2,
    sum(case when kelas = "Kelas 1" then total_byrdrpr else 0 end) as kelas_1, 
    sum(case when kelas = "Kelas VIP" then total_byrdrpr else 0 end) as kelas_vip,
    sum(case when kelas = "Kelas VVIP" then total_byrdrpr else 0 end) as kelas_vvip
  from (select * from jns_perawatan_inap where total_byrdrpr > 0 and status = "1" and kd_pj = "-" and kelas != "-") A
  
  where 
    kd_kategori in ("-", "RI") 
    and nm_perawatan not regexp "Perawat Pendamping|Dokter Pendamping|Ambulan|Visit|Pemakaian Oksigen| $P" 
    and kd_pj = "-"
  group by nm_perawatan;
end
;;
delimiter ;

-- ----------------------------
-- Procedure structure for sp_keu_tarif_radiologi
-- ----------------------------
DROP PROCEDURE IF EXISTS `sp_keu_tarif_radiologi`;
delimiter ;;
CREATE PROCEDURE `sp_keu_tarif_radiologi`()
begin
  select nm_perawatan
  , sum(case when kelas = "Kelas 3" then total_byr else 0 end) as kelas_3
  , sum(case when kelas = "Kelas 2" then total_byr else 0 end) as kelas_2
  , sum(case when kelas = "Kelas 1" then total_byr else 0 end) as kelas_1
  , sum(case when kelas = "Kelas VIP" then total_byr else 0 end) as kelas_vip
  , sum(case when kelas = "Kelas VVIP" then total_byr else 0 end) as kelas_vvip
  , sum(case when kelas = "Kelas Utama" then total_byr else 0 end) as kamar_khusus
  , sum(case when kelas = "Rawat Jalan" then total_byr else 0 end) as rawat_jalan
  from (select * from jns_perawatan_radiologi where total_byr > 0 and kelas != "-") A 
  where kd_pj = "-" and status = "1" and nm_perawatan not like "%PROMO%"
  group by nm_perawatan;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for sp_keu_tarif_rawat_inap
-- ----------------------------
DROP PROCEDURE IF EXISTS `sp_keu_tarif_rawat_inap`;
delimiter ;;
CREATE PROCEDURE `sp_keu_tarif_rawat_inap`(IN in_nama VARCHAR(200)
, IN in_kategori VARCHAR(200)
, IN not_nama VARCHAR(200)
, IN not_kategori VARCHAR(200)
, p_show_inap BOOLEAN)
begin 
  SET @sql = '
    select nm_perawatan, 
    sum(case when kelas = "Kelas 3" then total_byrdrpr else 0 end) as kelas_3,
    sum(case when kelas = "Kelas 2" then total_byrdrpr else 0 end) as kelas_2,
    sum(case when kelas = "Kelas 1" then total_byrdrpr else 0 end) as kelas_1, 
    sum(case when kelas = "Kelas VIP" then total_byrdrpr else 0 end) as kelas_vip,
    sum(case when kelas = "Kelas VVIP" then total_byrdrpr else 0 end) as kelas_vvip
  from (select * from jns_perawatan_inap where total_byrdrpr > 0 and status = "1" and kd_pj regexp "-|UMU" 
  ';
  
  IF p_show_inap THEN
    SET @sql = CONCAT(@sql, ') A');
  ELSE 
    SET @sql = CONCAT(@sql, 'and kelas != "-") A');
  END IF;
  
  SET @sql = CONCAT(@sql, '
    where 
    nm_perawatan regexp ?
    and kd_kategori regexp ?
    and nm_perawatan not regexp ?
    and kd_kategori not regexp ?
  group by nm_perawatan;');
  
  SET @p1 = in_nama;
  SET @p2 = in_kategori;
  SET @p3 = not_nama;
  SET @p4 = not_kategori;
  
  PREPARE stmt FROM @sql;
  EXECUTE stmt USING @p1, @p2, @p3, @p4;
  DEALLOCATE PREPARE stmt;
end
;;
delimiter ;

-- ----------------------------
-- Procedure structure for sp_keu_tarif_rawat_jalan
-- ----------------------------
DROP PROCEDURE IF EXISTS `sp_keu_tarif_rawat_jalan`;
delimiter ;;
CREATE PROCEDURE `sp_keu_tarif_rawat_jalan`(IN in_nama VARCHAR(200), 
    IN in_poli VARCHAR(200), 
    IN in_kategori VARCHAR(200),
    IN not_nama VARCHAR(200), 
    IN not_poli VARCHAR(200), 
    IN not_kategori VARCHAR(200))
begin
  select nm_perawatan, total_byrdrpr from jns_perawatan
  where kd_pj regexp "-|UMU" 
  and kd_kategori regexp in_kategori
  and kd_poli regexp in_poli
  and nm_perawatan regexp in_nama
  and kd_kategori not regexp not_kategori
  and kd_poli not regexp not_poli
  and nm_perawatan not regexp not_nama
  and status = "1"
  group by nm_perawatan;
end
;;
delimiter ;

-- ----------------------------
-- Procedure structure for sp_keu_tarif_utd
-- ----------------------------
DROP PROCEDURE IF EXISTS `sp_keu_tarif_utd`;
delimiter ;;
CREATE PROCEDURE `sp_keu_tarif_utd`()
begin 
  select nm_perawatan, total_byr from jns_perawatan_utd where status = "1";
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for sp_keu_tarif_visit_dokter_inap
-- ----------------------------
DROP PROCEDURE IF EXISTS `sp_keu_tarif_visit_dokter_inap`;
delimiter ;;
CREATE PROCEDURE `sp_keu_tarif_visit_dokter_inap`()
begin 
  select nm_perawatan
  , sum(case when kelas = "Kelas 3" then total_byrdrpr else 0 end) as kelas_3
  , sum(case when kelas = "Kelas 2" then total_byrdrpr else 0 end) as kelas_2
  , sum(case when kelas = "Kelas 1" then total_byrdrpr else 0 end) as kelas_1
    , sum(case when kelas = "Kelas VIP" then total_byrdrpr else 0 end) as vip
  , sum(case when kelas = "Kelas VVIP" then total_byrdrpr else 0 end) as vvip
--   , sum(case when kelas = "Kelas Utama" then total_byrdrpr else 0 end) as kelas_khusus
  from (select * from jns_perawatan_inap where kelas != "-") A
  where status = "1" and kd_kategori = "VISIT" and kd_pj = "-"
  group by nm_perawatan;
end
;;
delimiter ;

-- ----------------------------
-- Procedure structure for sp_Khanza_tampil_kamar_inap
-- ----------------------------
DROP PROCEDURE IF EXISTS `sp_Khanza_tampil_kamar_inap`;
delimiter ;;
CREATE PROCEDURE `sp_Khanza_tampil_kamar_inap`(IN p_mode           TINYINT,
  IN p_tgl1           DATE,
  IN p_tgl2           DATE,
  IN p_status_bayar   VARCHAR(20),
  IN p_bangsal        VARCHAR(100),
  IN p_dokter         VARCHAR(100),
  IN p_cari           VARCHAR(100),
  IN p_hitung_billing TINYINT,
  IN p_urut           VARCHAR(20))
BEGIN
  DECLARE v_cari VARCHAR(110);

  SET p_status_bayar = IFNULL(p_status_bayar,'');
  SET p_bangsal      = IFNULL(p_bangsal,'');
  SET p_dokter       = IFNULL(p_dokter,'');
  SET p_cari         = TRIM(IFNULL(p_cari,''));
  SET p_urut         = IFNULL(p_urut,'');
  SET v_cari         = CONCAT('%',p_cari,'%');

	WITH resiko_diet as
	(
		SELECT no_rawat, 
				CASE 
						WHEN nilai_total_gizi < 2 THEN 'Diet Normal'
						WHEN nilai_total_gizi >= 2 THEN 'Diet Beresiko'
				END AS kategori_resiko
		FROM penilaian_awal_keperawatan_ranap
		
		UNION ALL
    
		SELECT no_rawat,
        CASE skor_nutrisi
            WHEN 'Risikio Berat'  THEN 'Resiko Berat'
            WHEN 'Risiko Sedang'  THEN 'Resiko Sedang'
            WHEN 'Risiko Rendah'  THEN 'Resiko Rendah'
        END AS kategori_resiko
    FROM skrining_nutrisi_anak

    UNION ALL

    SELECT no_rawat,
        CASE
						WHEN total_hasil > 2 THEN 'Resiko Berat'
						WHEN sg3 = 'Ya' THEN 'Resiko Sedang'
						WHEN total_hasil >= 1 THEN 'Resiko Sedang'
						ELSE 'Resiko Rendah'
        END AS kategori_resiko
    FROM skrining_nutrisi_dewasa

    UNION ALL

    SELECT no_rawat,
        CASE skor_nutrisi
            WHEN 'Malnutrisi'          THEN 'Resiko Berat'
            WHEN 'Beresiko Malnutrisi' THEN 'Resiko Sedang'
            WHEN 'Status Gizi Normal'  THEN 'Resiko Rendah'
        END AS kategori_resiko
    FROM skrining_nutrisi_lansia
)
  SELECT t.*,
         IFNULL(t.tarif_raw,0) AS perkiraan_tarif,
         IF(t.tarif_raw IS NOT NULL AND t.tarif_raw <= t.billing,'Tidak Aman','Aman') AS pros
  FROM (
    SELECT kamar_inap.no_rawat, reg_periksa.no_rkm_medis, reg_periksa.biaya_reg,
           pasien.nm_pasien, pasien.jk,
           CONCAT(pasien.alamat,', ',kelurahan.nm_kel,', ',kecamatan.nm_kec,', ',kabupaten.nm_kab) AS alamat,
           reg_periksa.p_jawab, reg_periksa.hubunganpj, penjab.png_jawab,
           CONCAT(kamar_inap.kd_kamar,' ',bangsal.nm_bangsal) AS kamar,
           kamar_inap.trf_kamar, kamar_inap.diagnosa_awal, kamar_inap.diagnosa_akhir,
           kamar_inap.tgl_masuk, kamar_inap.jam_masuk,
           IF(kamar_inap.tgl_keluar='0000-00-00','',kamar_inap.tgl_keluar) AS tgl_keluar,
           IF(kamar_inap.jam_keluar='00:00:00','',kamar_inap.jam_keluar) AS jam_keluar,
           kamar_inap.ttl_biaya, kamar_inap.stts_pulang, kamar_inap.lama,
           dokter.nm_dokter, kamar_inap.kd_kamar, reg_periksa.kd_pj,
           CONCAT(reg_periksa.umurdaftar,' ',reg_periksa.sttsumur) AS umur,
           reg_periksa.status_bayar, pasien.agama,
           IFNULL((SELECT bridging_sep.klsnaik FROM bridging_sep
                   WHERE bridging_sep.no_rawat=reg_periksa.no_rawat AND bridging_sep.jnspelayanan=1 LIMIT 1),'') AS klsnaik,
           IFNULL(IF(kamar.kelas != CONCAT('Kelas ',bridging_sep.klsrawat),
                     CONCAT('Kelas ',bridging_sep.klsrawat),''),'') AS kelas_asli,
           IFNULL((SELECT bridging_sep.klsrawat FROM bridging_sep
                   WHERE bridging_sep.no_rawat=reg_periksa.no_rawat AND bridging_sep.jnspelayanan=1 LIMIT 1),'') AS klsrawat,
           '' AS proc,
           -- pengganti perhitungan diffDays di Java
           IF(kamar_inap.tgl_keluar='0000-00-00',0,DATEDIFF(CURDATE(),kamar_inap.tgl_keluar)) AS diff_days,
           IF(p_hitung_billing=1, fn_Khanza_billing_ranap(kamar_inap.no_rawat), 0) AS billing,
           (SELECT pb.tarif FROM perkiraan_biaya_ranap pb
             WHERE pb.no_rawat=kamar_inap.no_rawat LIMIT 1) AS tarif_raw,
					 IFNULL(pakr.nilai_total_gizi,'') AS nilai_total_gizi,
					 IFNULL(resiko_diet.kategori_resiko,'') as kategori_resiko
    FROM kamar_inap
      INNER JOIN reg_periksa ON kamar_inap.no_rawat=reg_periksa.no_rawat
      INNER JOIN pasien      ON reg_periksa.no_rkm_medis=pasien.no_rkm_medis
      INNER JOIN kamar       ON kamar_inap.kd_kamar=kamar.kd_kamar
      INNER JOIN bangsal     ON kamar.kd_bangsal=bangsal.kd_bangsal
      INNER JOIN kelurahan   ON pasien.kd_kel=kelurahan.kd_kel
      INNER JOIN kecamatan   ON pasien.kd_kec=kecamatan.kd_kec
      INNER JOIN kabupaten   ON pasien.kd_kab=kabupaten.kd_kab
      INNER JOIN penjab      ON reg_periksa.kd_pj=penjab.kd_pj
      LEFT JOIN dpjp_ranap   ON kamar_inap.no_rawat=dpjp_ranap.no_rawat
      LEFT JOIN dokter       ON dokter.kd_dokter=dpjp_ranap.kd_dokter
      LEFT JOIN bridging_sep ON reg_periksa.no_rawat=bridging_sep.no_rawat
			LEFT JOIN penilaian_awal_keperawatan_ranap pakr ON pakr.no_rawat = reg_periksa.no_rawat
			LEFT JOIN resiko_diet ON resiko_diet.no_rawat = reg_periksa.no_rawat
      -- titipan_ranap tidak dipakai di SELECT/WHERE, jadi join-nya dibuang
    WHERE
          -- filter utama sesuai radio button
          ( (p_mode=1 AND kamar_inap.stts_pulang='-')
         OR (p_mode=2 AND kamar_inap.tgl_masuk  BETWEEN p_tgl1 AND p_tgl2)
         OR (p_mode=3 AND kamar_inap.tgl_keluar BETWEEN p_tgl1 AND p_tgl2) )
          -- mode 1 tanpa filter bangsal/dokter: hanya DPJP utama (perilaku asli)
      AND (p_mode<>1 OR p_bangsal<>'' OR p_dokter<>'' OR dpjp_ranap.prioritas=1)
      AND reg_periksa.status_bayar LIKE CONCAT('%',p_status_bayar,'%')
      AND (p_bangsal='' OR bangsal.nm_bangsal=p_bangsal)
      AND (p_dokter ='' OR dokter.nm_dokter=p_dokter)
      AND (p_cari='' OR (
              kamar_inap.no_rawat LIKE v_cari
           OR reg_periksa.no_rkm_medis LIKE v_cari
           OR pasien.nm_pasien LIKE v_cari
           OR CONCAT(pasien.alamat,', ',kelurahan.nm_kel,', ',kecamatan.nm_kec,', ',kabupaten.nm_kab) LIKE v_cari
           OR kamar_inap.kd_kamar LIKE v_cari
           OR bangsal.nm_bangsal LIKE v_cari
           OR kamar_inap.diagnosa_awal LIKE v_cari
           OR kamar_inap.diagnosa_akhir LIKE v_cari
           OR kamar_inap.tgl_masuk LIKE v_cari
           OR dokter.nm_dokter LIKE v_cari
           OR kamar_inap.stts_pulang LIKE v_cari
           OR kamar_inap.tgl_keluar LIKE v_cari
           OR penjab.png_jawab LIKE v_cari
           OR pasien.agama LIKE v_cari
           OR CONCAT('Kelas ',bridging_sep.klsrawat) LIKE v_cari ))
    GROUP BY kamar_inap.no_rawat
  ) t
  ORDER BY
    CASE WHEN p_urut='nama'  THEN t.nm_pasien END,
    CASE WHEN p_urut='kamar' THEN t.kamar     END,
    t.tgl_masuk DESC, t.jam_masuk DESC;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for sp_waktu_server
-- ----------------------------
DROP PROCEDURE IF EXISTS `sp_waktu_server`;
delimiter ;;
CREATE PROCEDURE `sp_waktu_server`()
  READS SQL DATA 
  DETERMINISTIC
  COMMENT 'Waktu server MySQL untuk timestamp dokumen'
BEGIN
    SELECT
        NOW()                                AS waktu,
        DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s') AS waktu_teks,
        @@session.time_zone                  AS zona,
        @@global.hostname                    AS server;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for TambahObat_RANAP_BPJS
-- ----------------------------
DROP PROCEDURE IF EXISTS `TambahObat_RANAP_BPJS`;
delimiter ;;
CREATE PROCEDURE `TambahObat_RANAP_BPJS`(IN p_no_rawat VARCHAR(17) CHARACTER SET latin1 COLLATE latin1_swedish_ci, IN p_kode_brng VARCHAR(15), IN p_kelas VARCHAR(15))
BEGIN
	DECLARE v_noresep VARCHAR(14);
	DECLARE v_tgl date;
	DECLARE v_jam time;
	DECLARE v_kdbrng VARCHAR(15);
	DECLARE v_nmbrng VARCHAR(300);
	DECLARE v_hbeli DOUBLE;
	DECLARE v_hjual DOUBLE;
	
	SELECT no_resep,tgl_perawatan,jam 
	INTO v_noresep, v_tgl, v_jam
	FROM resep_obat where no_rawat = p_no_rawat ORDER BY no_resep DESC LIMIT 1 OFFSET 1;
	
	SELECT kode_brng, nama_brng, h_beli,
			CASE 
					 WHEN p_kelas = 'kelas 1' THEN kelas1
					 WHEN p_kelas = 'kelas 2' THEN kelas2
					 WHEN p_kelas = 'kelas 3' THEN kelas3
					 WHEN p_kelas = 'kelas utama' THEN utama
					 WHEN p_kelas = 'kelas vip' THEN vip
					 WHEN p_kelas = 'kelas vvip' THEN vvip
					 ELSE NULL 
			END
	INTO v_kdbrng, v_nmbrng, v_hbeli, v_hjual
	FROM databarang where kode_brng = p_kode_brng;

	IF v_noresep IS NOT NULL AND v_noresep != '' THEN
		
		-- tambahkan item obat ke dalam resep 
		INSERT INTO resep_dokter 
				(no_resep, kode_brng, jml, aturan_pakai) 
		VALUES 
				(v_noresep, p_kode_brng, 1, '');
		
		-- tambahkan item obat kedalam detail pemberian obat
		INSERT INTO detail_pemberian_obat 
				(tgl_perawatan, jam, no_rawat, kode_brng, h_beli, biaya_obat, jml, embalase, tuslah, total, status, kd_bangsal, no_batch, no_faktur ) 
		VALUES 
				(v_tgl, v_jam, p_no_rawat, p_kode_brng, v_hbeli, v_hjual, 1, 0, 0, v_hjual, 'Ranap', 'FARMA', '', '');

		select 
			v_noresep as noresep, 
			v_tgl as tgl, 
			v_jam as jam, 
			v_kdbrng as kode_brng,
			v_nmbrng as nama_brng, 
			v_hbeli as h_beli, 
			v_hjual as h_jual;
	END IF;
	
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for tampilAsuhanGizi
-- ----------------------------
DROP PROCEDURE IF EXISTS `tampilAsuhanGizi`;
delimiter ;;
CREATE PROCEDURE `tampilAsuhanGizi`(IN kriteria VARCHAR(50), IN tglAwal VARCHAR(25),IN tglAkhir VARCHAR(25))
BEGIN
	drop temporary table if EXISTS tmp;
	
	
	IF( kriteria = '' ) then
				create temporary table tmp
				select 
							reg_periksa.no_rawat,pasien.no_rkm_medis,pasien.nm_pasien,pasien.jk,pasien.tgl_lahir,asuhan_gizi.tanggal,
							asuhan_gizi.antropometri_bb,asuhan_gizi.antropometri_tb,asuhan_gizi.antropometri_imt,asuhan_gizi.antropometri_lla,
							asuhan_gizi.antropometri_tl,asuhan_gizi.antropometri_ulna,asuhan_gizi.antropometri_bbideal,asuhan_gizi.antropometri_bbperu,
							asuhan_gizi.antropometri_tbperu,asuhan_gizi.antropometri_bbpertb,asuhan_gizi.antropometri_llaperu,asuhan_gizi.biokimia,
							asuhan_gizi.fisik_klinis,asuhan_gizi.alergi_telur,asuhan_gizi.alergi_susu_sapi,asuhan_gizi.alergi_kacang,asuhan_gizi.alergi_gluten,
							asuhan_gizi.alergi_udang,asuhan_gizi.alergi_ikan,asuhan_gizi.alergi_hazelnut,asuhan_gizi.pola_makan,asuhan_gizi.riwayat_personal,
							asuhan_gizi.diagnosis,asuhan_gizi.intervensi_gizi,asuhan_gizi.monitoring_evaluasi,asuhan_gizi.nip,petugas.nama,kamar_inap.tgl_masuk,kamar_inap.kd_kamar,penjab.png_jawab 
				from reg_periksa 
							inner join pasien on reg_periksa.no_rkm_medis=pasien.no_rkm_medis 
							inner join asuhan_gizi on reg_periksa.no_rawat=asuhan_gizi.no_rawat 
							inner join petugas on asuhan_gizi.nip=petugas.nip 
							inner join kamar_inap ON reg_periksa.no_rawat = kamar_inap.no_rawat 
							inner join penjab ON reg_periksa.kd_pj = penjab.kd_pj 
				where 
							asuhan_gizi.tanggal between tglAwal and tglAkhir
				order by 
							reg_periksa.no_rawat, asuhan_gizi.tanggal, kamar_inap.tgl_masuk desc;
	ELSE
				create temporary table tmp
				select 
							reg_periksa.no_rawat,pasien.no_rkm_medis,pasien.nm_pasien,pasien.jk,pasien.tgl_lahir,asuhan_gizi.tanggal,
							asuhan_gizi.antropometri_bb,asuhan_gizi.antropometri_tb,asuhan_gizi.antropometri_imt,asuhan_gizi.antropometri_lla,
							asuhan_gizi.antropometri_tl,asuhan_gizi.antropometri_ulna,asuhan_gizi.antropometri_bbideal,asuhan_gizi.antropometri_bbperu,
							asuhan_gizi.antropometri_tbperu,asuhan_gizi.antropometri_bbpertb,asuhan_gizi.antropometri_llaperu,asuhan_gizi.biokimia,
							asuhan_gizi.fisik_klinis,asuhan_gizi.alergi_telur,asuhan_gizi.alergi_susu_sapi,asuhan_gizi.alergi_kacang,asuhan_gizi.alergi_gluten,
							asuhan_gizi.alergi_udang,asuhan_gizi.alergi_ikan,asuhan_gizi.alergi_hazelnut,asuhan_gizi.pola_makan,asuhan_gizi.riwayat_personal,
							asuhan_gizi.diagnosis,asuhan_gizi.intervensi_gizi,asuhan_gizi.monitoring_evaluasi,asuhan_gizi.nip,petugas.nama,kamar_inap.tgl_masuk,kamar_inap.kd_kamar,penjab.png_jawab 
				from reg_periksa 
							inner join pasien on reg_periksa.no_rkm_medis=pasien.no_rkm_medis 
							inner join asuhan_gizi on reg_periksa.no_rawat=asuhan_gizi.no_rawat 
							inner join petugas on asuhan_gizi.nip=petugas.nip 
							inner join kamar_inap ON reg_periksa.no_rawat = kamar_inap.no_rawat 
							inner join penjab ON reg_periksa.kd_pj = penjab.kd_pj 
				where 
							asuhan_gizi.tanggal between tglAwal and tglAkhir and reg_periksa.no_rawat like kriteria or 
              asuhan_gizi.tanggal between tglAwal and tglAkhir and pasien.no_rkm_medis like kriteria or 
              asuhan_gizi.tanggal between tglAwal and tglAkhir and pasien.nm_pasien like kriteria or 
              asuhan_gizi.tanggal between tglAwal and tglAkhir and asuhan_gizi.nip like kriteria or 
              asuhan_gizi.tanggal between tglAwal and tglAkhir and asuhan_gizi.diagnosis like kriteria or 
              asuhan_gizi.tanggal between tglAwal and tglAkhir and petugas.nama like kriteria
							
				order by 
							reg_periksa.no_rawat, asuhan_gizi.tanggal, kamar_inap.tgl_masuk desc;	
	END IF;
	
	select * from tmp GROUP BY no_rawat;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for taskid
-- ----------------------------
DROP PROCEDURE IF EXISTS `taskid`;
delimiter ;;
CREATE PROCEDURE `taskid`()
BEGIN
	declare xtanggal date default date(now());
	#TASK ID 3-4
	
	DECLARE
		CONTINUE
		HANDLER 
		FOR
		SQLEXCEPTION
	BEGIN
		GET
			DIAGNOSTICS
			CONDITION			1				@GxPesan		=	MESSAGE_TEXT,
													@GxNomor		=	MYSQL_ERRNO,
													@GxStatus 	= RETURNED_SQLSTATE
		;
	END
	;
	
	SET											@GxPesan			=	'',
													@GxNomor			=	0,
													@GxStatus 		= 0
	;
	
	
	
	
UPDATE mutasi_berkas
JOIN reg_periksa ON mutasi_berkas.no_rawat = reg_periksa.no_rawat 
SET mutasi_berkas.diterima = DATE_ADD( mutasi_berkas.dikirim, INTERVAL FLOOR( RAND() * ( 54 * 60 + 6 * 60 ) ) SECOND ) 
WHERE
	(
		TIMESTAMPDIFF( SECOND, mutasi_berkas.dikirim, mutasi_berkas.diterima ) > 4600 
		OR TIMESTAMPDIFF( SECOND, mutasi_berkas.dikirim, mutasi_berkas.diterima ) < 489
	) 
-- 	AND reg_periksa.no_rawat = '2024/03/14/000009'
	AND reg_periksa.tgl_registrasi between  date_add( xtanggal , interval -10 day) and xtanggal
	AND reg_periksa.kd_poli <> 'IGDK' 
	AND reg_periksa.kd_poli <> 'UMU'
	AND reg_periksa.kd_poli <> 'HCare' 
	AND reg_periksa.kd_poli <> 'LAB' 
	AND reg_periksa.kd_poli <> 'GIG'
	AND reg_periksa.kd_poli <> 'GIZ'
	AND reg_periksa.kd_poli <> 'RDO'
	AND reg_periksa.stts <> 'Batal'
	AND reg_periksa.stts <> 'Dirawat';
	
#TASK ID 4-5	
	UPDATE pemeriksaan_ralan
JOIN reg_periksa ON pemeriksaan_ralan.no_rawat = reg_periksa.no_rawat
JOIN mutasi_berkas ON pemeriksaan_ralan.no_rawat = mutasi_berkas.no_rawat 
SET 				tgl_perawatan = DATE_ADD( mutasi_berkas.diterima, INTERVAL FLOOR( RAND() * ( 40 * 60 + 6 * 60 )) SECOND ),
					jam_rawat = DATE_ADD( mutasi_berkas.diterima, INTERVAL FLOOR( RAND() * ( 40 * 60 + 6 * 60 )) SECOND ) 
WHERE
	(
		TIMESTAMPDIFF(
			SECOND,
			mutasi_berkas.diterima,
		CONCAT( tgl_perawatan, ' ', jam_rawat )) > 2400
		OR TIMESTAMPDIFF(
			SECOND,
			mutasi_berkas.diterima,
		CONCAT( tgl_perawatan, ' ', jam_rawat )) < 424 
	) --     AND reg_periksa.no_rawat = '2023/07/14/000002'
	
	AND reg_periksa.tgl_registrasi  between  date_add( xtanggal , interval -10 day) and xtanggal  #= xtanggal
	AND reg_periksa.kd_poli <> 'IGDK' 
	AND reg_periksa.kd_poli <> 'UMU' 
	AND reg_periksa.kd_poli <> 'HCare' 
	AND reg_periksa.kd_poli <> 'LAB' 
	AND reg_periksa.kd_poli <> 'GIG'
	AND reg_periksa.kd_poli <> 'GIZ'
	AND reg_periksa.kd_poli <> 'RDO'
	AND reg_periksa.stts <> 'Batal'
	AND reg_periksa.stts <> 'Dirawat';
	
#TASK ID 5-6	
	UPDATE resep_obat
JOIN reg_periksa ON resep_obat.no_rawat = reg_periksa.no_rawat
JOIN pemeriksaan_ralan ON resep_obat.no_rawat = pemeriksaan_ralan.no_rawat 
SET resep_obat.tgl_peresepan = pemeriksaan_ralan.tgl_perawatan,
resep_obat.jam_peresepan = pemeriksaan_ralan.jam_rawat + INTERVAL FLOOR( RAND() * ( 30 ) + 5 ) MINUTE + INTERVAL FLOOR( RAND() * 60 ) SECOND 
WHERE
	(
		TIMEDIFF(
			CONCAT( resep_obat.tgl_peresepan, ' ', resep_obat.jam_peresepan ),
		CONCAT( pemeriksaan_ralan.tgl_perawatan, ' ', pemeriksaan_ralan.jam_rawat )) > '00:45:58' 
		OR TIMEDIFF( CONCAT( resep_obat.tgl_peresepan, ' ', resep_obat.jam_peresepan ), CONCAT( pemeriksaan_ralan.tgl_perawatan, ' ', pemeriksaan_ralan.jam_rawat ) ) < '00:07:00' 
	) 
	AND reg_periksa.tgl_registrasi    between  date_add( xtanggal , interval -10 day) and xtanggal # = xtanggal
	AND reg_periksa.kd_poli <> 'IGDK' 
	AND reg_periksa.kd_poli <> 'UMU' 
	AND reg_periksa.kd_poli <> 'HCare' 
	AND reg_periksa.kd_poli <> 'LAB' 
	AND reg_periksa.kd_poli <> 'GIG'
	AND reg_periksa.kd_poli <> 'GIZ'
	AND reg_periksa.kd_poli <> 'RDO'
	AND reg_periksa.stts <> 'Batal'
	AND resep_obat.`status` = 'ralan'
	AND reg_periksa.stts <> 'Dirawat';
	
#TASK ID 6-7
UPDATE resep_obat
JOIN reg_periksa ON resep_obat.no_rawat = reg_periksa.no_rawat 
SET resep_obat.jam = DATE_ADD( resep_obat.jam_peresepan, INTERVAL FLOOR( RAND() * ( 25 * 60 + 6 * 60 ) ) SECOND ) 
WHERE
	(
		TIMESTAMPDIFF( SECOND, resep_obat.jam_peresepan, resep_obat.jam ) > 2931
		OR TIMESTAMPDIFF( SECOND, resep_obat.jam_peresepan, resep_obat.jam ) < 417
	) -- 	AND reg_periksa.no_rawat = '2024/03/15/000001'
	AND reg_periksa.tgl_registrasi  between  date_add( xtanggal , interval -10 day) and xtanggal #= xtanggal
	AND reg_periksa.kd_poli <> 'IGDK' 
	AND reg_periksa.kd_poli <> 'UMU' 
	AND reg_periksa.kd_poli <> 'HCare' 
	AND reg_periksa.kd_poli <> 'LAB' 
	AND reg_periksa.kd_poli <> 'GIG'
	AND reg_periksa.kd_poli <> 'GIZ'
	AND reg_periksa.kd_poli <> 'RDO'
	AND reg_periksa.stts <> 'Batal'
	AND resep_obat.`status` = 'ralan'
	AND resep_obat.jam_peresepan <> '00:00:00'
	AND resep_obat.jam <> '00:00:00'
	AND reg_periksa.stts <> 'Dirawat';
	
#UPDATE STATUS SUDAH
update referensi_mobilejkn_bpjs set referensi_mobilejkn_bpjs.statuskirim = 'Sudah';
update referensi_mobilejkn_bpjs_batal set referensi_mobilejkn_bpjs_batal.statuskirim = 'Sudah';
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for test_obat_dynamic
-- ----------------------------
DROP PROCEDURE IF EXISTS `test_obat_dynamic`;
delimiter ;;
CREATE PROCEDURE `test_obat_dynamic`(IN p_no_rkm_medis VARCHAR(20))
BEGIN

    SET @v_obat = '';

    SET @sql = '
        SELECT GROUP_CONCAT(
            CONCAT(
                ''<tr>'',
                ''<td>'', x.kode_brng, ''</td>'',
                ''<td>'', x.nama_brng, ''</td>'',
                ''<td>'', x.jumlah_hari, '' hari</td>'',
                ''<td>'', x.total_jumlah, ''</td>'',
                ''<td>'', DATE_FORMAT(x.terakhir, ''%d-%m-%Y''), ''</td>'',
                ''</tr>''
            )
            ORDER BY x.jumlah_hari DESC, x.terakhir DESC
            SEPARATOR ''''
        )
        INTO @v_obat
        FROM (
            SELECT
                dpo.kode_brng,
                db.nama_brng,
                COUNT(DISTINCT dpo.tgl_perawatan) AS jumlah_hari,
                SUM(dpo.jml) AS total_jumlah,
                MAX(dpo.tgl_perawatan) AS terakhir
            FROM detail_pemberian_obat dpo
            JOIN reg_periksa rp
                ON rp.no_rawat = dpo.no_rawat
            JOIN databarang db
                ON db.kode_brng = dpo.kode_brng
            WHERE rp.no_rkm_medis = ?
            GROUP BY dpo.kode_brng, db.nama_brng
        ) x
    ';

    PREPARE stmt FROM @sql;

    SET @medis = p_no_rkm_medis;

    EXECUTE stmt USING @medis;

    DEALLOCATE PREPARE stmt;

    SELECT @v_obat AS html_obat;

END
;;
delimiter ;

