-- ----------------------------
-- Procedure structure for test_obat_prmrj
-- ----------------------------
DROP PROCEDURE IF EXISTS `test_obat_prmrj`;
delimiter ;;
CREATE PROCEDURE `test_obat_prmrj`(IN p_no_rkm_medis VARCHAR(20))
BEGIN
    DECLARE v_html LONGTEXT DEFAULT '';
    DECLARE t1 DATETIME(6);
    DECLARE t2 DATETIME(6);

    SET v_html = CONVERT(
        '<html><body>'
        USING utf8mb4
    );

    SET t1 = NOW(6);

    SET v_html = CONVERT(
        CONCAT(
            v_html,
            '<h3>Obat yang Sering Digunakan</h3>',
            '<table>',
            '<tr><th>Kode</th><th>Nama Obat</th><th>Jumlah Hari</th><th>Total Jumlah</th><th>Terakhir</th></tr>',
            COALESCE(
                (
                    SELECT GROUP_CONCAT(
                        CONVERT(
                            CONCAT(
                                '<tr>',
                                '<td>',
                                COALESCE(CONVERT(x.kode_brng USING utf8mb4),''),
                                '</td>',
                                '<td>',
                                COALESCE(CONVERT(x.nama_brng USING utf8mb4),''),
                                '</td>',
                                '<td align="center">',
                                COALESCE(x.jumlah_hari,0),' hari',
                                '</td>',
                                '<td align="right">',
                                COALESCE(FORMAT(x.total_jumlah,2),'0'),
                                '</td>',
                                '<td class="tanggal">',
                                COALESCE(DATE_FORMAT(x.terakhir,'%d-%m-%Y'),''),
                                '</td>',
                                '</tr>'
                            )
                            USING utf8mb4
                        )
                        ORDER BY x.jumlah_hari DESC, x.terakhir DESC
                        SEPARATOR ''
                    )
                    FROM
                    (
                        SELECT
                            CONVERT(dpo.kode_brng USING utf8mb4) AS kode_brng,
                            CONVERT(db.nama_brng USING utf8mb4) AS nama_brng,
                            COUNT(DISTINCT dpo.tgl_perawatan) AS jumlah_hari,
                            SUM(dpo.jml) AS total_jumlah,
                            MAX(dpo.tgl_perawatan) AS terakhir
                        FROM detail_pemberian_obat dpo
                        JOIN reg_periksa rp 
                            ON rp.no_rawat = dpo.no_rawat
                        JOIN databarang db 
                            ON db.kode_brng = dpo.kode_brng
                        WHERE rp.no_rkm_medis = p_no_rkm_medis
                        GROUP BY dpo.kode_brng, db.nama_brng
                    ) x
                ),
                '<tr><td colspan="5">Tidak ada riwayat obat.</td></tr>'
            ),
            '</table>'
        )
        USING utf8mb4
    );

    SET t2 = NOW(6);

    SELECT
        TIMESTAMPDIFF(MICROSECOND,t1,t2) / 1000000 AS waktu_detik,
        LENGTH(v_html) AS panjang_html;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for test_obat_prmrj2
-- ----------------------------
DROP PROCEDURE IF EXISTS `test_obat_prmrj2`;
delimiter ;;
CREATE PROCEDURE `test_obat_prmrj2`(IN p_no_rkm_medis VARCHAR(20))
BEGIN
    DECLARE v_html LONGTEXT DEFAULT '';
    DECLARE v_obat LONGTEXT DEFAULT '';
    DECLARE t1 DATETIME(6);
    DECLARE t2 DATETIME(6);
    DECLARE t3 DATETIME(6);
    DECLARE t4 DATETIME(6);

    SET v_html = '<html><body>';

    /* TEST 1: hasil GROUP_CONCAT saja */
    SET t1 = NOW(6);

    SELECT GROUP_CONCAT(
        CONCAT(
            '<tr>',
            '<td>', x.kode_brng, '</td>',
            '<td>', x.nama_brng, '</td>',
            '<td>', x.jumlah_hari, ' hari</td>',
            '<td>', x.total_jumlah, '</td>',
            '<td>', DATE_FORMAT(x.terakhir,'%d-%m-%Y'), '</td>',
            '</tr>'
        )
        ORDER BY x.jumlah_hari DESC, x.terakhir DESC
        SEPARATOR ''
    )
    INTO v_obat
    FROM
    (
        SELECT
            dpo.kode_brng,
            db.nama_brng,
            COUNT(DISTINCT dpo.tgl_perawatan) AS jumlah_hari,
            SUM(dpo.jml) AS total_jumlah,
            MAX(dpo.tgl_perawatan) AS terakhir
        FROM detail_pemberian_obat dpo
        JOIN reg_periksa rp 
            ON rp.no_rawat = dpo.no_rawat
        JOIN databarang db 
            ON db.kode_brng = dpo.kode_brng
        WHERE rp.no_rkm_medis = p_no_rkm_medis
        GROUP BY dpo.kode_brng, db.nama_brng
    ) x;

    SET t2 = NOW(6);

    /* TEST 2: CONCAT saja */
    SET t1 = NOW(6);

    SET v_html = CONCAT(
        v_html,
        v_obat,
        '</body></html>'
    );

    SET t3 = NOW(6);

    /* TEST 3: CONVERT hasil akhir */
    SET t1 = NOW(6);

    SET v_html = CONVERT(v_html USING utf8mb4);

    SET t4 = NOW(6);

    SELECT
        TIMESTAMPDIFF(MICROSECOND,t2,t1) / 1000000 AS dummy,
        TIMESTAMPDIFF(MICROSECOND,t1,t3) / 1000000 AS concat_detik,
        TIMESTAMPDIFF(MICROSECOND,t3,t4) / 1000000 AS convert_detik,
        LENGTH(v_obat) AS panjang_obat,
        LENGTH(v_html) AS panjang_html;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for test_obat_prmrj3
-- ----------------------------
DROP PROCEDURE IF EXISTS `test_obat_prmrj3`;
delimiter ;;
CREATE PROCEDURE `test_obat_prmrj3`(IN p_no_rkm_medis VARCHAR(20))
BEGIN
    DECLARE v_html LONGTEXT DEFAULT '';
    DECLARE t1 DATETIME(6);
    DECLARE t2 DATETIME(6);

    SET v_html = '<html><body>';

    SET t1 = NOW(6);

    SET v_html = CONCAT(
        v_html,
        '<h3>Obat yang Sering Digunakan</h3>',
        '<table>',
        '<tr><th>Kode</th><th>Nama Obat</th><th>Jumlah Hari</th><th>Total Jumlah</th><th>Terakhir</th></tr>',
        COALESCE(
            (
                SELECT GROUP_CONCAT(
                    CONCAT(
                        '<tr>',
                        '<td>', x.kode_brng, '</td>',
                        '<td>', x.nama_brng, '</td>',
                        '<td align="center">',
                        x.jumlah_hari, ' hari',
                        '</td>',
                        '<td align="right">',
                        FORMAT(x.total_jumlah,2),
                        '</td>',
                        '<td class="tanggal">',
                        DATE_FORMAT(x.terakhir,'%d-%m-%Y'),
                        '</td>',
                        '</tr>'
                    )
                    ORDER BY x.jumlah_hari DESC, x.terakhir DESC
                    SEPARATOR ''
                )
                FROM
                (
                    SELECT
                        dpo.kode_brng,
                        db.nama_brng,
                        COUNT(DISTINCT dpo.tgl_perawatan) AS jumlah_hari,
                        SUM(dpo.jml) AS total_jumlah,
                        MAX(dpo.tgl_perawatan) AS terakhir
                    FROM detail_pemberian_obat dpo
                    JOIN reg_periksa rp
                        ON rp.no_rawat = dpo.no_rawat
                    JOIN databarang db
                        ON db.kode_brng = dpo.kode_brng
                    WHERE rp.no_rkm_medis = p_no_rkm_medis
                    GROUP BY dpo.kode_brng, db.nama_brng
                ) x
            ),
            '<tr><td colspan="5">Tidak ada riwayat obat.</td></tr>'
        ),
        '</table>'
    );

    SET t2 = NOW(6);

    SELECT
        TIMESTAMPDIFF(MICROSECOND,t1,t2) / 1000000 AS waktu_detik,
        LENGTH(v_html) AS panjang_html;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for Ubah_BPJSTK1_ralan
-- ----------------------------
DROP PROCEDURE IF EXISTS `Ubah_BPJSTK1_ralan`;
delimiter ;;
CREATE PROCEDURE `Ubah_BPJSTK1_ralan`(IN norawat VARCHAR(17) CHARACTER SET latin1 COLLATE latin1_swedish_ci)
BEGIN
	
 	# hapus biaya pendaftaran untuk BPJS TK di tabel 'reg_periksa' 
	UPDATE reg_periksa 
	SET reg_periksa.biaya_reg = 0 
	WHERE reg_periksa.no_rawat = norawat;	
	
	# hapus biaya pendaftaran untuk BPJS TK di tabel 'billing'
	UPDATE billing 
	SET billing.totalbiaya = 0 
	WHERE billing.no_rawat = norawat AND billing.status like 'Registrasi';
	
	# rubah biaya tindakan dari pasien umum menjadi pasien BPJS TENAGA KERJA
	UPDATE rawat_jl_dr
			inner join jns_perawatan jpawal on rawat_jl_dr.kd_jenis_prw = jpawal.kd_jenis_prw
			inner join jns_perawatan jptuj on jptuj.kd_jenis_prw = CONCAT("BJK",jpawal.kd_jenis_prw)
	SET 
			rawat_jl_dr.kd_jenis_prw = jptuj.kd_jenis_prw, 
			rawat_jl_dr.material = jptuj.material, 
			rawat_jl_dr.bhp = jptuj.bhp, 
			rawat_jl_dr.tarif_tindakandr = jptuj.tarif_tindakandr,
			rawat_jl_dr.biaya_rawat = jptuj.total_byrdrpr
	where rawat_jl_dr.no_rawat = norawat; #AND jptuj.kd_pj like 'BJK';
	
		# rubah biaya tindakan dari pasien umum menjadi pasien BPJS TENAGA KERJA
	UPDATE rawat_jl_pr
			inner join jns_perawatan jpawal on rawat_jl_pr.kd_jenis_prw = jpawal.kd_jenis_prw
			inner join jns_perawatan jptuj on jptuj.kd_jenis_prw = CONCAT("BJK",jpawal.kd_jenis_prw)
	SET 
			rawat_jl_pr.kd_jenis_prw = jptuj.kd_jenis_prw, 
			rawat_jl_pr.material = jptuj.material, 
			rawat_jl_pr.bhp = jptuj.bhp, 
			rawat_jl_pr.tarif_tindakanpr = jptuj.tarif_tindakanpr,
			rawat_jl_pr.biaya_rawat = jptuj.total_byrdrpr
	where rawat_jl_pr.no_rawat = norawat; #AND jptuj.kd_pj like 'BJK';
	
	# rubah biaya tindakan dari pasien umum menjadi pasien BPJS TENAGA KERJA
	UPDATE rawat_jl_drpr
			inner join jns_perawatan jpawal on rawat_jl_drpr.kd_jenis_prw = jpawal.kd_jenis_prw
			inner join jns_perawatan jptuj on jptuj.kd_jenis_prw = CONCAT("BJK",jpawal.kd_jenis_prw)
	SET 
			rawat_jl_drpr.kd_jenis_prw = jptuj.kd_jenis_prw, 
			rawat_jl_drpr.material = jptuj.material, 
			rawat_jl_drpr.bhp = jptuj.bhp, 
			rawat_jl_drpr.tarif_tindakandr = jptuj.tarif_tindakandr,
			rawat_jl_drpr.tarif_tindakanpr = jptuj.tarif_tindakanpr,
			rawat_jl_drpr.biaya_rawat = jptuj.total_byrdrpr
	where rawat_jl_drpr.no_rawat = norawat; #AND jptuj.kd_pj like 'BJK';
	
	# rubah di table billing, biaya tindakan dari pasien umum menjadi pasien BPJS TENAGA KERJA
	UPDATE billing b
	JOIN jns_perawatan jp ON jp.nm_perawatan = b.nm_perawatan AND jp.kd_jenis_prw NOT LIKE 'BJK%'
	JOIN jns_perawatan jpbjk ON jpbjk.kd_jenis_prw = CONCAT('BJK', jp.kd_jenis_prw)
	SET
	b.biaya = CASE
								WHEN b.`status` = 'Ralan dokter' THEN jpbjk.total_byrdr
								WHEN b.`status` = 'Ralan Paramedis' THEN jpbjk.total_byrpr
								WHEN b.`status` = 'Ralan Dokter Paramedis' THEN jpbjk.total_byrdrpr
								ELSE b.biaya
								END,
	b.totalbiaya = (
	CASE
			WHEN b.`status` = 'Ralan dokter' THEN jpbjk.total_byrdr
			WHEN b.`status` = 'Ralan Paramedis' THEN jpbjk.total_byrpr
			WHEN b.`status` = 'Ralan Dokter Paramedis' THEN jpbjk.total_byrdrpr
			ELSE b.biaya
	END
	* COALESCE(b.jumlah,0) ) + COALESCE(b.tambahan,0)
	WHERE b.`status` IN ('Ralan dokter', 'Ralan Paramedis', 'Ralan Dokter Paramedis')
	AND b.no_rawat = norawat; 
	
-- 	SELECT reg_periksa.biaya_reg FROM reg_periksa WHERE reg_periksa.no_rawat = norawat;
-- 	
-- 	select rawat_jl_dr.*, jns_perawatan.nm_perawatan 
-- 	from rawat_jl_dr inner join jns_perawatan on jns_perawatan.kd_jenis_prw = rawat_jl_dr.kd_jenis_prw 
-- 	where rawat_jl_dr.no_rawat = norawat;
-- 	
-- 	select rawat_jl_pr.*, jns_perawatan.nm_perawatan 
-- 	from rawat_jl_pr inner join jns_perawatan on jns_perawatan.kd_jenis_prw = rawat_jl_pr.kd_jenis_prw 
-- 	where rawat_jl_pr.no_rawat = norawat;
-- 	
-- 	select rawat_jl_drpr.*, jns_perawatan.nm_perawatan 
-- 	from rawat_jl_drpr inner join jns_perawatan on jns_perawatan.kd_jenis_prw = rawat_jl_drpr.kd_jenis_prw 
-- 	where rawat_jl_drpr.no_rawat = norawat;
	
	SELECT * from billing where no_rawat = norawat;
	SELECT SUM(totalbiaya) as SUM from billing where no_rawat = norawat;
	
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for Ubah_BPJSTK2_RAD_LAB
-- ----------------------------
DROP PROCEDURE IF EXISTS `Ubah_BPJSTK2_RAD_LAB`;
delimiter ;;
CREATE PROCEDURE `Ubah_BPJSTK2_RAD_LAB`(norawat VARCHAR(20))
BEGIN

	# rubah biaya tindakan radiologi
	UPDATE periksa_radiologi PR
			INNER JOIN jns_perawatan_radiologi JPAWAL on JPAWAL.kd_jenis_prw = PR.kd_jenis_prw
			INNER JOIN jns_perawatan_radiologi JPTUJ on JPTUJ.kd_jenis_prw = CONCAT("BJK",JPAWAL.kd_jenis_prw)
	SET 
			PR.kd_jenis_prw 					= JPTUJ.kd_jenis_prw, 
			PR.bagian_rs 							= JPTUJ.bagian_rs, 
			PR.bhp 										= JPTUJ.bhp, 
			PR.tarif_perujuk 					= JPTUJ.tarif_perujuk,
			PR.tarif_tindakan_dokter 	= JPTUJ.tarif_tindakan_dokter,
			PR.tarif_tindakan_petugas = JPTUJ.tarif_tindakan_petugas,
			PR.kso 										= JPTUJ.kso,
			PR.menejemen 							= JPTUJ.menejemen,
			PR.biaya 									= JPTUJ.total_byr
	where PR.no_rawat = norawat;
	
		# rubah biaya tindakan laborat
	UPDATE periksa_lab PL
			INNER JOIN jns_perawatan_lab JPAWAL on JPAWAL.kd_jenis_prw = PL.kd_jenis_prw
			INNER JOIN jns_perawatan_lab JPTUJ on JPTUJ.kd_jenis_prw = CONCAT("BJK",JPAWAL.kd_jenis_prw)
	SET 
			PL.kd_jenis_prw 					= JPTUJ.kd_jenis_prw, 
			PL.bagian_rs 							= JPTUJ.bagian_rs, 
			PL.bhp 										= JPTUJ.bhp, 
			PL.tarif_perujuk 					= JPTUJ.tarif_perujuk,
			PL.tarif_tindakan_dokter 	= JPTUJ.tarif_tindakan_dokter,
			PL.tarif_tindakan_petugas = JPTUJ.tarif_tindakan_petugas,
			PL.kso 										= JPTUJ.kso,
			PL.menejemen 							= JPTUJ.menejemen,
			PL.biaya 									= JPTUJ.total_byr
	where PL.no_rawat = norawat;


		# rubah biaya tindakan laborat
		# NOT FIX YET
		-- UPDATE detail_periksa_lab DP
		-- 	INNER JOIN template_laboratorium TLAWAL on TLAWAL.kd_jenis_prw = DP.kd_jenis_prw AND TLAWAL.id_template = DP.id_template
		-- 	INNER join template_laboratorium TLTUJ on TLTUJ.kd_jenis_prw = CONCAT("BJK",TLAWAL.kd_jenis_prw) AND TLTUJ.Pemeriksaan = TLAWAL.Pemeriksaan
		-- SET 
		-- 			DP.kd_jenis_prw 	= TLTUJ.kd_jenis_prw, 	
		-- 			DP.id_template 		= TLTUJ.id_template,
		-- 			DP.bagian_rs 			= TLTUJ.bagian_rs, DP.bagian_rs) ,			
		-- 			DP.bhp 						= TLTUJ.bhp, DP.bhp),
		-- 			DP.bagian_perujuk = TLTUJ.bagian_perujuk,	DP.bagian_perujuk),
		-- 			DP.bagian_dokter 	= TLTUJ.bagian_dokter, DP.bagian_dokter),
		-- 			DP.bagian_laborat = TLTUJ.bagian_laborat,	DP.bagian_laborat),
		-- 			DP.kso 						= TLTUJ.kso, DP.kso),
		-- 			DP.menejemen 			= TLTUJ.menejemen,	DP.menejemen),		
		-- 			DP.biaya_item 		= TLTUJ.biaya_item, DP.biaya_item)
		-- WHERE DP.no_rawat = norawat; 
		
		UPDATE detail_periksa_lab DP
			inner join template_laboratorium jpawal on DP.kd_jenis_prw = jpawal.kd_jenis_prw and DP.id_template= jpawal.id_template
			inner join template_laboratorium jptuj on jptuj.kd_jenis_prw = CONCAT("BJK",jpawal.kd_jenis_prw) and jptuj.Pemeriksaan = jpawal.Pemeriksaan
		SET 
					DP.kd_jenis_prw 	= jptuj.kd_jenis_prw,
					DP.id_template 		= jptuj.id_template,
					DP.bagian_rs 			= jptuj.bagian_rs,			
					DP.bhp 						= jptuj.bhp,
					DP.bagian_perujuk = jptuj.bagian_perujuk,
					DP.bagian_dokter 	= jptuj.bagian_dokter,
					DP.bagian_laborat = jptuj.bagian_laborat,
					DP.kso 						= jptuj.kso,
					DP.menejemen 			= jptuj.menejemen,
					DP.biaya_item 		= jptuj.biaya_item
	where DP.no_rawat = norawat;

select periksa_lab.*, jns_perawatan_lab.nm_perawatan 
from periksa_lab inner join jns_perawatan_lab on jns_perawatan_lab.kd_jenis_prw = periksa_lab.kd_jenis_prw
where periksa_lab.biaya <> 0 AND periksa_lab.no_rawat = norawat;


select detail_periksa_lab.*, template_laboratorium.Pemeriksaan
from detail_periksa_lab 
-- inner join jns_perawatan_lab on jns_perawatan_lab.kd_jenis_prw = periksa_lab.kd_jenis_prw
inner join template_laboratorium on template_laboratorium.kd_jenis_prw = detail_periksa_lab.kd_jenis_prw and template_laboratorium.id_template = detail_periksa_lab.id_template
where detail_periksa_lab.biaya_item <> 0 AND detail_periksa_lab.no_rawat = norawat;


select periksa_radiologi.*, jns_perawatan_radiologi.nm_perawatan
from periksa_radiologi inner join jns_perawatan_radiologi on jns_perawatan_radiologi.kd_jenis_prw = periksa_radiologi.kd_jenis_prw
where periksa_radiologi.no_rawat = norawat;


END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for Ubah_BPJSTK3_piutang_pasien
-- ----------------------------
DROP PROCEDURE IF EXISTS `Ubah_BPJSTK3_piutang_pasien`;
delimiter ;;
CREATE PROCEDURE `Ubah_BPJSTK3_piutang_pasien`(IN norawat VARCHAR(17) CHARACTER SET latin1 COLLATE latin1_swedish_ci)
BEGIN

	DECLARE totBilling DOUBLE;	
	SELECT SUM(totalbiaya) INTO totBilling from billing where no_rawat = norawat;

	#
	UPDATE piutang_pasien SET sisapiutang = totBilling, totalpiutang = totBilling where no_rawat = norawat;
	
	#
	UPDATE detail_piutang_pasien SET sisapiutang = totBilling, totalpiutang = totBilling where no_rawat = norawat;

	SELECT * from detail_piutang_pasien where no_rawat = norawat;
	SELECT * from piutang_pasien where no_rawat = norawat;

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for Ubah_BPJSTK4_ranap
-- ----------------------------
DROP PROCEDURE IF EXISTS `Ubah_BPJSTK4_ranap`;
delimiter ;;
CREATE PROCEDURE `Ubah_BPJSTK4_ranap`(norawat VARCHAR(20))
BEGIN
	
 	# hapus biaya pendaftaran untuk BPJS TK di tabel 'reg_periksa' 
	UPDATE reg_periksa 
	SET reg_periksa.biaya_reg = 0 
	WHERE reg_periksa.no_rawat = norawat;	
	
	# hapus biaya pendaftaran untuk BPJS TK di tabel 'billing'
	UPDATE billing 
	SET billing.totalbiaya = 0 
	WHERE billing.no_rawat = norawat AND billing.no like 'Registrasi';
	
	# rubah biaya tindakan dari pasien umum menjadi pasien BPJS TENAGA KERJA
-- 	UPDATE rawat_jl_dr
-- 			inner join jns_perawatan jpawal on rawat_jl_dr.kd_jenis_prw = jpawal.kd_jenis_prw
-- 			inner join jns_perawatan jptuj on jptuj.kd_jenis_prw = CONCAT("BJK",jpawal.kd_jenis_prw)
-- 	SET 
-- 			rawat_jl_dr.kd_jenis_prw = jptuj.kd_jenis_prw, 
-- 			rawat_jl_dr.material = jptuj.material, 
-- 			rawat_jl_dr.bhp = jptuj.bhp, 
-- 			rawat_jl_dr.tarif_tindakandr = jptuj.tarif_tindakandr,
-- 			rawat_jl_dr.biaya_rawat = jptuj.total_byrdrpr
-- 	where rawat_jl_dr.no_rawat = norawat; #AND jptuj.kd_pj like 'BJK';
	
	# rubah biaya tindakan dari pasien umum menjadi pasien BPJS TENAGA KERJA
-- 	UPDATE rawat_jl_drpr
-- 			inner join jns_perawatan jpawal on rawat_jl_drpr.kd_jenis_prw = jpawal.kd_jenis_prw
-- 			inner join jns_perawatan jptuj on jptuj.kd_jenis_prw = CONCAT("BJK",jpawal.kd_jenis_prw)
-- 	SET 
-- 			rawat_jl_drpr.kd_jenis_prw = jptuj.kd_jenis_prw, 
-- 			rawat_jl_drpr.material = jptuj.material, 
-- 			rawat_jl_drpr.bhp = jptuj.bhp, 
-- 			rawat_jl_drpr.tarif_tindakandr = jptuj.tarif_tindakandr,
-- 			rawat_jl_drpr.biaya_rawat = jptuj.total_byrdrpr
-- 	where rawat_jl_drpr.no_rawat = norawat; #AND jptuj.kd_pj like 'BJK';
	
-- 	

	SELECT reg_periksa.biaya_reg FROM reg_periksa WHERE reg_periksa.no_rawat = norawat;
	
	SELECT billing.totalbiaya FROM billing WHERE billing.no_rawat = norawat AND billing.no like 'Registrasi';

	select rawat_jl_dr.*, jpawal.kd_jenis_prw kdawal, jpawal.nm_perawatan, jptuj.kd_jenis_prw kdtuj, jptuj.nm_perawatan  
	from rawat_jl_dr 
			inner join jns_perawatan jpawal on rawat_jl_dr.kd_jenis_prw = jpawal.kd_jenis_prw
			LEFT join jns_perawatan jptuj on jptuj.kd_jenis_prw = CONCAT("BJK",jpawal.kd_jenis_prw)
	where rawat_jl_dr.no_rawat = norawat; #AND jptuj.kd_pj like 'BJK';

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for Ubah_BPJSTK4_ranaps
-- ----------------------------
DROP PROCEDURE IF EXISTS `Ubah_BPJSTK4_ranaps`;
delimiter ;;
CREATE PROCEDURE `Ubah_BPJSTK4_ranaps`(norawat VARCHAR(20))
BEGIN
	
	# hapus Biaya Pendaftaran Ranap untuk BPJS TK di tabel 'billing'
	UPDATE billing 
	SET billing.totalbiaya = 0,
			billing.biaya = 0,
			billing.jumlah = 0,
			billing.tambahan = 0
	WHERE billing.no_rawat = norawat and nm_perawatan = 'administrasi RI' and status = 'Ranap Paramedis';
	
	# ---------------------------------------------------
	# perubahan tarif ranap umum ke BJK
	# TABEL rawat_inap_dr 
UPDATE rawat_inap_dr
			inner join jns_perawatan_inap jpawal on rawat_inap_dr.kd_jenis_prw = jpawal.kd_jenis_prw
			inner join jns_perawatan_inap jptuj on jptuj.kd_jenis_prw = CONCAT("BJK",jpawal.kd_jenis_prw)
	SET 
			rawat_inap_dr.kd_jenis_prw = jptuj.kd_jenis_prw, 
			rawat_inap_dr.material = jptuj.material, 
			rawat_inap_dr.bhp = jptuj.bhp, 
			rawat_inap_dr.tarif_tindakandr = jptuj.tarif_tindakandr,
			rawat_inap_dr.biaya_rawat = jptuj.total_byrdr			
	where rawat_inap_dr.no_rawat = norawat; 
	
	# ---------------------------------------------------
	# TABEL rawat_inap_pr  
UPDATE rawat_inap_pr
			inner join jns_perawatan_inap jpawal on rawat_inap_pr.kd_jenis_prw = jpawal.kd_jenis_prw
			inner join jns_perawatan_inap jptuj on jptuj.kd_jenis_prw = CONCAT("BJK",jpawal.kd_jenis_prw)
	SET 
			rawat_inap_pr.kd_jenis_prw = jptuj.kd_jenis_prw, 
			rawat_inap_pr.material = jptuj.material, 
			rawat_inap_pr.bhp = jptuj.bhp, 
			rawat_inap_pr.tarif_tindakanpr = jptuj.tarif_tindakanpr,
			rawat_inap_pr.biaya_rawat = jptuj.total_byrpr			
	where rawat_inap_pr.no_rawat = norawat; 
	
	# ---------------------------------------------------
	# TABEL rawat_inap_drpr 
UPDATE rawat_inap_drpr
			inner join jns_perawatan_inap jpawal on rawat_inap_drpr.kd_jenis_prw = jpawal.kd_jenis_prw
			inner join jns_perawatan_inap jptuj on jptuj.kd_jenis_prw = CONCAT("BJK",jpawal.kd_jenis_prw)
	SET 
			rawat_inap_drpr.kd_jenis_prw = jptuj.kd_jenis_prw, 
			rawat_inap_drpr.material = jptuj.material, 
			rawat_inap_drpr.bhp = jptuj.bhp, 
			rawat_inap_drpr.tarif_tindakanpr = jptuj.tarif_tindakanpr,
			rawat_inap_drpr.biaya_rawat = jptuj.total_byrdrpr			
	where rawat_inap_drpr.no_rawat = norawat; 
	
-- select rawat_jl_dr.*, jns_perawatan.nm_perawatan 
-- 	from rawat_jl_dr inner join jns_perawatan on jns_perawatan.kd_jenis_prw = rawat_jl_dr.kd_jenis_prw 
-- 	where rawat_jl_dr.no_rawat = norawat;
		
	select rawat_inap_dr.*,jns_perawatan_inap.nm_perawatan 
	from rawat_inap_dr inner join jns_perawatan_inap on jns_perawatan_inap.kd_jenis_prw = rawat_inap_dr.kd_jenis_prw  
	where rawat_inap_dr.no_rawat = norawat;
	
	select rawat_inap_pr.*,jns_perawatan_inap.nm_perawatan 
	from rawat_inap_pr inner join jns_perawatan_inap on jns_perawatan_inap.kd_jenis_prw = rawat_inap_pr.kd_jenis_prw
	where rawat_inap_pr.no_rawat = norawat;
	
	select rawat_inap_drpr.*,jns_perawatan_inap.nm_perawatan 
	from rawat_inap_drpr inner join jns_perawatan_inap on jns_perawatan_inap.kd_jenis_prw = rawat_inap_drpr.kd_jenis_prw
	where rawat_inap_drpr.no_rawat = norawat;


END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for Ubah_BPJSTK4_ranap_copy1
-- ----------------------------
DROP PROCEDURE IF EXISTS `Ubah_BPJSTK4_ranap_copy1`;
delimiter ;;
CREATE PROCEDURE `Ubah_BPJSTK4_ranap_copy1`(norawat VARCHAR(20))
BEGIN
	
	# ---------------------------------------------------
	# perubahan tarif ranap umum ke BJK
	# TABEL rawat_inap_dr 
UPDATE rawat_inap_dr
			inner join jns_perawatan_inap jpawal on rawat_inap_dr.kd_jenis_prw = jpawal.kd_jenis_prw
			LEFT join jns_perawatan_inap jptuj on jptuj.kd_jenis_prw = CONCAT("BJK",jpawal.kd_jenis_prw)
	SET 
			rawat_inap_dr.kd_jenis_prw = jptuj.kd_jenis_prw, 
			rawat_inap_dr.material = jptuj.material, 
			rawat_inap_dr.bhp = jptuj.bhp, 
			rawat_inap_dr.tarif_tindakandr = jptuj.tarif_tindakandr,
			rawat_inap_dr.biaya_rawat = jptuj.total_byrdr			
	where rawat_inap_dr.no_rawat = norawat; 
	
	# ---------------------------------------------------
	# TABEL rawat_inap_pr  
UPDATE rawat_inap_pr
			inner join jns_perawatan_inap jpawal on rawat_inap_pr.kd_jenis_prw = jpawal.kd_jenis_prw
			LEFT join jns_perawatan_inap jptuj on jptuj.kd_jenis_prw = CONCAT("BJK",jpawal.kd_jenis_prw)
	SET 
			rawat_inap_dr.kd_jenis_prw = jptuj.kd_jenis_prw, 
			rawat_inap_dr.material = jptuj.material, 
			rawat_inap_dr.bhp = jptuj.bhp, 
			rawat_inap_dr.tarif_tindakanpr = jptuj.tarif_tindakanpr,
			rawat_inap_dr.biaya_rawat = jptuj.total_byrpr			
	where rawat_inap_pr.no_rawat = norawat; 
	
	# ---------------------------------------------------
	# TABEL rawat_inap_drpr 
UPDATE rawat_inap_drpr
			inner join jns_perawatan_inap jpawal on rawat_inap_drpr.kd_jenis_prw = jpawal.kd_jenis_prw
			LEFT join jns_perawatan_inap jptuj on jptuj.kd_jenis_prw = CONCAT("BJK",jpawal.kd_jenis_prw)
	SET 
			rawat_inap_dr.kd_jenis_prw = jptuj.kd_jenis_prw, 
			rawat_inap_dr.material = jptuj.material, 
			rawat_inap_dr.bhp = jptuj.bhp, 
			rawat_inap_dr.tarif_tindakanpr = jptuj.tarif_tindakanpr,
			rawat_inap_dr.biaya_rawat = jptuj.total_byrdrpr			
	where rawat_inap_drpr.no_rawat = norawat; 
	
	


END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for Ubah_BPJSTK5_Obat
-- ----------------------------
DROP PROCEDURE IF EXISTS `Ubah_BPJSTK5_Obat`;
delimiter ;;
CREATE PROCEDURE `Ubah_BPJSTK5_Obat`(IN p_no_rawat VARCHAR(17) CHARACTER SET latin1 COLLATE latin1_swedish_ci, IN p_jenis VARCHAR(10))
BEGIN
		DECLARE v_total VARCHAR(50);
		
    -- 1. Update data detail_pemberian_obat ---------------------------
    UPDATE detail_pemberian_obat dpo
			INNER JOIN dt_barang_tk dbt 
					ON dbt.kode_brng = dpo.kode_brng
			SET 
					dpo.biaya_obat = dbt.harga,
					dpo.total = ROUND(dbt.harga * dpo.jml)
			WHERE dpo.no_rawat = p_no_rawat;

-- 		2. Tampilkan jumlah baris terupdate -----------------------------
    UPDATE resep_pulang rpul
			INNER JOIN dt_barang_tk dbt 
					ON dbt.kode_brng = rpul.kode_brng
			SET 
					rpul.harga = dbt.harga,
					rpul.total = ROUND(dbt.harga * rpul.jml_barang)
			WHERE rpul.no_rawat = p_no_rawat;						
		
		-- 3. Update data billing -------------------------------------------
		UPDATE billing b
			INNER JOIN databarang dtb ON dtb.nama_brng = TRIM(REGEXP_REPLACE(b.nm_perawatan,' \\([^()]*\\)$',''))
			INNER JOIN dt_barang_tk dbtk on dbtk.kode_brng = dtb.kode_brng
			SET 
					b.biaya = dbtk.harga,
					b.totalbiaya = (dbtk.harga * b.jumlah) + b.tambahan
			WHERE b.no_rawat = p_no_rawat AND b.status = 'Obat';
			
		-- 5. Update data TOTAL OBAT billing --------------------------------
    SELECT FORMAT(IFNULL(SUM(totalbiaya),0),0)
    INTO v_total
    FROM billing
    WHERE no_rawat = p_no_rawat
    AND status = 'Obat';

    -- Jika RANAP → tambahkan teks
    IF UPPER(p_jenis) = 'RANAP' THEN
        SET v_total = CONCAT('Total Obat & BHP : ', v_total);
    END IF;

    -- Update baris TtlObat
    UPDATE billing
    SET nm_perawatan = v_total
    WHERE no_rawat = p_no_rawat
    AND status = 'TtlObat';
		
    -- 6. Tampilkan hasil setelah update ----------------------------------
    SELECT 
        dpo.no_rawat,
        dpo.kode_brng,
        dpo.biaya_obat,
        dpo.jml,
        dpo.total
    FROM detail_pemberian_obat dpo
    WHERE dpo.no_rawat = p_no_rawat;
		
		-- 7. Tampilkan hasil setelah update BILLING -------------------------
		SELECT 
				b.no_rawat, 
				b.tgl_byr, 
				b.no, 
				dtb.kode_brng, 
				b.nm_perawatan, 
				b.biaya, 
				dbtk.harga as hrg_tk,
				b.jumlah, 
				b.totalbiaya, 
				ROUND( (dbtk.harga * b.jumlah) + b.tambahan) as total_tk,
				b.status
		FROM billing b
		INNER JOIN databarang dtb 
				ON dtb.nama_brng = 
					 TRIM(REGEXP_REPLACE(b.nm_perawatan, ' \\([^()]*\\)$', ''))
		INNER JOIN dt_barang_tk dbtk on dbtk.kode_brng = dtb.kode_brng
		WHERE b.no_rawat = p_no_rawat
		AND b.status = 'Obat';

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for Ubah_BPJSTK7_hargaObat
-- ----------------------------
DROP PROCEDURE IF EXISTS `Ubah_BPJSTK7_hargaObat`;
delimiter ;;
CREATE PROCEDURE `Ubah_BPJSTK7_hargaObat`(IN nm_obate VARCHAR(200), IN jumlah INTEGER)
BEGIN
	
	select 
					dtb.kode_brng, 
					dtb.nama_brng, 
					dbt.harga as hrg_tk, jumlah, 
					ROUND(dbt.harga * jumlah) as total_tk
	from databarang dtb
	INNER JOIN dt_barang_tk dbt on dbt.kode_brng = dtb.kode_brng
	where dtb.nama_brng like CONCAT(TRIM(nm_obate), '%');
	
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for Ubah_BPJSTK7_Obat_Retur
-- ----------------------------
DROP PROCEDURE IF EXISTS `Ubah_BPJSTK7_Obat_Retur`;
delimiter ;;
CREATE PROCEDURE `Ubah_BPJSTK7_Obat_Retur`(IN p_no_rawat VARCHAR(30))
BEGIN
	
			UPDATE detreturjual drj
			INNER JOIN dt_barang_tk dbt ON dbt.kode_brng = drj.kode_brng
			SET 
					drj.h_retur = dbt.harga,
					drj.subtotal = ROUND(dbt.harga * drj.jml_retur)
			WHERE drj.no_retur_jual LIKE CONCAT('%', p_no_rawat, '%');

			select 
						drj.no_retur_jual, 
						drj.kode_brng, 
						databarang.nama_brng, 
						drj.jml_retur, 
						drj.h_retur, 
						drj.subtotal, 
						dbt.harga, 
						ROUND(dbt.harga * drj.jml_retur) as total_tk 
			from detreturjual drj
			INNER JOIN databarang on databarang.kode_brng = drj.kode_brng
			INNER JOIN dt_barang_tk dbt on dbt.kode_brng = drj.kode_brng
			where drj.no_retur_jual like CONCAT('%', p_no_rawat, '%');
	
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for UBAH_KELAS
-- ----------------------------
DROP PROCEDURE IF EXISTS `UBAH_KELAS`;
delimiter ;;
CREATE PROCEDURE `UBAH_KELAS`(norawat VARCHAR(20), klasTujuan VARCHAR(5))
BEGIN
	
	# ---------------------------------------------------
	# perubahan tarif ranap umum ke BJK
	# TABEL rawat_inap_dr
	UPDATE rawat_inap_dr
			INNER JOIN jns_perawatan_inap jpawal on rawat_inap_dr.kd_jenis_prw = jpawal.kd_jenis_prw
		  INNER JOIN jns_perawatan_inap jptuj  on jptuj.nm_perawatan = jpawal.nm_perawatan AND jptuj.kelas = CONCAT("Kelas ",klasTujuan) AND LEFT(jptuj.kd_jenis_prw,3) <>  "BJK"
	SET 
			rawat_inap_dr.kd_jenis_prw = jptuj.kd_jenis_prw, 
			rawat_inap_dr.material = jptuj.material, 
			rawat_inap_dr.bhp = jptuj.bhp, 
			rawat_inap_dr.tarif_tindakandr = jptuj.tarif_tindakandr,
			rawat_inap_dr.biaya_rawat = jptuj.total_byrdr			
	where rawat_inap_dr.no_rawat = norawat;

	# ---------------------------------------------------
	# TABEL rawat_inap_pr  
	UPDATE rawat_inap_pr
				INNER JOIN jns_perawatan_inap jpawal on rawat_inap_pr.kd_jenis_prw = jpawal.kd_jenis_prw
		    INNER JOIN jns_perawatan_inap jptuj  on jptuj.nm_perawatan = jpawal.nm_perawatan AND jptuj.kelas = CONCAT("Kelas ",klasTujuan) AND LEFT(jptuj.kd_jenis_prw,3) <>  "BJK"
		SET 
				rawat_inap_pr.kd_jenis_prw = jptuj.kd_jenis_prw, 
				rawat_inap_pr.material = jptuj.material, 
				rawat_inap_pr.bhp = jptuj.bhp, 
				rawat_inap_pr.tarif_tindakanpr = jptuj.tarif_tindakanpr,
				rawat_inap_pr.biaya_rawat = jptuj.total_byrpr			
		where rawat_inap_pr.no_rawat = norawat; 
	
	# ---------------------------------------------------
	# TABEL rawat_inap_drpr 
	UPDATE rawat_inap_drpr
				INNER JOIN jns_perawatan_inap jpawal on rawat_inap_drpr.kd_jenis_prw = jpawal.kd_jenis_prw
		    INNER JOIN jns_perawatan_inap jptuj  on jptuj.nm_perawatan = jpawal.nm_perawatan AND jptuj.kelas = CONCAT("Kelas ",klasTujuan) AND LEFT(jptuj.kd_jenis_prw,3) <>  "BJK"
		SET 
				rawat_inap_drpr.kd_jenis_prw = jptuj.kd_jenis_prw, 
				rawat_inap_drpr.material = jptuj.material, 
				rawat_inap_drpr.bhp = jptuj.bhp, 
				rawat_inap_drpr.tarif_tindakanpr = jptuj.tarif_tindakanpr,
				rawat_inap_drpr.biaya_rawat = jptuj.total_byrdrpr			
		where rawat_inap_drpr.no_rawat = norawat; 

-- 		SELECT 
-- 					rawat_inap_dr.no_rawat, jpawal.kd_jenis_prw, jpawal.nm_perawatan, jpawal.kelas, jpawal.total_byrdr byrAwal,
-- 					jptuj.kd_jenis_prw, jptuj.nm_perawatan, jptuj.kelas, jptuj.total_byrdr byrTujuan
-- 		FROM rawat_inap_dr
-- 		INNER JOIN jns_perawatan_inap jpawal on rawat_inap_dr.kd_jenis_prw = jpawal.kd_jenis_prw
-- 		INNER JOIN jns_perawatan_inap jptuj  on jptuj.nm_perawatan = jpawal.nm_perawatan AND jptuj.kelas = CONCAT("Kelas ",klasTujuan) AND LEFT(jptuj.kd_jenis_prw,3) <>  "BJK"
-- 		WHERE rawat_inap_dr.no_rawat = norawat;
		
		select * from rawat_inap_dr where no_rawat = norawat;
		select * from rawat_inap_pr where no_rawat = norawat;
		select * from rawat_inap_drpr where no_rawat = norawat;
END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for ubah_PLN_ralan
-- ----------------------------
DROP PROCEDURE IF EXISTS `ubah_PLN_ralan`;
delimiter ;;
CREATE PROCEDURE `ubah_PLN_ralan`(norawat VARCHAR(20))
BEGIN
	
	DECLARE totBilling DOUBLE;
	
	-- Update baris Pendaftaran
    UPDATE billing
    SET totalbiaya = '20000'
    WHERE no_rawat = norawat
    AND status = 'Registrasi';

	-- ubah piutang		
	SELECT SUM(totalbiaya) INTO totBilling from billing where no_rawat = norawat;

	#
	UPDATE piutang_pasien SET sisapiutang = totBilling, totalpiutang = totBilling where no_rawat = norawat;
	
	#
	UPDATE detail_piutang_pasien SET sisapiutang = totBilling, totalpiutang = totBilling where no_rawat = norawat;

	SELECT * from detail_piutang_pasien where no_rawat = norawat;
	SELECT * from piutang_pasien where no_rawat = norawat;	

END
;;
delimiter ;

-- ----------------------------
-- Procedure structure for ubah_Resep_insertItemObat
-- ----------------------------
DROP PROCEDURE IF EXISTS `ubah_Resep_insertItemObat`;
delimiter ;;
CREATE PROCEDURE `ubah_Resep_insertItemObat`(p_norawat VARCHAR(20),p_kelas VARCHAR(20),p_kodeObat VARCHAR(30),p_jumlah DOUBLE)
BEGIN
			DECLARE v_noresep VARCHAR(30);
			DECLARE v_tanggal DATE;
			DECLARE v_jam TIME;
-- 			DECLARE v_kls VARCHAR(25);
			DECLARE v_kd_barang VARCHAR(25);
			DECLARE v_nm_barang VARCHAR(125);
			DECLARE v_h_beli DOUBLE;
			DECLARE v_tarif DOUBLE;
-- 			DECLARE v_jml DOUBLE;
			DECLARE v_tot DOUBLE;
			
			-- ambil salah satu nomor resep untuk di susupkan data obat baru
			SELECT no_resep, tgl_perawatan, jam INTO v_noresep, v_tanggal, v_jam
			from (
				select no_resep, tgl_perawatan, jam from resep_obat
				where no_rawat = p_norawat
			) as x ORDER BY RAND() limit 1;
			
			-- cari obat, dan ambil harganya
			SELECT 
					kode_brng,
					nama_brng,
					h_beli,
					CASE p_kelas
							WHEN 'kelas 1' THEN kelas1
							WHEN 'kelas 2' THEN kelas2
							WHEN 'kelas 3' THEN kelas3
							WHEN 'kelas utama' THEN utama
							WHEN 'kelas ralan' THEN ralan
							WHEN 'kelas vip' THEN vip
							WHEN 'kelas vvip' THEN vvip
					END AS tarif
					INTO v_kd_barang, v_nm_barang, v_h_beli, v_tarif
			FROM databarang
			WHERE kode_brng = p_kodeObat;
			
			-- susupkan item obat ke resep dokter
			INSERT INTO resep_dokter ( no_resep, kode_brng, jml, aturan_pakai ) VALUES ( v_noresep, v_kd_barang, p_jumlah, '' ); 
			
			
			-- masukkan semua modifikasi ke dalam tabel detail_pemberian_obat
			INSERT INTO detail_pemberian_obat (
						tgl_perawatan,
						jam,
						no_rawat,
						kode_brng,
						h_beli,
						biaya_obat,
						jml,
						embalase,
						tuslah,
						total,
						status,
						kd_bangsal,
						no_batch,
						no_faktur						
			)
			select 
						tgl_perawatan,
						jam,
						no_rawat,
						v_kd_barang,
						v_h_beli,
						v_tarif,
						p_jumlah,
						embalase,
						tuslah,
						p_jumlah * v_tarif as total,
						status,
						kd_bangsal,
						no_batch,
						no_faktur 
			from detail_pemberian_obat 
			where no_rawat = p_norawat AND tgl_perawatan = v_tanggal AND jam = v_jam limit 1; 
			
			select
						v_noresep 					as noResep,
						v_tanggal 					as Tanggal,
						v_jam 							as Jam,
						v_kd_barang 				as kd_Barang,
						v_nm_barang 				as nm_barang,
						v_h_beli 						as harga_beli,
						v_tarif							as harga_jual,
						p_jumlah 						as jumlah,
						p_jumlah * v_tarif 	as Total;

END
;;
delimiter ;

