-- ----------------------------
DROP TRIGGER IF EXISTS `kamar_inap_AU`;
delimiter ;;
CREATE TRIGGER `kamar_inap_AU` AFTER UPDATE ON `kamar_inap` FOR EACH ROW begin
/*
