-- ----------------------------
DROP TRIGGER IF EXISTS `pemeriksaan_ralan_AI`;
delimiter ;;
CREATE TRIGGER `pemeriksaan_ralan_AI` AFTER INSERT ON `pemeriksaan_ralan` FOR EACH ROW begin
	
	set		@param_pemeriksaan_ralan	=	json_object(
													'tx',			'+taskid',
													'jenis',			'trigger',
													'nama',		'pemeriksaan_ralan_AI',
													'norawat',		NEW.no_rawat
													);
	call 	rsb221022021_1jkn.pxAAntrol(@param_pemeriksaan_ralan);
	
	
	call 	rsb221022021_1jkn.pxAntrol_Tugas_Picu(json_object(
			'tabel',	'pemeriksaan_ralan',
			'picu',		'pemeriksaan_ralan_AI',
			'tugas',	'taskid',
			'norawat',	NEW.no_rawat,
			'waktu',	TIMESTAMPADD(hour,1,timestamp(now()))) 
			);
	
end
;;
