-- ----------------------------
-- Triggers structure for table zzz1wa
-- ----------------------------
DROP TRIGGER IF EXISTS `zzz1wa_BI`;
delimiter ;;
CREATE TRIGGER `zzz1wa_BI` BEFORE INSERT ON `zzz1wa` FOR EACH ROW BEGIN
	if	(ifnull((select count(a.id) from rsb221022021.zzz1wa partition(A) a where a.data = NEW.data),0)) > 0 then
		set	NEW.partisi = 'Z',
			NEW.uuid	   = (select a.uuid from rsb221022021.zzz1wa partition (A) a where a.data = NEW.data order by a.id limit 1);
	end if
	;
END
;;
delimiter ;

